OPOSICIONES.push({"id": "getxo-kirolak-auxiliar", "nombre": "Auxiliar Administrativo/a · Getxo Kirolak", "sub": "3 plazas, C2, laboral fijo. BOB nº 143, 29/07/2026. 20 temas.", "temas": [{"id": "t01", "sig": "Tema 1", "titulo": "Tema 1. La Constitución Española: derechos y deberes fundamentales", "sub": "Título I de la Constitución. Preguntas de la batería oficial de Getxo Kirolak (primera prueba).", "preguntas": [{"id": "gett01q01", "q": "Según lo establecido en el artículo 10 de la Constitución Española de 1978, ¿cuál de las siguientes cuestiones es fundamento del orden político y de la paz social?:", "o": ["La dignidad de la persona.", "El libre desarrollo de la personalidad.", "El respeto a la ley y a los derechos de los demás.", "Todas las respuestas anteriores son correctas."], "e": "Art. 10.1: la dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social.", "r": "CE art. 10 · batería oficial, pregunta 1", "c": 3}, {"id": "gett01q02", "q": "Según lo establecido en el artículo 11 y 12 de la Constitución Española de 1978, ¿cuál de las siguientes cuestiones es INCORRECTA?:", "o": ["La nacionalidad española se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley.", "Los españoles de origen pueden ser privados de su nacionalidad.", "Los españoles son mayores de edad a los dieciocho años.", "El Estado podrá concertar tratados de doble nacionalidad con los países iberoamericanos o con aquellos que hayan tenido o tengan una particular vinculación con España."], "e": "Art. 11.2: ningún español de origen podrá ser privado de su nacionalidad.", "r": "CE art. 11 y 12 · batería oficial, pregunta 2", "c": 1}, {"id": "gett01q03", "q": "De conformidad con el artículo 13 de la Constitución Española de 1978, ¿quiénes serán titulares de los derechos reconocidos en el artículo 23 de la Constitución Española?:", "o": ["Solamente las personas españolas serán reconocidas titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.", "Solamente las personas que residan en España, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones generales.", "Solamente las personas españolas, sin excepciones.", "Solamente las personas españolas y las personas ciudadanas de la Unión Europea, salvo excepciones para el derecho de sufragio pasivo en las elecciones municipales, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales."], "e": "Es el texto literal del artículo.", "r": "CE art. 13 · batería oficial, pregunta 3", "c": 0}, {"id": "gett01q04", "q": "Conforme al artículo 14 de la Constitución Española de 1978, señale la afirmación correcta:", "o": ["Los ciudadanos extranjeros gozarán de los mismos derechos que los españoles sin excepción.", "Solo las personas con nacionalidad española son iguales ante la ley.", "Los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.", "La ley podrá establecer excepciones al principio de igualdad en función de la utilidad pública."], "e": "Es el texto literal del artículo.", "r": "CE art. 14 · batería oficial, pregunta 4", "c": 2}, {"id": "gett01q05", "q": "De acuerdo con la Constitución Española de 1978, indique cuál de las siguientes afirmaciones es INCORRECTA en relación con el artículo 15:", "o": ["Todos tienen derecho a la vida y a la integridad física y moral", "Queda abolida la pena de muerte, salvo en los supuestos previstos en las leyes penales militares para tiempos de guerra.", "Se permite la tortura si está legalmente justificada.", "En ningún caso, podrán ser sometidos a tortura ni a penas o tratos inhumanos o degradantes."], "e": "Art. 15: en ningún caso pueden ser sometidos a tortura ni a penas o tratos inhumanos o degradantes.", "r": "CE art. 15 · batería oficial, pregunta 5", "c": 2}, {"id": "gett01q06", "q": "Siguiendo lo dispuesto en el artículo 16 de la Constitución Española de 1978, señale la respuesta correcta:", "o": ["Se garantiza la libertad ideológica, religiosa y de culto de los individuos y las comunidades sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.", "La ciudadanía podrá ser obligada a declarar sobre su ideología, religión o creencias.", "La confesión católica tendrá carácter estatal, aun así, los poderes públicos tendrán en cuenta las creencias religiosas de la sociedad española y mantendrán las consiguientes relaciones de cooperación con las demás confesiones.", "La confesión católica tendrá carácter estatal y los poderes públicos evitarán relacionarse con las demás confesiones."], "e": "Es el texto literal del artículo.", "r": "CE art. 16 · batería oficial, pregunta 6", "c": 0}, {"id": "gett01q07", "q": "Según el artículo 17 de la Constitución Española, señale la opción correcta en relación con el procedimiento de “habeas corpus”:", "o": ["Se trata de una figura jurídica que permite revisar la legalidad de las sentencias condenatorias.", "Es un procedimiento exclusivo de la jurisdicción militar.", "Es un procedimiento regulado por ley para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente.", "Solo es aplicable en casos de detención en flagrante delito."], "e": "Es el texto literal del artículo.", "r": "CE art. 17 · batería oficial, pregunta 7", "c": 2}, {"id": "gett01q08", "q": "Siguiendo con el artículo 17 de la Constitución Española, ¿qué se debe comunicar a toda persona detenida?", "o": ["La causa de su detención y el nombre del denunciante.", "Los delitos que se le imputan y el nombre del/la juez/a instructor/a.", "Sus derechos y las razones de su detención, de forma inmediata y comprensible.", "Su obligación de declarar ante la autoridad judicial en un plazo de 72 horas."], "e": "Es el texto literal del artículo.", "r": "CE art. 17 · batería oficial, pregunta 8", "c": 2}, {"id": "gett01q09", "q": "Conforme al artículo 18.3 de la Constitución Española de 1978, se garantiza el secreto de las comunicaciones y, en especial, de las postales, telegráficas y telefónicas:", "o": ["Salvo, resolución administrativa.", "No se garantiza el secreto de las comunicaciones.", "Salvo, resolución judicial.", "Salvo, resolución judicial o administrativa, indistintamente."], "e": "Es el texto literal del artículo.", "r": "CE art. 18.3 · batería oficial, pregunta 9", "c": 2}, {"id": "gett01q10", "q": "¿Cuál de los siguientes derechos se reconoce a los españoles según el artículo 19 de la Constitución Española?", "o": ["Solamente el derecho a residir en el lugar asignado por la autoridad competente dentro del territorio nacional.", "El derecho a elegir libremente su residencia y a circular por el territorio nacional.", "El derecho a residir en cualquier país de la Unión Europea sin restricciones.", "El derecho a circular y residir libremente por el territorio nacional, pero solo con autorización administrativa."], "e": "Es el texto literal del artículo.", "r": "CE art. 19 · batería oficial, pregunta 10", "c": 1}, {"id": "gett01q11", "q": "De conformidad con el artículo 20 de la Constitución Española de 1978, ¿cuál de estos derechos NO se recoge en dicho artículo?:", "o": ["A expresar y difundir libremente los pensamientos, ideas y opiniones mediante la palabra, el escrito o cualquier otro medio de reproducción.", "A la producción y creación literaria, artística, científica y técnica.", "A fundar sindicatos que promuevan la libertad de expresión.", "A comunicar o recibir libremente información veraz por cualquier medio de difusión."], "e": "Las demás opciones reproducen el texto del artículo.", "r": "CE art. 20 · batería oficial, pregunta 11", "c": 2}, {"id": "gett01q12", "q": "El artículo 20.3 de la Constitución Española establece que la ley regulará la organización y el control parlamentario de:", "o": ["Los medios de comunicación social más significativos, garantizando el acceso a los mismos de los grupos sociales significativos.", "Todos los medios de comunicación social.", "Los medios de comunicación social dependientes del Estado o de cualquier ente público.", "Los medios de comunicación social más significativos, respetando el pluralismo de la sociedad."], "e": "Art. 20.3: medios dependientes del Estado o de cualquier ente público; la ley garantiza el acceso a ellos de los grupos sociales y políticos significativos.", "r": "CE art. 20.3 · batería oficial, pregunta 12", "c": 2}, {"id": "gett01q13", "q": "De acuerdo con el artículo 21 de la Constitución Española de 1978, sobre el derecho de reunión:", "o": ["Se reconoce el derecho de reunión pacífica y sin armas. El ejercicio de este derecho necesitará autorización previa.", "En los casos de reuniones en lugares de tránsito público y manifestaciones no se dará comunicación previa a la autoridad.", "Las manifestaciones podrán ser prohibidas cuando existan razones fundadas de alteración del orden público.", "Se reconoce el derecho de reunión pacífica y con armas. El ejercicio de este derecho no necesitará autorización previa."], "e": "Art. 21: no necesita autorización previa; en lugares de tránsito público se da comunicación previa, y solo se pueden prohibir si hay razones fundadas de alteración del orden público con peligro para personas o bienes.", "r": "CE art. 21 · batería oficial, pregunta 13", "c": 2}, {"id": "gett01q14", "q": "Conforme al artículo 22 de la Constitución Española, las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de:", "o": ["Resolución judicial motivada.", "Resolución administrativa motivada.", "Orden gubernativa motivada.", "No podrán ser disueltas."], "e": "Es el texto literal del artículo.", "r": "CE art. 22 · batería oficial, pregunta 14", "c": 0}, {"id": "gett01q15", "q": "Según el artículo 23 de la Constitución Española, señale cuál de los siguientes derechos se reconoce a los ciudadanos:", "o": ["Únicamente el derecho a votar en las elecciones generales.", "El derecho a participar en los asuntos públicos, directamente o por medio de representantes, libremente elegidos en elecciones periódicas por sufragio universal.", "El derecho a participar en la política únicamente a través de los partidos políticos.", "El derecho a participar en los asuntos públicos exclusivamente mediante consultas populares."], "e": "Es el texto literal del artículo.", "r": "CE art. 23 · batería oficial, pregunta 15", "c": 1}, {"id": "gett01q16", "q": "Los/as ciudadanos/as tienen derecho a acceder a los cargos públicos (artículo 23.2 de la Constitución Española):", "o": ["Únicamente mediante designación directa de los poderes públicos.", "En condiciones de igualdad, con los requisitos que señalen las leyes.", "Sólo si pertenecen a un partido político legalmente constituido.", "Siempre que hayan superado una oposición general convocada por el Estado."], "e": "Es el texto literal del artículo.", "r": "CE art. 23.2 · batería oficial, pregunta 16", "c": 1}, {"id": "gett01q17", "q": "Atendiendo al artículo 24.2 de la Constitución Española, señale cuál de los siguientes derechos procesales NO se menciona expresamente:", "o": ["El derecho al Juez ordinario predeterminado por la ley.", "El derecho a no declarar contra sí mismo.", "El derecho a la doble instancia judicial.", "El derecho a la presunción de inocencia."], "e": "El art. 24.2 no menciona la doble instancia.", "r": "CE art. 24.2 · batería oficial, pregunta 17", "c": 2}, {"id": "gett01q18", "q": "El principio de legalidad regulado en el artículo 25.1 de la Constitución Española, implica que:", "o": ["Nadie podrá ser condenado o sancionado por acciones u omisiones que en el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente en aquel momento.", "Nadie podrá ser condenado o sancionado por acciones u omisiones que en el momento de producirse constituyan delito, falta o infracción administrativa, según la legislación vigente en aquel momento.", "Podrá ser sancionada una persona por la comisión de una falta, aun cuando no constituya infracción penal en el momento de producirse, siempre que si lo sea al dictarse sentencia.", "Podrá ser sancionada una persona por la comisión de una infracción administrativa, aun cuando no constituya conducta sancionable en el momento de producirse."], "e": "Es el texto literal del artículo.", "r": "CE art. 25.1 · batería oficial, pregunta 18", "c": 0}, {"id": "gett01q19", "q": "Según el artículo 26 de la Constitución Española, ¿qué se prohíbe expresamente?", "o": ["Los tribunales militares en tiempos de paz.", "La creación de órganos jurisdiccionales no dependientes del Poder Judicial.", "Los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.", "Los Tribunales Constitucionales autonómicos."], "e": "Es el texto literal del artículo.", "r": "CE art. 26 · batería oficial, pregunta 19", "c": 2}, {"id": "gett01q20", "q": "En base al artículo 27 de la Constitución Española, la educación tendrá por objeto:", "o": ["El pleno desarrollo de la personalidad humana conforme a los planes educativos aprobados por el Consejo Escolar Nacional a instancia de las Asociaciones Nacionales de Padres de Alumnos.", "El pleno desarrollo de la personalidad humana en el respeto de los principios democráticos de convivencia, y a los derechos y libertades culturales.", "El desarrollo de la personalidad humana conforme a las líneas educativas marcadas por el Consejo Escolar Nacional.", "El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia, y a los derechos y libertades fundamentales."], "e": "Es el texto literal del artículo.", "r": "CE art. 27 · batería oficial, pregunta 20", "c": 3}, {"id": "gett01q21", "q": "Señale la respuesta INCORRECTA, de acuerdo con el artículo 27 de la Constitución Española de 1978:", "o": ["La enseñanza básica es obligatoria y gratuita.", "Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.", "Los poderes públicos podrán garantizar el derecho que asiste a los padres para que sus hijos reciban la formación en los centros docentes, en los términos que la ley establezca.", "La educación tendrá por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales."], "e": "Art. 27.3: los poderes públicos garantizan el derecho de los padres a que sus hijos reciban la formación religiosa y moral acorde con sus convicciones. No es «podrán garantizar».", "r": "CE art. 27 · batería oficial, pregunta 21", "c": 2}, {"id": "gett01q22", "q": "De conformidad con el artículo 28 de la Constitución Española, ¿quiénes tienen derecho a sindicarse libremente?", "o": ["Sólo los/as trabajadores/as del sector privado.", "Únicamente los ciudadanos españoles en edad laboral.", "Todos, con las limitaciones que establezca la ley para las Fuerzas Armadas y Cuerpos sometidos a disciplina militar.", "Sólo los/as trabajadores/as por cuenta ajena y los/as funcionarios/as de carrera."], "e": "Es el texto literal del artículo.", "r": "CE art. 28 · batería oficial, pregunta 22", "c": 2}, {"id": "gett01q23", "q": "Según el artículo 29.1 de la Constitución Española, ¿cómo puede ejercerse el derecho de petición?", "o": ["Verbalmente o por escrito, en función del interés público del asunto.", "De forma individual o colectiva, por escrito, en la forma y con los efectos que determine la ley.", "Sólo de manera colectiva y mediante representación legal.", "Sólo por vía administrativa, a través de sindicatos o asociaciones."], "e": "Es el texto literal del artículo.", "r": "CE art. 29.1 · batería oficial, pregunta 23", "c": 1}, {"id": "gett01q24", "q": "De acuerdo con el artículo 29.2 de la Constitución Española, ¿cómo pueden ejercer el derecho de petición los miembros de las Fuerzas Armadas o cuerpos sometidos a disciplina militar?", "o": ["Sólo de forma colectiva y bajo supervisión del mando.", "Por cualquier medio que establezca el reglamento disciplinario interno.", "Sólo individualmente y conforme a lo dispuesto en su legislación específica.", "Exclusivamente a través de sus representantes legales."], "e": "Es el texto literal del artículo.", "r": "CE art. 29.2 · batería oficial, pregunta 24", "c": 2}, {"id": "gett01q25", "q": "Atendiendo a lo dispuesto en el artículo 30.1 de la Constitución Española, ¿cuál de las siguientes afirmaciones es correcta?", "o": ["Los españoles tienen el deber, pero no el derecho, de defender a España.", "Los españoles tienen el derecho y el deber de defender a España.", "La defensa de España es competencia exclusiva de las Fuerzas Armadas.", "Los ciudadanos podrán defender a España solo si así lo establece una ley específica."], "e": "Es el texto literal del artículo.", "r": "CE art. 30.1 · batería oficial, pregunta 25", "c": 1}, {"id": "gett01q26", "q": "Conforme al artículo 30.4 de la Constitución Española, ¿qué podrá regularse mediante ley?", "o": ["Los deberes cívicos relacionados con el ejercicio del derecho al voto.", "La creación de una red ciudadana voluntaria para emergencias.", "Los deberes de los ciudadanos en casos de grave riesgo, catástrofe o calamidad pública.", "La participación de los ciudadanos en las misiones internacionales."], "e": "Es el texto literal del artículo.", "r": "CE art. 30.4 · batería oficial, pregunta 26", "c": 2}, {"id": "gett01q27", "q": "En base a lo previsto en el artículo 31 de la Constitución Española de 1978, señale la respuesta correcta respecto a los principios tributarios que se recogen en el mismo:", "o": ["Todos contribuirán al sostenimiento de los gastos públicos de acuerdo con su capacidad económica mediante un sistema tributario justo inspirado en los principios de igualdad, mérito y capacidad, y en casos excepcionales previsto en la Constitución, tendrá alcance confiscatorio.", "El gasto público realizará una asignación equitativa de los recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.", "Sólo podrán establecerse prestaciones personales o patrimoniales de carácter privado con arreglo a la ley.", "Todas las respuestas anteriores son correctas."], "e": "Art. 31.2. El 31.1 habla de igualdad y progresividad y prohíbe en todo caso el alcance confiscatorio; el 31.3, de prestaciones de carácter público.", "r": "CE art. 31 · batería oficial, pregunta 27", "c": 1}, {"id": "gett01q28", "q": "Una de las siguientes afirmaciones es INCORRECTA:", "o": ["La Constitución establece que la ley regulará las causas de separación y disolución del matrimonio.", "La Constitución establece que el hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.", "La Constitución delega en la Ley la concreción de los derechos y deberes de los cónyuges.", "La Constitución admite que no regulará la edad y la capacidad del hombre y la mujer para contraer matrimonio."], "e": "Art. 32.2: la ley regulará las formas de matrimonio, la edad y capacidad para contraerlo, los derechos y deberes de los cónyuges y las causas de separación y disolución.", "r": "CE · batería oficial, pregunta 28", "c": 3}, {"id": "gett01q29", "q": "¿Qué derechos se reconocen expresamente en el artículo 33.1 de la Constitución Española?", "o": ["El derecho a la propiedad privada únicamente.", "El derecho a la propiedad colectiva y a la sucesión universal.", "El derecho a la propiedad privada y a la herencia.", "El derecho a poseer bienes inmuebles con autorización judicial."], "e": "Es el texto literal del artículo.", "r": "CE art. 33.1 · batería oficial, pregunta 29", "c": 2}, {"id": "gett01q30", "q": "De acuerdo con el artículo 33.3 de la Constitución Española, ¿en qué circunstancias puede una persona ser privada de sus bienes y derechos?", "o": ["Por causa de utilidad pública, sin necesidad de compensación.", "Cuando lo determine una administración pública competente.", "Por causa justificada de utilidad pública o interés social, mediante indemnización y conforme a la ley.", "Únicamente por orden judicial en caso de delito patrimonial."], "e": "Es el texto literal del artículo.", "r": "CE art. 33.3 · batería oficial, pregunta 30", "c": 2}, {"id": "gett01q31", "q": "De conformidad con el artículo 35.1 de la Constitución Española, ¿qué tipo de discriminación está expresamente prohibida en relación con el trabajo?", "o": ["Por razones políticas.", "Por razón de sexo.", "Por nivel de estudios.", "Por edad o estado civil."], "e": "Es el texto literal del artículo.", "r": "CE art. 35.1 · batería oficial, pregunta 31", "c": 1}, {"id": "gett01q32", "q": "En relación al artículo 37 de la Constitución Española de 1978, señale la respuesta correcta:", "o": ["La ley garantizará el derecho a la negociación colectiva laboral entre los representantes de los trabajadores y empresarios, así como la fuerza vinculante de los convenios.", "La ley garantizará el derecho a la negociación colectiva laboral, únicamente entre los representantes de los trabajadores, así como la fuerza vinculante de los convenios.", "La ley garantizará el derecho a la negociación colectiva laboral, únicamente entre los representantes de los empresarios, así como la fuerza vinculante de los convenios.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "CE art. 37 · batería oficial, pregunta 32", "c": 0}, {"id": "gett01q33", "q": "Siguiendo con el artículo 37.2 de la Constitución Española, ¿qué debe incluir la ley que regule el ejercicio de medidas de conflicto colectivo?", "o": ["La obligación de preavisar con un mes de antelación.", "Un mecanismo de suspensión automática del conflicto.", "Las garantías precisas para asegurar el funcionamiento de los servicios esenciales de la comunidad.", "Un sistema obligatorio de arbitraje previo al conflicto."], "e": "Es el texto literal del artículo.", "r": "CE art. 37.2 · batería oficial, pregunta 33", "c": 2}, {"id": "gett01q34", "q": "Según el artículo 38 de la Constitución Española, ¿qué principio económico se reconoce expresamente?", "o": ["La intervención directa del Estado en todos los sectores productivos.", "El control estatal sobre las empresas estratégicas.", "La libertad de empresa en el marco de la economía de mercado.", "La eliminación de la competencia como principio regulador."], "e": "Es el texto literal del artículo.", "r": "CE art. 38 · batería oficial, pregunta 34", "c": 2}, {"id": "gett01q35", "q": "Una de las siguientes afirmaciones NO es verdadera. Los poderes públicos, según dispone la Constitución Española:", "o": ["Aseguran la protección económica de la familia.", "Aseguran la protección fiscal de la familia.", "Aseguran la protección jurídica de la familia.", "Aseguran la protección social de la familia."], "e": "Art. 39.1: protección social, económica y jurídica de la familia. No dice «fiscal».", "r": "CE · batería oficial, pregunta 35", "c": 1}, {"id": "gett01q36", "q": "¿Qué política realizarán especialmente los poderes públicos según el artículo 40.1 de la Constitución Española?", "o": ["Una política orientada al fomento del ahorro familiar.", "Una política de reducción del déficit público.", "Una política de impulso al mercado exterior.", "Una política orientada al pleno empleo."], "e": "Es el texto literal del artículo.", "r": "CE art. 40.1 · batería oficial, pregunta 36", "c": 3}, {"id": "gett01q37", "q": "Los poderes públicos fomentarán una política que garantice: (artículo 40.2 de la Constitución Española):", "o": ["La movilidad obligatoria entre sectores económicos.", "La formación y readaptación profesionales.", "El teletrabajo como régimen general.", "La suspensión temporal del empleo y sueldo en caso de baja productividad."], "e": "Es el texto literal del artículo.", "r": "CE art. 40.2 · batería oficial, pregunta 37", "c": 1}, {"id": "gett01q38", "q": "El régimen público de Seguridad Social al que se refiere el artículo 41 de la Constitución Española garantizará:", "o": ["Únicamente la asistencia sanitaria universal.", "La pensión de jubilación y la asistencia a personas mayores.", "La asistencia y prestaciones sociales suficientes ante situaciones de necesidad, especialmente en caso de desempleo.", "Sólo prestaciones económicas en situaciones excepcionales."], "e": "Es el texto literal del artículo.", "r": "CE art. 41 · batería oficial, pregunta 38", "c": 2}, {"id": "gett01q39", "q": "El artículo 43 de la Constitución Española reconoce:", "o": ["El derecho a una sanidad exclusivamente gratuita.", "El derecho a la protección de la salud.", "El derecho a elegir centro sanitario público o privado.", "El derecho a la libre elección de tratamientos médicos."], "e": "Es el texto literal del artículo.", "r": "CE art. 43 · batería oficial, pregunta 39", "c": 1}, {"id": "gett01q40", "q": "¿A quién compete organizar y tutelar la salud pública según el artículo 43 de la Constitución Española?", "o": ["A los Colegios Oficiales de Médicos.", "A las Comunidades Autónomas exclusivamente.", "A los poderes públicos.", "A los profesionales sanitarios en coordinación con los centros privados."], "e": "Es el texto literal del artículo.", "r": "CE art. 43 · batería oficial, pregunta 40", "c": 2}, {"id": "gett01q41", "q": "De conformidad con el artículo 43.3 de la Constitución Española, ¿cuál de las siguientes acciones deberán fomentar los poderes públicos?", "o": ["El deporte únicamente de alto rendimiento.", "El ocio digital y el entretenimiento en redes sociales.", "La educación sanitaria, la educación física y el deporte.", "La formación sanitaria universitaria exclusivamente."], "e": "Es el texto literal del artículo.", "r": "CE art. 43.3 · batería oficial, pregunta 41", "c": 2}, {"id": "gett01q42", "q": "¿Qué función tienen los poderes públicos respecto al acceso a la cultura, de acuerdo con el artículo 44.1 de la Constitución Española?", "o": ["Garantizar que la cultura sea gestionada por el sector privado.", "Conceder ayudas solo a manifestaciones artísticas tradicionales.", "Promover y tutelar el acceso a la cultura.", "Restringir el acceso a la cultura a profesionales del sector."], "e": "Es el texto literal del artículo.", "r": "CE art. 44.1 · batería oficial, pregunta 42", "c": 2}, {"id": "gett01q43", "q": "Según el artículo 44.2 de la Constitución Española, ¿qué promoverán los poderes públicos en beneficio del interés general?", "o": ["La innovación exclusivamente en el ámbito militar.", "La publicación de investigaciones en revistas extranjeras.", "La ciencia y la investigación científica y técnica.", "La protección de los secretos industriales y comerciales."], "e": "Es el texto literal del artículo.", "r": "CE art. 44.2 · batería oficial, pregunta 43", "c": 2}, {"id": "gett01q44", "q": "De acuerdo con el artículo 45.1 de la Constitución Española, el derecho a disfrutar de un medio ambiente adecuado está vinculado a:", "o": ["La conservación del medio ambiente como un deber individual y colectivo.", "La garantía de acceso a zonas naturales protegidas exclusivamente.", "La obligación de reciclar y reducir el consumo de energía.", "El desarrollo integral de la persona en un medio ambiente adecuado."], "e": "Art. 45.1: derecho a un medio ambiente adecuado para el desarrollo de la persona, y deber de conservarlo.", "r": "CE art. 45.1 · batería oficial, pregunta 44", "c": 3}, {"id": "gett01q45", "q": "Señale la respuesta INCORRECTA conforme a lo previsto en el artículo 46 de la Constitución Española:", "o": ["Los poderes públicos promoverán el enriquecimiento del patrimonio histórico, cultural y artístico de los pueblos de España.", "La conservación del patrimonio histórico, cultural y artístico dependerá exclusivamente de su titularidad.", "Los poderes públicos garantizarán la conservación del patrimonio cultural, con independencia de su régimen jurídico.", "La ley penal sancionará los atentados contra el patrimonio histórico, cultural y artístico."], "e": "Las demás opciones reproducen el texto del artículo.", "r": "CE art. 46 · batería oficial, pregunta 45", "c": 1}, {"id": "gett01q46", "q": "El artículo 47 de la Constitución Española establece que:", "o": ["Solo los ciudadanos con bajos recursos tienen derecho a una vivienda digna y adecuada.", "Los poderes públicos garantizarán la propiedad de una vivienda a todos los ciudadanos.", "Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.", "La vivienda digna es un derecho reconocido solo en determinadas comunidades autónomas."], "e": "Es el texto literal del artículo.", "r": "CE art. 47 · batería oficial, pregunta 46", "c": 2}, {"id": "gett01q47", "q": "Conforme al artículo 48 de la Constitución Española, ¿en qué ámbitos deben participar los jóvenes?", "o": ["Solamente en el ámbito educativo y laboral.", "En el desarrollo económico, pero no en el político.", "Únicamente en actividades culturales y sociales.", "En el desarrollo político, social, económico y cultural."], "e": "Es el texto literal del artículo.", "r": "CE art. 48 · batería oficial, pregunta 47", "c": 3}, {"id": "gett01q48", "q": "¿Cómo deben ejercer sus derechos las personas con discapacidad según el artículo 49 de la Constitución Española?", "o": ["En condiciones equivalentes a las de los ciudadanos extranjeros.", "En condiciones de igualdad formal, sin necesidad de medidas adicionales.", "En condiciones de libertad e igualdad reales y efectivas.", "Únicamente mediante la tutela o apoyo de un representante legal."], "e": "Art. 49 (reformado en 2024): las personas con discapacidad ejercen sus derechos en condiciones de libertad e igualdad reales y efectivas.", "r": "CE art. 49 · batería oficial, pregunta 48", "c": 2}, {"id": "gett01q49", "q": "Según el artículo 50 de la Constitución Española, ¿cómo garantizarán los poderes públicos la suficiencia económica durante la tercera edad?", "o": ["Mediante ayudas puntuales y extraordinarias aprobadas anualmente.", "A través de seguros privados subvencionados por el Estado.", "Mediante pensiones adecuadas y periódicamente actualizadas.", "Mediante la renta mínima vital universal."], "e": "Es el texto literal del artículo.", "r": "CE art. 50 · batería oficial, pregunta 49", "c": 2}, {"id": "gett01q50", "q": "Atendiendo al artículo 51 de la Constitución Española, ¿qué derechos deben proteger los poderes públicos respecto a los consumidores y usuarios?", "o": ["Solo los intereses económicos relacionados con el comercio exterior.", "Exclusivamente la salud en el ámbito alimentario.", "Los intereses culturales y recreativos de los consumidores.", "La seguridad, la salud y los legítimos intereses económicos de los consumidores y usuarios."], "e": "Es el texto literal del artículo.", "r": "CE art. 51 · batería oficial, pregunta 50", "c": 3}, {"id": "gett01q51", "q": "Siguiendo lo previsto en el apartado 1 del artículo 53 de la Constitución Española, ¿qué condiciones deben cumplirse para que una norma regule el ejercicio de los derechos y libertades reconocidos en el Capítulo segundo?", "o": ["Podrá regularse por cualquier tipo de norma jurídica, siempre que cuente con mayoría absoluta.", "Solo podrá regularse por ley, que en todo caso deberá respetar su contenido esencial.", "La regulación podrá hacerse por Real Decreto siempre que provenga del Gobierno.", "Podrá ser regulada por los reglamentos internos de cada Administración pública."], "e": "Es el texto literal del artículo.", "r": "CE art. 53 · batería oficial, pregunta 51", "c": 1}, {"id": "gett01q52", "q": "De acuerdo con el artículo 54 de la Constitución Española, ¿qué tipo de norma debe regular la institución del Defensor del Pueblo?", "o": ["Un reglamento aprobado por el Consejo de ministros.", "Una ley ordinaria aprobada por mayoría simple.", "Una ley orgánica.", "Un decreto ley aprobado por el Gobierno."], "e": "Es el texto literal del artículo.", "r": "CE art. 54 · batería oficial, pregunta 52", "c": 2}]}, {"id": "t02", "sig": "Tema 2", "titulo": "Tema 2. Organización territorial del Estado y Comunidades Autónomas", "sub": "Título VIII de la Constitución. Batería oficial.", "preguntas": [{"id": "gett02q01", "q": "Según el artículo 141 de la Constitución Española de 1978, una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado es:", "o": ["La mancomunidad.", "El municipio.", "La Provincia.", "El Estado."], "e": "Es el texto literal del artículo.", "r": "CE art. 141 · batería oficial, pregunta 53", "c": 2}, {"id": "gett02q02", "q": "De conformidad con los artículos 137 y ss. de la Constitución Española de 1978, señale la respuesta INCORRECTA respecto a la organización territorial del Estado:", "o": ["El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.", "Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.", "Las diferencias entre los Estatutos de las distintas Comunidades Autónomas podrán implicar, privilegios económicos o sociales.", "Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado."], "e": "Art. 138.2: las diferencias entre Estatutos no podrán implicar, en ningún caso, privilegios económicos o sociales.", "r": "CE art. 137 · batería oficial, pregunta 54", "c": 2}, {"id": "gett02q03", "q": "De acuerdo con el artículo 139 de la Constitución Española de 1978:", "o": ["Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado.", "Los españoles tienen los mismos derechos y obligaciones sólo en determinadas partes del territorio del Estado.", "La autoridad podrá adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y establecimiento de las personas y la libre circulación de bienes en todo el territorio español.", "La autoridad podrá adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y establecimiento de las personas y la libre circulación de bienes sólo en determinadas partes del territorio español."], "e": "Es el texto literal del artículo.", "r": "CE art. 139 · batería oficial, pregunta 55", "c": 0}, {"id": "gett02q04", "q": "Tal y como establece el artículo 147 de la Constitución Española de 1978, los Estatutos de autonomía deberán contener:", "o": ["La denominación de la Comunidad que mejor corresponda a su identidad histórica.", "La delimitación de su territorio y la denominación, organización y sede de las instituciones autónomas propias.", "Las competencias asumidas dentro del marco establecido en la Constitución y las bases para el traspaso de los servicios correspondientes a las mismas.", "Todas las anteriores son correctas."], "e": "Art. 147.2 recoge los cuatro contenidos: denominación, delimitación del territorio, instituciones propias y competencias asumidas.", "r": "CE art. 147 · batería oficial, pregunta 56", "c": 3}, {"id": "gett02q05", "q": "Los museos, las bibliotecas y conservatorios de música que sean de interés para la comunidad autónoma, tal y como establece el artículo 148 de la Constitución Española, pueden ser competencia de:", "o": ["Las comunidades autónomas.", "El Estado.", "Las cortes Generales.", "Los Estatutos."], "e": "Es el texto literal del artículo.", "r": "CE art. 148 · batería oficial, pregunta 57", "c": 0}, {"id": "gett02q06", "q": "Las bases y coordinación de la planificación general de la actividad económica, tal y como establece el artículo 149 de la Constitución Española, son competencia de:", "o": ["Las Comunidades Autónomas.", "El Estado.", "Las Cortes Generales.", "Los Estatutos."], "e": "Es el texto literal del artículo.", "r": "CE art. 149 · batería oficial, pregunta 58", "c": 1}, {"id": "gett02q07", "q": "Según el artículo 140 de la Constitución Española de 1978, los concejales serán elegidos:", "o": ["Por los vecinos y anteriores concejales del municipio mediante sufragio universal.", "Por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto.", "Por los alcaldes mediante sufragio universal, igual, libre, directo y secreto.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "CE art. 140 · batería oficial, pregunta 59", "c": 1}, {"id": "gett02q08", "q": "De conformidad con el artículo 142 de la Constitución Española de 1978, las Haciendas Locales:", "o": ["Deberán disponer de los medios suficientes para el desempeño de las funciones que la ley atribuye a las Corporaciones respectivas, aunque no se nutrirán de tributos propios y de participación en los del Estado y de las Comunidades Autónomas.", "Deberán disponer de los medios suficientes para el desempeño de las funciones que la ley atribuye a las Corporaciones respectivas y se nutrirán fundamentalmente de tributos propios y de participación en los del Estado y de las Comunidades Autónomas.", "Deberán únicamente disponer de los medios justos para el desempeño de sus funciones.", "La participación en los del Estado y de las Comunidades Autónomas no serán fuente de ingresos."], "e": "Es el texto literal del artículo.", "r": "CE art. 142 · batería oficial, pregunta 60", "c": 1}, {"id": "gett02q09", "q": "El Estado tiene competencia exclusiva sobre la siguiente materia (artículo 149 de la Constitución Española):", "o": ["Sanidad e higiene.", "Fomento y coordinación general de la investigación científica y técnica.", "Los montes y aprovechamientos forestales.", "Promoción del deporte y de la adecuada utilización del ocio."], "e": "Art. 149.1.15.ª. Sanidad e higiene, montes y deporte son materias del art. 148.", "r": "CE art. 149 · batería oficial, pregunta 61", "c": 1}, {"id": "gett02q10", "q": "Los recursos de las Comunidades Autónomas estarán constituidos por (artículo 157 de la Constitución Española de 1978):", "o": ["Impuestos cedidos totalmente por el Estado; recargos sobre impuestos estatales y otras participaciones en los ingresos de las Comunidades Autónomas.", "Transferencias de un Fondo Público y otras asignaciones con cargo en los ingresos del Estado.", "Rendimientos procedentes de su patrimonio e ingresos de derecho privado.", "Ninguna de las respuestas anteriores es correcta."], "e": "Art. 157.1.e. Las opciones a) y b) cambian el texto: impuestos cedidos total o parcialmente y participaciones en los ingresos del Estado; Fondo de Compensación interterritorial.", "r": "CE art. 157 · batería oficial, pregunta 62", "c": 2}, {"id": "gett02q11", "q": "Si una Comunidad Autónoma no cumpliere las obligaciones que la Constitución u otras leyes le impongan, o actuare de forma que atente gravemente al interés general de España (art. 155 de la CE):", "o": ["El Gobierno, previo requerimiento al presidente de la Comunidad Autónoma y, en el caso de no ser atendido, con la aprobación por mayoría simple del Congreso, podrá adoptar las medidas necesarias para obligar a aquélla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general.", "El Gobierno, previo requerimiento al presidente de la Comunidad Autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado, podrá adoptar las medidas necesarias para obligar a aquélla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general.", "Para la ejecución de las medidas previstas en la respuesta anterior, el Gobierno no podrá dar instrucciones a las autoridades de las Comunidades Autónomas.", "Para la ejecución de las medidas previstas en la respuesta anterior, el Gobierno, sólo y exclusivamente si cuenta con la autorización del Congreso y Senado, podrá dar instrucciones a las autoridades de las Comunidades Autónomas."], "e": "Es el texto literal del artículo.", "r": "CE · batería oficial, pregunta 63", "c": 1}, {"id": "gett02q12", "q": "De acuerdo con el artículo 150.2 de la CE, el Estado podrá transferir o delegar en las Comunidades Autónomas:", "o": ["Mediante ley orgánica, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.", "Mediante ley ordinaria, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.", "Mediante reglamento, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "CE art. 150.2 · batería oficial, pregunta 64", "c": 0}, {"id": "gett02q13", "q": "El control de la actividad de los órganos de las Comunidades Autónomas se ejercerá (art. 153. de la CE):", "o": ["Por el Tribunal Constitucional, el relativo a la constitucionalidad de sus disposiciones normativas con fuerza de ley.", "Por el Gobierno, previo dictamen del Congreso y del Senado, el del ejercicio de funciones delegadas a que se refiere el apartado 2 del artículo 150.", "Por el Tribunal de Cuentas, el económico y político.", "Ninguna de las respuestas anteriores es correcta."], "e": "Art. 153.a. El control de las funciones delegadas lo ejerce el Gobierno previo dictamen del Consejo de Estado, y el Tribunal de Cuentas ejerce el económico y presupuestario.", "r": "CE · batería oficial, pregunta 65", "c": 0}, {"id": "gett02q14", "q": "Atendiendo al artículo 150.3 de la CE, el Estado podrá dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las Comunidades Autónomas:", "o": ["Salvo se trate de materias atribuidas a la competencia de éstas, cuando así lo exija el interés general. Corresponde a las Cortes Generales, por mayoría simple de cada Cámara, la apreciación de esta necesidad.", "Aun en el caso de materias atribuidas a la competencia de éstas, cuando así lo exija el interés general. Corresponde únicamente al Congreso, por mayoría simple, la apreciación de esta necesidad.", "Aun en el caso de materias atribuidas a la competencia de éstas, cuando así lo exija el interés general. Corresponde a las Cortes Generales, por mayoría absoluta de cada Cámara, la apreciación de esta necesidad.", "El Estado no podrá, en ningún caso, dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las Comunidades Autónomas."], "e": "Es el texto literal del artículo.", "r": "CE art. 150.3 · batería oficial, pregunta 66", "c": 2}, {"id": "gett02q15", "q": "Conforme al apartado 3 del artículo 148 de la CE:", "o": ["Las materias no atribuidas expresamente al Estado por esta Constitución podrán corresponder a las Comunidades Autónomas, en virtud de sus respectivos Estatutos.", "La competencia sobre las materias que no se hayan asumido por los Estatutos de Autonomía corresponderá al Estado, cuyas normas prevalecerán, en caso de conflicto, sobre las de las Comunidades Autónomas en todo lo que no esté atribuido a la exclusiva competencia de éstas.", "El derecho estatal será, en todo caso, supletorio del derecho de las Comunidades Autónomas.", "Todas las respuestas anteriores son correctas."], "e": "Ojo: el texto de las tres opciones es del art. 149.3, aunque la pregunta cite el 148.3.", "r": "CE art. 148 · batería oficial, pregunta 67", "c": 3}, {"id": "gett02q16", "q": "En el ejercicio del derecho a la autonomía reconocido en el artículo 2 de la Constitución (art. 143.1 de la CE):", "o": ["Salvo las provincias limítrofes con características históricas, culturales y económicas comunes, los territorios insulares y las provincias con entidad regional histórica podrán acceder a su autogobierno y constituirse en Comunidades Autónomas con arreglo a lo previsto en este Título.", "Las provincias limítrofes con características históricas, culturales y económicas comunes, los territorios insulares y las provincias con entidad regional histórica podrán acceder a su autogobierno y constituirse en Comunidades Autónomas con arreglo a lo previsto en este Título y en los respectivos Estatutos.", "Las provincias limítrofes con características históricas, culturales y económicas comunes, los territorios insulares y las provincias con entidad regional histórica no podrán, en ningún caso, acceder a su autogobierno y constituirse en Comunidades Autónomas.", "Las provincias limítrofes con características históricas, culturales y económicas comunes, salvo los territorios insulares y las provincias con entidad regional histórica, podrán acceder a su autogobierno y constituirse en Comunidades Autónomas con arreglo a lo previsto en los respectivos Estatutos."], "e": "Es el texto literal del artículo.", "r": "CE art. 2 · batería oficial, pregunta 68", "c": 1}, {"id": "gett02q17", "q": "Señale la respuesta que es conforme al artículo 139.2 de la CE:", "o": ["Ninguna autoridad podrá adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y establecimiento de las personas, salvo se trate de la libre circulación de bienes en todo el territorio español.", "La autoridad podrá adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y establecimiento de las personas y la libre circulación de bienes en todo el territorio español.", "La autoridad, estatal o autonómica, podrá adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y establecimiento de las personas, a excepción de la libre circulación de bienes en todo el territorio español.", "Ninguna autoridad podrá adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y establecimiento de las personas y la libre circulación de bienes en todo el territorio español."], "e": "Es el texto literal del artículo.", "r": "CE art. 139.2 · batería oficial, pregunta 69", "c": 3}, {"id": "gett02q18", "q": "De conformidad con el artículo 144 de la Constitución Española, las Cortes Generales, mediante ley orgánica, podrán, por motivos de interés nacional:", "o": ["Autorizar la constitución de una comunidad autónoma cuando su ámbito territorial no supere el de una provincia y no reúna las condiciones del apartado 1 del artículo 143.", "Autorizar o acordar, en su caso, un Estatuto de autonomía para territorios que estén integrados en la organización provincial.", "Prohibir la iniciativa de las Corporaciones locales a que se refiere el apartado 2 del artículo 143.", "Autorizar la constitución de una comunidad autónoma cuando su ámbito territorial no supere el de una provincia, aunque reúna las condiciones del apartado 1 del artículo 143."], "e": "Es el texto literal del artículo.", "r": "CE art. 144 · batería oficial, pregunta 70", "c": 0}, {"id": "gett02q19", "q": "De conformidad con el artículo 149 de la Constitución Española, la regulación de las condiciones básicas que garanticen la igualdad de todos los españoles en el ejercicio de los derechos y en el cumplimiento de los deberes constitucionales:", "o": ["Es una competencia exclusiva del Estado.", "Es una competencia autonómica.", "Es una competencia compartida entre el Estado y las Comunidades Autónomas.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "CE art. 149 · batería oficial, pregunta 71", "c": 0}, {"id": "gett02q20", "q": "El artículo 141 de la Constitución Española de 1978:", "o": ["Autoriza la federación de las Comunidades Autónomas.", "Prevé la posibilidad de crear agrupaciones de municipios diferentes de la provincia.", "Encomienda el control de la actividad económico y presupuestaria de los órganos de las Comunidades Autónomas al Tribunal Constitucional y, subsidiariamente, al Tribunal de Cuentas.", "Autoriza la reforma de los Estatutos de autonomía, que se ajustará al procedimiento establecido en los mismos, y no requerirá la aprobación por las Cortes Generales mediante ley orgánica."], "e": "Es el texto literal del artículo.", "r": "CE art. 141 · batería oficial, pregunta 72", "c": 1}, {"id": "gett02q21", "q": "De conformidad con el artículo 147 de la CE, dentro de los términos de la presente Constitución, los Estatutos de autonomía serán:", "o": ["La norma institucional básica de cada Comunidad Autónoma, aunque el Estado no los reconozca y ampare como parte integrante del ordenamiento jurídico autonómico.", "La norma institucional supletoria de cada Comunidad Autónoma y el Estado los reconocerá y amparará solo como parte integrante del ordenamiento jurídico autonómico.", "La norma institucional básica de cada Comunidad Autónoma y el Estado los reconocerá y amparará como parte integrante de su ordenamiento jurídico.", "La norma institucional básica de cada Comunidad Autónoma y el Estado los reconocerá, pero no los amparará como parte integrante de su ordenamiento jurídico en ningún caso."], "e": "Es el texto literal del artículo.", "r": "CE art. 147 · batería oficial, pregunta 73", "c": 2}, {"id": "gett02q22", "q": "En cuanto a la administración local, conforme al artículo 140 de la CE:", "o": ["La Constitución garantiza la autonomía de los municipios.", "Estos gozarán de personalidad jurídica plena.", "Su gobierno y administración corresponde a sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "CE art. 140 · batería oficial, pregunta 74", "c": 3}, {"id": "gett02q23", "q": "De conformidad con el artículo 156 de la CE, las Comunidades Autónomas gozarán de:", "o": ["Autonomía financiera para el desarrollo y ejecución de sus competencias con arreglo a los principios de coordinación con la Hacienda estatal y de solidaridad entre todos los españoles.", "Autonomía financiera únicamente para el desarrollo de sus competencias con arreglo a los principios de coordinación con la Hacienda estatal y de eficiencia en todo el territorio español.", "Autonomía financiera únicamente para la ejecución de sus competencias con arreglo a los principios de coordinación con la Hacienda autonómica y de solidaridad entre todos los españoles.", "Autonomía financiera para el desarrollo y ejecución de sus competencias con arreglo a los principios de coordinación con la Hacienda autonómica y de solidaridad entre todos los españoles."], "e": "Es el texto literal del artículo.", "r": "CE art. 156 · batería oficial, pregunta 75", "c": 0}, {"id": "gett02q24", "q": "En los Presupuestos Generales del Estado podrá establecerse una asignación a las Comunidades Autónomas (art. 158 de la CE):", "o": ["En función de la necesidad de los servicios y actividades autonómicas que hayan asumido y de la garantía de un nivel medio en la prestación de los servicios públicos fundamentales en todo su respectivo territorio.", "En función del volumen de los servicios y actividades estatales que hayan asumido y de la garantía de un nivel mínimo en la prestación de los servicios públicos fundamentales en su respectivo territorio.", "En función de la necesidad de los servicios y actividades autonómicas que hayan asumido y de la garantía de un nivel alto en la prestación de los servicios públicos fundamentales en todo su respectivo territorio.", "En función del volumen de los servicios y actividades estatales que hayan asumido y de la garantía de un nivel mínimo en la prestación de los servicios públicos fundamentales en todo el territorio español."], "e": "Art. 158.1: en función del volumen de los servicios y actividades estatales asumidos y de la garantía de un nivel mínimo en los servicios públicos fundamentales en todo el territorio español.", "r": "CE · batería oficial, pregunta 76", "c": 3}, {"id": "gett02q25", "q": "En los Estatutos aprobados por el procedimiento a que se refiere el artículo 151 de la CE, la organización institucional autonómica se basará en:", "o": ["Una Asamblea Legislativa y un Consejo de Gobierno únicamente.", "Una Asamblea Legislativa, un Consejo de Gobierno y un Tribunal Superior de Justicia que, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo, culminará la organización judicial en todo el territorio español.", "Una Asamblea Legislativa, un Consejo de Gobierno, un Presidente y un Tribunal Superior de Justicia que, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo, culminará la organización judicial en el ámbito territorial de la Comunidad Autónoma.", "Ninguna de las respuestas anteriores es correcta."], "e": "Art. 152.1.", "r": "CE art. 151 · batería oficial, pregunta 77", "c": 2}, {"id": "gett02q26", "q": "De acuerdo con el artículo 148 de la CE, las Comunidades Autónomas podrán ampliar sucesivamente sus competencias dentro del marco establecido en el artículo 149:", "o": ["Transcurridos dos años, y mediante la reforma de sus Estatutos.", "Transcurridos cinco años, y mediante la reforma de sus Estatutos.", "Transcurridos tres años, y mediante la reforma de sus Estatutos.", "Transcurrido un año, y mediante la reforma de sus Estatutos."], "e": "Es el texto literal del artículo.", "r": "CE art. 148 · batería oficial, pregunta 78", "c": 1}, {"id": "gett02q27", "q": "De conformidad con el artículo 149 de la Constitución Española, sin perjuicio de las competencias que podrán asumir las Comunidades Autónomas, el Estado considerará el servicio de la cultura como:", "o": ["Deber y atribución secundaria, sin obligación de facilitar la comunicación cultural entre las Comunidades Autónomas.", "Deber y atribución esencial y facilitará la comunicación cultural entre las Comunidades Autónomas, de acuerdo con ellas.", "Atribución secundaria y facilitará la comunicación institucional entre las Comunidades Autónomas, de acuerdo con ellas.", "Deber esencial, sin obligación de facilitar la comunicación institucional entre las Comunidades Autónomas."], "e": "Es el texto literal del artículo.", "r": "CE art. 149 · batería oficial, pregunta 79", "c": 1}, {"id": "gett02q28", "q": "De conformidad con el artículo 138, el Estado garantiza la realización efectiva del principio de solidaridad consagrado en el artículo 2 de la Constitución:", "o": ["Velando por el establecimiento de un equilibrio económico, adecuado y justo entre las diversas partes del territorio español, y atendiendo en particular a las circunstancias del hecho insular.", "Velando por el establecimiento de un equilibrio económico, adecuado y justo entre las diversas partes del territorio español, sin atender a las circunstancias del hecho insular.", "Velando por el establecimiento de un equilibrio económico únicamente entre determinadas partes del territorio español, sin atender a las circunstancias del hecho insular.", "El Estado no garantizará, en ningún caso, la realización efectiva del principio de solidaridad del artículo 2 de la CE."], "e": "Es el texto literal del artículo.", "r": "CE art. 138 · batería oficial, pregunta 80", "c": 0}, {"id": "gett02q29", "q": "Según el artículo 146 de la CE, el proyecto de Estatuto será elaborado por una asamblea compuesta por:", "o": ["Los miembros de la Diputación u órgano interinsular de las provincias afectadas y por los Diputados y Senadores elegidos en ellas y será elevado a las Cortes Generales para su tramitación como ley.", "Los miembros de la Diputación u órgano interinsular de las provincias afectadas y por los Diputados y Senadores elegidos en ellas, sin necesidad de elevarlo a las Cortes Generales para su tramitación como ley.", "Los miembros de la Diputación u órgano interinsular de las provincias afectadas exclusivamente y será elevado al Gobierno Autonómico para su tramitación como ley.", "Los miembros de la Diputación u órgano interinsular de las provincias afectadas exclusivamente, sin necesidad de elevarlo al Gobierno Autonómico para su tramitación como ley."], "e": "Es el texto literal del artículo.", "r": "CE art. 146 · batería oficial, pregunta 81", "c": 0}, {"id": "gett02q30", "q": "La iniciativa del proceso autonómico a que se refiere el artículo 149 de la CE, es una competencia exclusiva del Estado:", "o": ["La Administración de Justicia.", "La artesanía.", "Asistencia social.", "Promoción del deporte y de la adecuada utilización del ocio."], "e": "Es el texto literal del artículo.", "r": "CE art. 149 · batería oficial, pregunta 82", "c": 0}, {"id": "gett02q31", "q": "La iniciativa del proceso autonómico a que se refiere el artículo 143.2 de la CE, en caso de no prosperar, solamente podrá reiterarse pasados:", "o": ["Tres años.", "Cinco años.", "Un año.", "Cuatro años."], "e": "Es el texto literal del artículo.", "r": "CE art. 143.2 · batería oficial, pregunta 83", "c": 1}, {"id": "gett02q32", "q": "De conformidad con el artículo 141 de la Constitución Española cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante:", "o": ["Ley ordinaria.", "Decreto Legislativo.", "Norma reglamentaria.", "Ley orgánica."], "e": "Es el texto literal del artículo.", "r": "CE art. 141 · batería oficial, pregunta 84", "c": 3}, {"id": "gett02q33", "q": "De conformidad con el artículo 153 de la Constitución Española, señale la respuesta correcta. El control de la actividad de los órganos de las Comunidades Autónomas se ejercerá:", "o": ["Por el Tribunal Constitucional, el relativo a la constitucionalidad de sus disposiciones normativas que no tengan fuerza de ley.", "Por la jurisdicción contencioso-administrativa, el del ejercicio de funciones delegadas a que se refiere el apartado 2 del artículo 150.", "Por el Gobierno, previo dictamen del Consejo de Estado, el de la administración autónoma y sus normas reglamentarias.", "Por el Tribunal de Cuentas, el económico y presupuestario."], "e": "Art. 153.d.", "r": "CE art. 153 · batería oficial, pregunta 85", "c": 3}, {"id": "gett02q34", "q": "De conformidad con el artículo 157 de la Constitución Española, señale la respuesta INCORRECTA. Los recursos de las Comunidades Autónomas estarán constituidos por:", "o": ["Impuestos cedidos total o parcialmente por el Estado; recargos sobre impuestos autonómicos y otras participaciones en los gastos del Estado.", "Sus propios impuestos, tasas y contribuciones especiales.", "Transferencias de un Fondo de Compensación interterritorial y otras asignaciones con cargo a los Presupuestos Generales del Estado.", "Rendimientos procedentes de su patrimonio e ingresos de derecho privado."], "e": "Art. 157.1.a: recargos sobre impuestos estatales y participaciones en los ingresos del Estado.", "r": "CE art. 157 · batería oficial, pregunta 86", "c": 0}, {"id": "gett02q35", "q": "Señale cuál de las siguientes actuaciones estaría prohibida para una Comunidad Autónoma según el artículo 157.2 de la Constitución Española:", "o": ["Establecer impuestos sobre bienes inmuebles ubicados dentro de su propio territorio.", "Adoptar medidas tributarias sobre bienes situados fuera de su territorio o que supongan obstáculo para la libre circulación de mercancías o servicios.", "Regular servicios públicos en su ámbito competencial.", "Promover el comercio local mediante ayudas a empresas de su territorio."], "e": "Es el texto literal del artículo.", "r": "CE art. 157.2 · batería oficial, pregunta 87", "c": 1}, {"id": "gett02q36", "q": "Según el artículo 154 de la Constitución Española, ¿cuál es la función principal del/la Delegado/a del Gobierno en una Comunidad Autónoma?", "o": ["Dictar leyes autonómicas en nombre del Estado.", "Representar al/la presidente/a de la Comunidad Autónoma ante el Gobierno central.", "Dirigir la Administración del Estado en el territorio autonómico y coordinarla con la administración autonómica.", "Nombrar a los/as consejeros/as del gobierno autonómico."], "e": "Es el texto literal del artículo.", "r": "CE art. 154 · batería oficial, pregunta 88", "c": 2}, {"id": "gett02q37", "q": "Conforme al artículo 155 de la Constitución Española, ¿qué debe hacer el Gobierno antes de adoptar medidas para obligar a una Comunidad Autónoma a cumplir con sus obligaciones?", "o": ["Solicitar la opinión del Tribunal Constitucional.", "Presentar una denuncia en el Congreso de los/as Diputados/as.", "Requerir al/la Presidente/a de la Comunidad Autónoma y, si no es atendido/a, obtener la aprobación por mayoría absoluta del Senado.", "Consultar a los partidos políticos de la Comunidad Autónoma afectada."], "e": "Es el texto literal del artículo.", "r": "CE art. 155 · batería oficial, pregunta 89", "c": 2}, {"id": "gett02q38", "q": "Atendiendo al artículo 137 de la Constitución Española, ¿qué entidades gozan de autonomía para la gestión de sus respectivos intereses?", "o": ["Únicamente las Comunidades Autónomas.", "Los municipios, las provincias y las Comunidades Autónomas que se constituyan.", "Solo los municipios.", "Las provincias y el Estado central."], "e": "Es el texto literal del artículo.", "r": "CE art. 137 · batería oficial, pregunta 90", "c": 1}, {"id": "gett02q39", "q": "Según el artículo 142 de la Constitución Española, ¿cómo deben financiarse las Haciendas locales para el desempeño de sus funciones?", "o": ["Únicamente a través de los tributos establecidos por el Estado.", "Mediante préstamos internacionales y participaciones privadas.", "Fundamentalmente con tributos propios y con participación en los tributos del Estado y las Comunidades Autónomas.", "A través de fondos aportados exclusivamente por las Comunidades Autónomas."], "e": "Es el texto literal del artículo.", "r": "CE art. 142 · batería oficial, pregunta 91", "c": 2}, {"id": "gett02q40", "q": "De conformidad con el artículo 140 de la Constitución Española, ¿quiénes son responsables del gobierno y la administración de los municipios?", "o": ["Los/as diputados/as provinciales.", "Los Ayuntamientos, compuestos por Alcaldes/sas y Concejales/as.", "El Gobierno central.", "Las Cortes Generales."], "e": "Es el texto literal del artículo.", "r": "CE art. 140 · batería oficial, pregunta 92", "c": 1}, {"id": "gett02q41", "q": "Las Cortes Generales, en materias de competencia estatal, podrán atribuir a todas o a alguna de las Comunidades Autónomas (artículo 150 de la CE):", "o": ["La facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, bases y directrices fijados por una ley estatal. Sin perjuicio de la competencia de los Tribunales, en cada ley marco se establecerá la modalidad del control de las Cortes Generales sobre estas normas legislativas de las Comunidades Autónomas.", "La facultad de dictar, para sí mismas u otras Comunidades Autónomas, normas legislativas en el marco de los principios, bases y directrices fijados por una ley autonómica. Sin perjuicio de la competencia de los Tribunales, en cada ley marco se establecerá la modalidad del control de las Cortes Generales sobre estas normas legislativas de las Comunidades Autónomas.", "La facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, bases y directrices fijados por un reglamento. El Reglamento no establecerá la modalidad del control de las Cortes Generales sobre estas normas legislativas de las Comunidades Autónomas.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "CE art. 150 · batería oficial, pregunta 93", "c": 0}, {"id": "gett02q42", "q": "Mediante _____________ podrá regularse el ejercicio de las competencias financieras enumeradas en el apartado 1 del artículo 157, las normas para resolver los conflictos que pudieran surgir y las posibles formas de colaboración financiera entre las Comunidades Autónomas y el Estado:", "o": ["Ley orgánica.", "Ley ordinaria.", "Decreto Legislativo.", "Reglamento."], "e": "Es el texto literal del artículo.", "r": "CE art. 157 · batería oficial, pregunta 94", "c": 0}]}, {"id": "t03", "sig": "Tema 3", "titulo": "Tema 3. Estatuto de Autonomía del País Vasco: competencias", "sub": "Título I de la LO 3/1979. Batería oficial.", "preguntas": [{"id": "gett03q01", "q": "Señale la respuesta INCORRECTA. Según el artículo 14 de la Ley Orgánica 3/1979, de 18 de diciembre, del Estatuto de Autonomía para el País Vasco, la competencia de los órganos jurisdiccionales en el País Vasco se extiende:", "o": ["En el orden civil, a todas las instancias y grados, a excepción de los recursos de casación y de revisión en las materias del Derecho Civil Foral propio del País Vasco.", "En el orden penal y social, a todas las instancias y grados, con excepción de los recursos de casación y de revisión.", "En el orden contencioso-administrativo, a todas las instancias y grados cuando se trate de actos dictados por la Administración del País Vasco en las materias cuya legislación exclusiva corresponde a la Comunidad Autónoma, y, en primera instancia, cuando se trate de actos dictados por la Administración del Estado.", "A las cuestiones de competencia entre órganos judiciales del País Vasco."], "e": "Art. 14.1.a del Estatuto: en el orden civil, en todas las instancias y grados, incluidos los recursos de casación y revisión en materias de Derecho Civil Foral propio.", "r": "EAPV art. 14 · batería oficial, pregunta 95", "c": 0}, {"id": "gett03q02", "q": "Según el artículo 10 de la Ley Orgánica 3/1979, de 18 de diciembre, de Estatuto de la Autonomía para el País Vasco, ¿cuál de las competencias indicadas es competencia exclusiva de la Comunidad Autónoma del País Vasco?:", "o": ["Ordenación del territorio y del litoral, urbanismo y vivienda.", "Medio Ambiente y ecología.", "Ordenación del crédito, banca y seguros.", "Ordenación del sector pesquero del País Vasco."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 10 · batería oficial, pregunta 96", "c": 0}, {"id": "gett03q03", "q": "De acuerdo con el artículo 12 de la Ley Orgánica 3/1979, de 18 de diciembre, de Estatuto de Autonomía para el País Vasco, corresponde a la Comunidad Autónoma del País Vasco la ejecución de la legislación del Estado en las materias siguientes:", "o": ["Pesca en aguas interiores, marisqueo y acuicultura, caza y pesca fluvial y lacustre.", "Medio ambiente y ecología.", "Ordenación del crédito, banca y seguros.", "Propiedad intelectual e industrial."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 12 · batería oficial, pregunta 97", "c": 3}, {"id": "gett03q04", "q": "De acuerdo con el artículo 11 de la Ley Orgánica 3/1979, de 18 de diciembre, de Estatuto de Autonomía para el País Vasco, es de competencia de la Comunidad Autónoma del País Vasco el desarrollo legislativo y la ejecución dentro de su territorio de la legislación básica del Estado, las siguientes materias:", "o": ["Espectáculos.", "Ordenación del sector pesquero del País Vasco.", "Turismo y deporte.", "Casinos, juegos y apuestas, con excepción de las Apuestas Mutuas Deportivas Benéficas."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 11 · batería oficial, pregunta 98", "c": 1}, {"id": "gett03q05", "q": "De conformidad con el artículo 11 de la Ley Orgánica 3/1979, de 18 de diciembre, de Estatuto de la Autonomía del País Vasco, es competencia de la Comunidad Autónoma del País Vasco el desarrollo legislativo y la ejecución dentro de su territorio de la legislación básica del Estado en las siguientes materias:", "o": ["Legislación penitenciaria.", "Ferias internacionales celebradas en el País Vasco.", "Salvamento marítimo y vertidos industriales y contaminantes en las aguas territoriales del Estado correspondientes al litoral vasco.", "Expropiación forzosa, contratos y concesiones administrativas, en el ámbito de sus competencias y sistema de responsabilidad de la Administración del País Vasco."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 11 · batería oficial, pregunta 99", "c": 3}, {"id": "gett03q06", "q": "De conformidad con el artículo 10 de la Ley Orgánica 3/1979, de 18 de diciembre, de Estatuto de Autonomía para el País Vasco, la Comunidad Autónoma del País Vasco tiene competencia exclusiva en materias de:", "o": ["Organización, régimen y funcionamiento de sus instituciones de autogobierno dentro de las normas del presente Estatuto.", "Normas procesales y de procedimientos administrativo y económicoadministrativo que se deriven de las especialidades del derecho sustantivo y de la organización propia del País Vasco.", "Investigación científica y técnica en coordinación con el Estado.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 10 · batería oficial, pregunta 100", "c": 3}, {"id": "gett03q07", "q": "Siguiendo con el artículo 10.2 del estatuto de autonomía para el país vasco, la organización, régimen y funcionamiento de las instituciones de autogobierno, es una competencia:", "o": ["Compartida con el Estado.", "Exclusiva no compartida.", "Compartida con los territorios históricos.", "De desarrollo legislativo y ejecución."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 10.2 · batería oficial, pregunta 101", "c": 1}, {"id": "gett03q08", "q": "El artículo 17 del Estatuto de Autonomía para el País Vasco NO establece como competencia exclusiva de los territorios históricos:", "o": ["Régimen electoral municipal.", "Régimen electoral foral.", "Régimen de los bienes provinciales y municipales.", "Las demarcaciones territoriales de ámbito supramunicipal que no excedan de los límites provinciales."], "e": "Ojo: la pregunta cita el art. 17, pero las competencias exclusivas de los Territorios Históricos están en el art. 37.3. El régimen electoral foral no figura entre ellas.", "r": "EAPV art. 17 · batería oficial, pregunta 102", "c": 1}, {"id": "gett03q09", "q": "En materia de Seguridad Social corresponderá al País Vasco conforme a lo dispuesto en el art. 18.2 del Estatuto de Autonomía del País Vasco:", "o": ["El desarrollo legislativo y la ejecución de la legislación básica del Estado, salvo las normas que configuran el régimen económico de la misma.", "La gestión del régimen económico de la Seguridad Social.", "Las dos respuestas anteriores son correctas.", "Las respuestas a) y b) no son correctas."], "e": "Es el texto literal del artículo.", "r": "EAPV · batería oficial, pregunta 103", "c": 2}, {"id": "gett03q10", "q": "De acuerdo con el artículo 21 del Estatuto de Autonomía del País Vasco:", "o": ["El Derecho emanado del País Vasco en las materias de su competencia exclusiva es el aplicable con preferencia a cualquier otro y sólo en su defecto será de aplicación supletoria el Derecho del Estado.", "El Derecho emanado del País Vasco en las materias de competencias compartidas es el aplicable con preferencia a cualquier otro y sólo en su defecto será de aplicación supletoria el Derecho del Estado.", "El Derecho emanado del País Vasco en las materias de competencia estatal es el aplicable con preferencia a cualquier otro y sólo en su defecto será de aplicación supletoria el Derecho del Estado.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 21 · batería oficial, pregunta 104", "c": 0}, {"id": "gett03q11", "q": "¿Qué derecho tiene el País Vasco en cuanto a los medios de comunicación social de conformidad con el artículo 19 del Estatuto de Autonomía?", "o": ["Puede regular y crear únicamente radio y prensa, pero no televisión.", "Puede regular, crear y mantener su propia televisión, radio, prensa y otros medios de comunicación social, respetando lo dispuesto en el artículo 20 de la Constitución Española.", "Solo puede ejecutar las normativas del Estado en materia de medios de comunicación sin capacidad para crear sus propios medios.", "Solo puede coordinarse con el Estado en cuanto a la ejecución de medios de titularidad estatal, sin desarrollar legislación propia."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 19 · batería oficial, pregunta 105", "c": 1}, {"id": "gett03q12", "q": "Atendiendo al artículo 20 del Estatuto de Autonomía para el País Vasco, señale la respuesta INCORRECTA:", "o": ["El País Vasco tendrá competencias legislativas y de ejecución en las demás materias que por Ley Orgánica le transfiera o delegue el Estado según la Constitución, a petición del Parlamento Vasco.", "La Comunidad Autónoma del País Vasco podrá dictar la correspondiente legislación en los términos del artículo 150.1 de la Constitución, cuando las Cortes Generales aprueben las Leyes marco a que se refiere dicho precepto.", "El País Vasco ejecutará los tratados y convenios en todo lo que afecte a las materias atribuidas a su competencia en este Estatuto.", "Cualquier tratado o convenio podrá afectar a las atribuciones y competencias del País Vasco, aun cuando no sea mediante el procedimiento del artículo 152.2 de la Constitución."], "e": "Art. 20.3: ningún tratado o convenio podrá afectar a las competencias del País Vasco si no es mediante el procedimiento del art. 152.2 de la Constitución.", "r": "EAPV art. 20 · batería oficial, pregunta 106", "c": 3}, {"id": "gett03q13", "q": "¿Cómo se organiza la Administración Civil del Estado en el territorio del País Vasco? (art. 23 del Estatuto de Autonomía del País Vasco):", "o": ["La Administración Civil del Estado opera independientemente de la Administración autonómica del País Vasco.", "La Administración Civil del Estado en el País Vasco se adecúa al ámbito geográfico de la Comunidad Autónoma y es dirigida por un/a Delegado/a del Gobierno, coordinada con la administración autonómica.", "El Gobierno Vasco tiene la autoridad para organizar la Administración Civil del Estado sin intervención del Gobierno central.", "La Administración Civil del Estado solo coordina sus acciones con el Gobierno Vasco en casos de emergencia."], "e": "Es el texto literal del artículo.", "r": "EAPV · batería oficial, pregunta 107", "c": 1}, {"id": "gett03q14", "q": "Los poderes públicos vascos ejercerán las competencias en materia de Sanidad y Seguridad Social (art. 18.5 del Estatuto de Autonomía del País Vasco):", "o": ["A través de decisiones administrativas, sin necesidad de consultar a los/as interesados/as.", "Ajustándose a criterios de participación democrática, consultando a los/as interesados/as, sindicatos y asociaciones empresariales, según lo disponga la ley.", "Exigiendo la participación solo de las autoridades sanitarias y de seguridad social del Gobierno Vasco.", "Realizando consultas únicamente a las autoridades estatales y excluyendo la participación de sindicatos y asociaciones empresariales."], "e": "Es el texto literal del artículo.", "r": "EAPV · batería oficial, pregunta 108", "c": 1}, {"id": "gett03q15", "q": "Conforme al artículo 13 del Estatuto de Autonomía del País Vasco, la Comunidad Autónoma del País Vasco tiene las siguientes competencias en relación con la Administración de Justicia:", "o": ["Puede ejercer todas las competencias judiciales, incluida la jurisdicción militar.", "Tiene competencia exclusiva en todos los ámbitos de la Administración de Justicia.", "Solo puede intervenir en la organización del Ministerio Fiscal, pero no en la Administración de Justicia.", "Ejercerá las facultades que las Leyes Orgánicas del Poder Judicial y del Consejo General del Poder Judicial reconozcan, reserven o atribuyan al Gobierno, excepto la jurisdicción militar."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 13 · batería oficial, pregunta 109", "c": 3}, {"id": "gett03q16", "q": "En relación a la creación y organización de su Parlamento, el País Vasco tiene la siguiente competencia conforme al artículo 15 del Estatuto de Autonomía del País Vasco:", "o": ["El País Vasco no tiene competencia para crear su Parlamento, que depende exclusivamente del Gobierno central.", "El País Vasco puede crear y organizar su Parlamento mediante Ley, y establecer un órgano similar al del artículo 54 de la Constitución Española para ejercer funciones específicas.", "El Parlamento Vasco debe ser designado exclusivamente por el Gobierno central, sin intervención del País Vasco.", "El País Vasco solo puede crear un Parlamento, pero no puede organizar un órgano similar al previsto en el artículo 54 de la Constitución."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 15 · batería oficial, pregunta 110", "c": 1}, {"id": "gett03q17", "q": "En caso de declaración del estado de alarma, excepción o sitio, según el artículo 17.7 del Estatuto de Autonomía del País Vasco:", "o": ["Las fuerzas policiales del País Vasco mantienen su independencia y no están subordinadas a ninguna autoridad externa.", "Las fuerzas policiales del País Vasco quedarán a las órdenes directas de la autoridad civil o militar correspondiente, según lo dispuesto en la legislación pertinente.", "Las fuerzas policiales del País Vasco actuarán bajo las órdenes del Parlamento Vasco exclusivamente.", "Las fuerzas policiales del País Vasco solo estarán bajo el control del Gobierno Vasco, independientemente de la situación."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 17.7 · batería oficial, pregunta 111", "c": 1}, {"id": "gett03q18", "q": "Señale la respuesta INCORRECTA (artículo 22 del Estatuto de Autonomía del País Vasco):", "o": ["La Comunidad Autónoma podrá celebrar convenios con otras Comunidades Autónomas para la gestión y prestación de servicios propios de la exclusiva competencia de las mismas.", "La celebración de los citados convenios, antes de su entrada en vigor, deberá ser comunicada a las Cortes Generales.", "La Comunidad Autónoma podrá celebrar convenios con otro Territorio Histórico foral para la gestión y prestación de servicios propios correspondientes a las materias de su competencia, no siendo necesaria su comunicación a las Cortes Generales.", "La Comunidad Autónoma podrá establecer también acuerdos de cooperación con otras Comunidades Autónomas previa autorización de las Cortes Generales."], "e": "Art. 22.3: los convenios con otro Territorio Histórico foral también deben comunicarse a las Cortes Generales y entran en vigor a los 20 días.", "r": "EAPV art. 22 · batería oficial, pregunta 112", "c": 2}, {"id": "gett03q19", "q": "De acuerdo con el artículo 20.5 del Estatuto de Autonomía del País Vasco, el Gobierno Vasco será informado en:", "o": ["La elaboración de los tratados y convenios, así como de los proyectos de legislación aduanera, en cuanto afecten a materias de específico interés para el País Vasco.", "La elaboración de los tratados y convenios, así como de los proyectos de legislación básica y régimen económico de la Seguridad Social, a pesar de que no afecten a materias de específico interés para el País Vasco.", "La elaboración de los tratados y convenios, así como de los proyectos de legislación de productos farmacéuticos, a pesar de que no afecten a materias de específico interés para el País Vasco.", "El precepto dispone que el Gobierno Vasco no será informado en la elaboración de los tratados y convenios."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 20.5 · batería oficial, pregunta 113", "c": 0}, {"id": "gett03q20", "q": "De conformidad con el artículo 12 del Estatuto de Autonomía del País Vasco, a legislación en materia de salvamento marítimo y vertidos industriales y contaminantes en las aguas territoriales del Estado correspondientes al litoral vasco es:", "o": ["Una competencia exclusiva del Estado, así como su ejecución.", "Una competencia exclusiva de la Comunidad Autónoma del País Vasco.", "Una competencia del Estado, pero su ejecución corresponde a la Comunidad Autónoma del País Vasco.", "Una competencia de la Comunidad Autónoma del País Vasco, pero su ejecución corresponde en exclusiva al Estado."], "e": "Es el texto literal del artículo.", "r": "EAPV art. 12 · batería oficial, pregunta 114", "c": 2}]}, {"id": "t04", "sig": "Tema 4", "titulo": "Tema 4. Ley 10/1982 de normalización del uso del euskera", "sub": "Título Preliminar, Título I y Capítulo I del Título II. Batería oficial.", "preguntas": [{"id": "gett04q01", "q": "Según los artículos 2-3 de la ley 10/1982, básica de normalización del uso del Euskera, deberán estar redactados en forma bilingüe:", "o": ["Toda disposición normativa o resolución oficial que emane de los poderes públicos sitos en la Comunidad Autónoma del País Vasco.", "Las señales e indicadores de tráfico instalados en la vía pública.", "Los modelos oficiales que hayan de utilizarse por los poderes públicos en la Comunidad Autónoma del País Vasco.", "Todas las respuestas son correctas."], "e": "Arts. 8.1 (disposiciones y resoluciones), 10.2 (señales de tráfico) y 13 (modelos oficiales).", "r": "Ley 10/1982 art. 2-3 · batería oficial, pregunta 115", "c": 3}, {"id": "gett04q02", "q": "Conforme al artículo 2 de la Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera, la lengua propia del País Vasco es:", "o": ["El euskera.", "El castellano.", "El euskera y el castellano.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 2 · batería oficial, pregunta 116", "c": 0}, {"id": "gett04q03", "q": "Las lenguas oficiales en la Comunidad Autónoma del País Vasco son (artículo 3 de la Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera):", "o": ["El castellano, que es la única lengua oficial.", "El euskera, que es la única lengua oficial.", "El euskera y el castellano.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 3 · batería oficial, pregunta 117", "c": 2}, {"id": "gett04q04", "q": "Se reconocen a los ciudadanos del País Vasco los siguientes derechos lingüísticos fundamentales (artículo 5 de la Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera):", "o": ["Derecho a relacionarse en euskera o en castellano oralmente y/o por escrito con la Administración y con cualquier Organismo o Entidad radicado en la Comunidad Autónoma.", "Derecho a recibir en euskera publicaciones periódicas, programaciones de radio y televisión y de otros medios de comunicación.", "Derecho a expresarse en euskera en cualquier reunión.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 5 · batería oficial, pregunta 118", "c": 3}, {"id": "gett04q05", "q": "Señale la respuesta INCORRECTA. De acuerdo con el artículo 9 de la Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera:", "o": ["En sus relaciones con la Administración de Justicia, todo ciudadano podrá utilizar la lengua oficial de su elección, aunque en los casos convenientes previstos en la presente ley, se le podrá exigir traducción.", "Los escritos y documentos presentados en euskera, así como las actuaciones judiciales, serán totalmente válidas y eficaces.", "El Gobierno Vasco promoverá, de acuerdo con los órganos correspondientes, la normalización del uso del euskera en la Administración de Justicia en el País Vasco.", "Ninguna de las respuestas anteriores es correcta."], "e": "Art. 9.1: puede usar la lengua oficial de su elección sin que se le pueda exigir traducción alguna.", "r": "Ley 10/1982 art. 9 · batería oficial, pregunta 119", "c": 0}, {"id": "gett04q06", "q": "De conformidad con el artículo 14 de la Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera, señale la respuesta correcta:", "o": ["A fin de hacer efectivos los derechos reconocidos en el artículo 6.º de la presente Ley, los poderes Públicos adoptarán las medidas tendentes a la progresiva euskaldunización del personal afecto a la Administración Pública en la Comunidad Autónoma del País Vasco.", "Los órganos políticos determinarán las plazas para las que es preceptivo o no el conocimiento del euskera.", "En las pruebas selectivas que se realicen para el acceso a las demás plazas de la Administración en el ámbito territorial de la Comunidad Autónoma del País Vasco, se considerará, entre otros méritos, el nivel de conocimiento de la lengua propia, cuya ponderación la realizarán los órganos políticos para cada nivel profesional.", "Todas las respuestas anteriores son correctas."], "e": "Art. 14.1. Las plazas con conocimiento preceptivo las determinan los poderes públicos, y en las demás se valora el conocimiento de las lenguas oficiales.", "r": "Ley 10/1982 art. 14 · batería oficial, pregunta 120", "c": 0}, {"id": "gett04q07", "q": "Atendiendo al artículo 5 de la Ley 10/1982, básica de normalización del uso del Euskera, ¿cuál de las siguientes expresiones es correcta?:", "o": ["Los poderes públicos intentarán garantizar parcialmente el ejercicio de los derechos lingüísticos de la ciudadanía vasco-parlante.", "Toda la ciudadanía del País Vasco tiene derecho a conocer y usar las lenguas oficiales, tanto oralmente como por escrito.", "Los poderes públicos garantizarán el ejercicio de los derechos lingüísticos tanto dentro como fuera de la Comunidad Autónoma del País Vasco.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 5 · batería oficial, pregunta 121", "c": 1}, {"id": "gett04q08", "q": "Según el artículo 5 de la Ley 10/1982, básica de normalización del uso del Euskera, se reconocen a la ciudadanía del País Vasco los siguientes derechos lingüísticos fundamentales:", "o": ["Derecho a relacionarse exclusivamente en euskera y por escrito con la Administración y con cualquier Organismo o Entidad radicado en la Comunidad Autónoma.", "Derecho a desarrollar actividades profesionales, laborales y políticas en euskera y sindicales exclusivamente en castellano.", "Derecho a expresarse en euskera en cualquier reunión.", "Las respuestas b) y c), ambas, son correctas."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 5 · batería oficial, pregunta 122", "c": 2}, {"id": "gett04q09", "q": "Señale la respuesta correcta de acuerdo con lo previsto en el artículo 14 de la ley 10/1982, básica de normalización del uso del Euskera:", "o": ["Los poderes públicos adoptarán las medidas tendentes a la progresiva euskaldunización del personal afecto a la Administración Pública en la Comunidad Autónoma del País Vasco.", "En las pruebas selectivas que se realicen para el acceso a las demás plazas se considerará, entre otros méritos, el nivel de conocimiento de las lenguas oficiales en la Comunidad Autónoma Vasca.", "Los poderes públicos determinarán las plazas para las que es preceptivo el conocimiento de ambas lenguas.", "Todas las respuestas son correctas."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 14 · batería oficial, pregunta 123", "c": 3}, {"id": "gett04q10", "q": "De conformidad con el artículo 7 de la Ley 10/1982, básica de normalización del uso del Euskera La inscripción de documentos en los registros públicos dependientes de las administraciones de la comunidad autónoma, se hará:", "o": ["En castellano con su traducción al euskera.", "En euskera con su traducción al castellano.", "En la lengua oficial en que aparezcan extendidos.", "Ninguna de las respuestas es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 7 · batería oficial, pregunta 124", "c": 2}, {"id": "gett04q11", "q": "Según el artículo 9 de la ley 10/1982, básica de normalización del uso del Euskera, todo ciudadano/a, en sus relaciones con la Administración de Justicia:", "o": ["Podrá utilizar la lengua oficial de su elección, exigiéndosele su traducción al castellano.", "Podrá utilizar la lengua propia del País Vasco, exigiéndosele su traducción al castellano.", "Podrá utilizar la lengua oficial de su elección, sin que se le pueda exigir traducción alguna.", "Ninguna de las respuestas es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 9 · batería oficial, pregunta 125", "c": 2}, {"id": "gett04q12", "q": "El artículo 14 de la Ley 10/1982, básica de normalización del uso del Euskera, establece que los poderes públicos para hacer efectivos los derechos de uso del euskera adoptarán:", "o": ["Las medidas tendentes a la lenta euskaldunización del personal afecto a la Administración Pública en la Comunidad Autónoma del País Vasco.", "Las medidas tendentes a la progresiva euskaldunización del personal afecto a la Administración Pública en la Comunidad Autónoma del País Vasco.", "Las medidas tendentes a la consolidación de la euskaldunización del personal afecto a la Administración Pública en la Comunidad Autónoma del País Vasco.", "Todas las respuestas anteriores son incorrectas."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 14 · batería oficial, pregunta 126", "c": 1}, {"id": "gett04q13", "q": "Según el artículo 2 de la ley 10/1982, básica de normalización del uso del Euskera:", "o": ["La lengua oficial en la comunidad Autónoma del País Vasco es el exclusivamente el castellano a efectos de notificaciones administrativas practicadas por escrito.", "La lengua oficial en la comunidad Autónoma del País Vasco es el exclusivamente el euskera a efectos de notificaciones administrativas practicadas por escrito.", "Los poderes públicos velarán y adoptarán las medidas oportunas para que la lengua propia y oficial del País Vasco sea el euskera.", "La lengua propia del País Vasco es el euskera."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 2 · batería oficial, pregunta 127", "c": 3}, {"id": "gett04q14", "q": "Siguiendo lo dispuesto en los artículos 2 y 3 de la Ley 10/1982, básica de normalización del uso del Euskera, el euskera es:", "o": ["La Lengua propia del País Vasco junto con el castellano.", "La única lengua propia y una de las oficiales del País Vasco.", "La única lengua oficial del País Vasco.", "Es la única lengua propia y la única oficial del País Vasco."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 2 y 3 · batería oficial, pregunta 128", "c": 1}, {"id": "gett04q15", "q": "En los expedientes o procedimientos en los que intervenga más de una persona, los poderes públicos utilizarán aquella lengua que establezcan de mutuo acuerdo las partes que concurran. En caso de no haber acuerdo:", "o": ["Se utilizará la que disponga la persona que haya promovido el expediente o procedimiento, sin perjuicio del derecho de las partes a ser informadas en la lengua que deseen.", "Se utilizará la que dispongan los poderes públicos, sin perjuicio del derecho de las partes a ser informadas en la lengua que deseen.", "Se utilizará la que se acuerde entre los poderes públicos y las partes implicadas.", "Se utilizará, en todo caso, el euskera y, subsidiariamente, el castellano."], "e": "Es la redacción literal del art. 6.2, pero esa última frase fue declarada inconstitucional y nula por la STC 82/1986.", "r": "Ley 10/1982 · batería oficial, pregunta 129", "c": 0}, {"id": "gett04q16", "q": "En todos los servicios de transporte público con origen en el País Vasco, los impresos, los avisos y las comunicaciones al público se harán en: (Art. 11 de la Ley 10/1982)", "o": ["Euskera y en castellano.", "Únicamente en castellano.", "Únicamente en euskera.", "Únicamente en castellano y, si se solicitase expresamente por algún/a ciudadano/a, en euskera."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 · batería oficial, pregunta 130", "c": 0}, {"id": "gett04q17", "q": "En relación a la Administración de Justicia en el País Vasco, conforme al artículo 9 de la Ley 10/1982, de 24 de noviembre, los escritos y documentos presentados en euskera, así como las actuaciones judiciales:", "o": ["No serán válidas.", "No serán válidas y eficaces si no se traducen al castellano.", "Serán totalmente válidas y eficaces.", "Sólo serán válidas y eficaces si así se acuerda expresamente y por escrito entre las partes implicadas."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 9 · batería oficial, pregunta 131", "c": 2}, {"id": "gett04q18", "q": "La nomenclatura oficial de los territorios, municipios, entidades de población, accidentes geográficos, vías urbanas y, en general, los topónimos de la Comunidad Autónoma Vasca, según el artículo 10 de la Ley 10/1982, básica de normalización del uso del Euskera, será establecida por:", "o": ["El Gobierno, los Órganos Forales de los Territorios Históricos o las Corporaciones Locales en el ámbito de sus respectivas competencias.", "El Gobierno exclusivamente.", "Los Órganos Forales de los Territorios Históricos o las Corporaciones Locales en el ámbito de sus respectivas competencias y, subsidiariamente, por el Gobierno.", "Las Corporaciones Locales en primer lugar y, subsidiariamente, por el Gobierno."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 10 · batería oficial, pregunta 132", "c": 0}, {"id": "gett04q19", "q": "El servicio oficial de traductores (artículo 12 de la Ley 10/1982, de 24 de noviembre):", "o": ["Estará a disposición de los/as ciudadanos/as.", "Estará a disposición de las entidades Públicas de la Comunidad Autónoma.", "Tiene por finalidad garantizar la exactitud y equivalencia jurídica de las traducciones.", "Todas las respuestas anteriores son correctas."], "e": "Art. 12.2.", "r": "Ley 10/1982 art. 12 · batería oficial, pregunta 133", "c": 3}, {"id": "gett04q20", "q": "Conforme al artículo 4 de la Ley 10/1982, básica de normalización del uso del Euskera, para que nadie sea discriminado/a por razón de la lengua en la Comunidad Autónoma del País Vasco:", "o": ["Los poderes públicos velarán y adoptarán las medidas oportunas.", "Los poderes públicos no tienen la obligación de adoptar las medidas que consideren necesarias.", "Sólo los poderes públicos estatales pueden adoptar las medidas necesarias al respecto, sin que los poderes públicos autonómicos puedan adoptarlas.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 4 · batería oficial, pregunta 134", "c": 0}, {"id": "gett04q21", "q": "Recibir en euskera publicaciones periódicas, programaciones de radio y televisión y de otros medios de comunicación es (artículo 5 de la Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera):", "o": ["Un derecho lingüístico fundamental de los/as ciudadanos/as del País Vasco.", "Una obligación lingüística de los/as ciudadanos/as del País Vasco.", "La Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera no lo prevé ni como derecho lingüístico ni como obligación lingüística.", "Esta Ley únicamente prevé el derecho a recibir en euskera publicaciones periódicas, pero no programaciones de radio y televisión o de otros medios de comunicación."], "e": "Es el texto literal del artículo.", "r": "Ley 10/1982 art. 5 · batería oficial, pregunta 135", "c": 0}]}, {"id": "t05", "sig": "Tema 5", "titulo": "Tema 5. Igualdad: LO 3/2007 (Título II) y Decreto Legislativo 1/2023 (Título Preliminar)", "sub": "Batería oficial.", "preguntas": [{"id": "gett05q01", "q": "De conformidad con el artículo 14 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, a los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos:", "o": ["La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo.", "La protección de la maternidad, con especial atención a la asunción por la sociedad de los efectos derivados del embarazo, parto y lactancia.", "El fomento de la efectividad del principio de igualdad entre mujeres y hombres en las relaciones entre particulares.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 14 · batería oficial, pregunta 136", "c": 3}, {"id": "gett05q02", "q": "Según el artículo 14 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, a los fines de esta Ley, serán criterios generales de actuación de los Poderes Públicos (señale la respuesta INCORRECTA):", "o": ["La adopción de las medidas necesarias para la erradicación de la violencia de género, la violencia familiar y todas las formas de acoso sexual y acoso por razón de sexo.", "La protección de la maternidad, con especial atención a la asunción por la sociedad de los efectos derivados del embarazo, parto y lactancia.", "El fomento de la efectividad del principio de igualdad entre mujeres y hombres en las relaciones entre particulares.", "La implantación de un lenguaje sexista en el ámbito administrativo y su fomento única y exclusivamente en las relaciones sociales."], "e": "Las demás opciones reproducen el texto del artículo.", "r": "LO 3/2007 art. 14 · batería oficial, pregunta 137", "c": 3}, {"id": "gett05q03", "q": "¿Qué debe incluir el Plan Estratégico de Igualdad de Oportunidades aprobado por el Gobierno según el art. 17 de la LO 3/2007, para la igualdad efectiva de Mujeres y Hombres?", "o": ["Medidas para fomentar la discriminación positiva hacia las mujeres.", "Medidas para promover los derechos exclusivos de las mujeres.", "Medidas para alcanzar la igualdad entre mujeres y hombres y eliminar la discriminación por razón de sexo.", "Medidas para reducir el salario de los hombres y fomentar la equidad salarial."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 · batería oficial, pregunta 138", "c": 2}, {"id": "gett05q04", "q": "En relación con la colaboración entre las Administraciones públicas, el art. 21 de la LO 3/2007, de 22 de marzo, para la igualdad efectiva de Mujeres y Hombres, establece que:", "o": ["La Administración General del Estado y las Administraciones de las Comunidades Autónomas cooperarán para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de sus respectivas competencias y, en especial, en sus actuaciones de planificación.", "En el seno de la Conferencia Sectorial de la Mujer podrán adoptarse planes y programas conjuntos de actuación con esta finalidad.", "Las Entidades Locales integrarán el derecho de igualdad en el ejercicio de sus competencias y colaborarán, a tal efecto, con el resto de las Administraciones públicas.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 · batería oficial, pregunta 139", "c": 3}, {"id": "gett05q05", "q": "De acuerdo con lo dispuesto en el artículo 23 de la Ley Orgánica 3/2007, de 22 de marzo, ¿qué debe incluir el sistema educativo en sus fines?", "o": ["La educación sobre los derechos laborales de las mujeres y hombres.", "La educación en el respeto de los derechos y libertades fundamentales, y en la igualdad de derechos y oportunidades entre mujeres y hombres.", "La educación exclusiva sobre igualdad de género en el ámbito familiar.", "La educación en la diferencia de derechos y oportunidades entre mujeres y hombres."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 23 · batería oficial, pregunta 140", "c": 1}, {"id": "gett05q06", "q": "Conforme al artículo 25 de la Ley Orgánica 3/2007, para la igualdad efectiva de Mujeres y Hombres, en particular, y con tal finalidad, las Administraciones públicas promoverán:", "o": ["La inclusión, en los planes de estudio en que proceda, de enseñanzas en materia de igualdad entre mujeres y hombres.", "La creación de postgrados específicos.", "La realización de estudios e investigaciones especializadas en la materia.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 25 · batería oficial, pregunta 141", "c": 3}, {"id": "gett05q07", "q": "Los distintos organismos, agencias, entes y demás estructuras de las administraciones públicas que de modo directo o indirecto configuren el sistema de gestión cultural, desarrollarán las siguientes actuaciones (artículo 26 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres):", "o": ["Políticas pasivas de ayuda a la creación y producción artística e intelectual de autoría femenina, traducidas en incentivos de naturaleza económica, con el objeto de crear las condiciones para que se produzca una efectiva igualdad de oportunidades.", "Promover una presencia mayoritaria de mujeres en la oferta artística y cultural pública.", "Que se respete y se garantice la representación equilibrada en los distintos órganos consultivos, científicos y de decisión existentes en el organigrama artístico y cultural.", "Participar en la elaboración de medidas puntuales para la creación y producción artística e intelectual de las mujeres, propiciando el intercambio cultural, intelectual y artístico, tanto nacional como internacional."], "e": "Art. 26.2.c. Las demás opciones alteran el texto: políticas activas (no pasivas) y presencia equilibrada (no mayoritaria).", "r": "LO 3/2007 art. 26 · batería oficial, pregunta 142", "c": 2}, {"id": "gett05q08", "q": "Según el artículo 15 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, el principio de igualdad de trato y oportunidades entre mujeres y hombres informará:", "o": ["Las actuaciones en materia educativa y sanitaria.", "Las políticas de igualdad exclusivamente.", "Con carácter transversal, la actuación de todos los poderes públicos.", "Sólo las decisiones de órganos especializados en igualdad."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 15 · batería oficial, pregunta 143", "c": 2}, {"id": "gett05q09", "q": "Siguiendo lo dispuesto en el artículo 15 de la Ley Orgánica 3/2007, ¿en qué ámbitos integrarán las Administraciones públicas, de forma activa, el principio de igualdad?", "o": ["En las políticas fiscales y de empleo.", "En la formación de personal directivo.", "En la adopción y ejecución de sus disposiciones normativas, en la definición y presupuestación de políticas públicas en todos los ámbitos y en el desarrollo del conjunto de todas sus actividades.", "En las campañas de comunicación institucional sobre igualdad."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 15 · batería oficial, pregunta 144", "c": 2}, {"id": "gett05q10", "q": "Conforme al artículo 16 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, en los nombramientos y designaciones de los cargos de responsabilidad que correspondan a los poderes públicos:", "o": ["Se priorizará a las mujeres por ser el grupo históricamente menos representado.", "Sólo se nombrará a mujeres hasta alcanzar el 50 % de representación.", "Se procurará atender al principio de presencia equilibrada de mujeres y hombres.", "Se atenderá exclusivamente a criterios de mérito y capacidad, sin considerar la presencia equilibrada."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 16 · batería oficial, pregunta 145", "c": 2}, {"id": "gett05q11", "q": "De acuerdo con el artículo 17 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, ¿qué debe incluir el Plan Estratégico de Igualdad de Oportunidades aprobado por el Gobierno?", "o": ["Medidas para fomentar la discriminación positiva en favor de la mujer.", "Medidas para alcanzar el objetivo de igualdad entre mujeres y hombres y eliminar la discriminación por razón de sexo.", "Medidas para garantizar el acceso preferente de mujeres a cargos públicos.", "Medidas para reducir las tasas de desempleo exclusivamente en mujeres."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 17 · batería oficial, pregunta 146", "c": 1}, {"id": "gett05q12", "q": "Conforme al artículo 18 de la Ley Orgánica 3/2007, de 22 de marzo, en los términos que reglamentariamente se determinen el Gobierno:", "o": ["Publicará un plan anual sobre políticas de igualdad entre mujeres y hombres.", "Elaborará un informe conjunto con las Comunidades Autónomas sobre violencia de género.", "Elaborará un informe periódico sobre el conjunto de sus actuaciones en relación con la efectividad del principio de igualdad entre mujeres y hombres.", "Emitirá un informe periódico sobre la representación equilibrada en los órganos constitucionales."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 18 · batería oficial, pregunta 147", "c": 2}, {"id": "gett05q13", "q": "Atendiendo al artículo 19 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, ¿qué deberán incorporar los proyectos de disposiciones de carácter general y los planes de especial relevancia económica, social, cultural y artística que se sometan a la aprobación del Consejo de Ministros?", "o": ["Un informe sobre el impacto medioambiental.", "Un informe sobre su impacto por razón de género.", "Un análisis comparado con otros países de la Unión Europea.", "Una memoria presupuestaria desglosada por sexos."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 19 · batería oficial, pregunta 148", "c": 1}, {"id": "gett05q14", "q": "Los poderes públicos deberán incluir sistemáticamente en sus estadísticas, encuestas y recogida de datos (artículo 20 de la Ley Orgánica 3/2007, de 22 de marzo):", "o": ["La variable de edad.", "La situación económica de los hogares.", "La variable de sexo.", "La nacionalidad de los participantes."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 20 · batería oficial, pregunta 149", "c": 2}, {"id": "gett05q15", "q": "De acuerdo con el artículo 20 de la Ley Orgánica 3/2007, ¿qué deberán establecer e incluir los poderes públicos en las operaciones estadísticas?", "o": ["Encuestas anuales específicas por Comunidades Autónomas.", "Nuevos indicadores que posibiliten un mejor conocimiento de las diferencias en los valores, roles, situaciones, condiciones, aspiraciones y necesidades de mujeres y hombres.", "Un sistema único de codificación de sexo y edad.", "Un análisis agregado sin distinción de género."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 20 · batería oficial, pregunta 150", "c": 1}, {"id": "gett05q16", "q": "Según el artículo 20 de la Ley Orgánica 3/2007, que regula la adecuación de las estadísticas y estudios para garantizar la integración efectiva de la perspectiva de género en la actividad ordinaria de los poderes públicos, señale la respuesta INCORRECTA:", "o": ["Incluir sistemáticamente la variable de sexo en las estadísticas, encuestas y recogida de datos que lleven a cabo.", "Diseñar e introducir los indicadores y mecanismos necesarios que permitan el conocimiento de la incidencia de otras variables cuya concurrencia resulta generadora de situaciones de discriminación múltiple en los diferentes ámbitos de intervención.", "Revisar y, en su caso, adecuar las definiciones estadísticas existentes con objeto de contribuir al reconocimiento y valoración del trabajo de las mujeres y evitar la estereotipación negativa de determinados colectivos de mujeres.", "Realizar únicamente estudios cuantitativos sin necesidad de incluir variables cualitativas en el análisis estadístico."], "e": "Las demás opciones reproducen el texto del artículo.", "r": "LO 3/2007 art. 20 · batería oficial, pregunta 151", "c": 3}, {"id": "gett05q17", "q": "Según el artículo 21.1 de la Ley Orgánica 3/2007, ¿qué administraciones cooperarán para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de sus competencias?", "o": ["La Administración General del Estado y las Administraciones de las Comunidades Autónomas.", "Las Entidades Locales y las Administraciones privadas.", "Los organismos internacionales y las Comunidades Autónomas.", "Las empresas públicas y privadas."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 21.1 · batería oficial, pregunta 152", "c": 0}, {"id": "gett05q18", "q": "Según el artículo 21.2 de la Ley Orgánica 3/2007, las Entidades Locales:", "o": ["Promoverán la igualdad de oportunidades únicamente en sus planes de empleo.", "Integrarán el derecho de igualdad en el ejercicio de sus competencias y colaborarán con el resto de las Administraciones públicas.", "Coordinarán exclusivamente con las Comunidades Autónomas.", "Delegarán la competencia en organismos privados."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 21.2 · batería oficial, pregunta 153", "c": 1}, {"id": "gett05q19", "q": "Según el artículo 22 de la Ley Orgánica 3/2007, ¿qué podrán establecer las corporaciones locales para avanzar hacia un reparto equitativo de los tiempos entre mujeres y hombres?", "o": ["Planes Nacionales de Igualdad.", "Planes Municipales de organización del tiempo de la ciudad.", "Programas exclusivos para mujeres.", "Planes de trabajo individualizados para cada ciudadano."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 22 · batería oficial, pregunta 154", "c": 1}, {"id": "gett05q20", "q": "De acuerdo con el artículo 22 de la Ley Orgánica 3/2007, ¿qué podrá hacer el Estado en relación con los Planes Municipales de organización del tiempo?", "o": ["Suplir completamente a las corporaciones locales en la elaboración de los planes.", "Prestar asistencia técnica para la elaboración de estos planes.", "Imponer directamente los planes sin consulta previa.", "Restringir la participación de las Comunidades Autónomas en dichos planes."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 22 · batería oficial, pregunta 155", "c": 1}, {"id": "gett05q21", "q": "Según el artículo 23 de la Ley Orgánica 3/2007, ¿qué incluirá el sistema educativo entre sus fines?", "o": ["La educación en valores patrióticos exclusivamente.", "La formación en habilidades técnicas para el mercado laboral.", "La educación en el respeto de los derechos y libertades fundamentales y en la igualdad de derechos y oportunidades entre mujeres y hombres.", "La educación exclusiva en igualdad entre mujeres."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 23 · batería oficial, pregunta 156", "c": 2}, {"id": "gett05q22", "q": "De acuerdo con el artículo 24 de la Ley Orgánica 3/2007, para la igualdad efectiva de mujeres y hombres, las Administraciones educativas, en el ámbito de sus respectivas competencias, desarrollarán, con tal finalidad, las siguientes actuaciones: (Indica la opción INCORRECTA)", "o": ["La atención especial en los currículos y en todas las etapas educativas al principio de igualdad entre mujeres y hombres.", "La cooperación con el resto de las Administraciones educativas para el desarrollo de proyectos y programas dirigidos a fomentar el conocimiento y la difusión, entre las personas de la comunidad educativa, de los principios de coeducación y de igualdad efectiva entre mujeres y hombres.", "La promoción de la presencia equilibrada de mujeres y hombres en los órganos de control y de gobierno de los centros docentes.", "La creación de incentivos económicos para centros que desarrollen planes de igualdad en la etapa de educación infantil."], "e": "El art. 24.2 no prevé incentivos económicos para centros de educación infantil.", "r": "LO 3/2007 art. 24 · batería oficial, pregunta 157", "c": 3}, {"id": "gett05q23", "q": "De acuerdo con el artículo 25 de la Ley Orgánica 3/2007, ¿qué promoverán las Administraciones públicas, en el ejercicio de sus competencias, en el ámbito de la educación superior?", "o": ["La creación de órganos independientes de control universitario en materia de igualdad.", "La obligatoriedad de cursar formación en igualdad en todas las titulaciones superiores.", "La inclusión, en los planes de estudio en que proceda, de enseñanzas en materia de igualdad entre mujeres y hombres.", "La implantación de asignaturas comunes de igualdad en la enseñanza secundaria y universitaria."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 25 · batería oficial, pregunta 158", "c": 2}, {"id": "gett05q24", "q": "Según el artículo 26.1 de la Ley Orgánica 3/2007, las autoridades públicas, en el ámbito de sus competencias:", "o": ["Deberán subvencionar de forma preferente las obras de autoría femenina.", "Estarán obligadas a garantizar la programación paritaria en centros culturales públicos.", "Velarán, por hacer efectivo el principio de igualdad de trato y de oportunidades entre mujeres y hombres en todo lo concerniente a la creación y producción artística e intelectual y a la difusión de la misma.", "Promoverán únicamente las actividades culturales que representen la diversidad de género en su contenido."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 26.1 · batería oficial, pregunta 159", "c": 2}, {"id": "gett05q25", "q": "De acuerdo con el apartado 2 del artículo 26 de la Ley Orgánica 3/2007, Los distintos organismos, agencias, entes y demás estructuras de las administraciones públicas que de modo directo o indirecto configuren el sistema de gestión cultural, desarrollarán las siguientes actuaciones: (indique la respuesta INCORRECTA)", "o": ["Adoptar iniciativas destinadas a favorecer la promoción específica de las mujeres en la cultura y a combatir su discriminación estructural y/o difusa.", "Exigir una representación mayoritaria femenina en todos los órganos de decisión cultural.", "Promover la presencia equilibrada de mujeres y hombres en la oferta artística y cultural pública.", "Adoptar medidas de acción positiva que propicien el intercambio cultural y la suscripción de convenios con organismos competentes."], "e": "El art. 26.2 habla de presencia equilibrada, no de representación mayoritaria femenina.", "r": "LO 3/2007 art. 26 · batería oficial, pregunta 160", "c": 1}, {"id": "gett05q26", "q": "Según el artículo 27 de la Ley Orgánica 3/2007, para la igualdad efectiva de mujeres y hombres, señale cuál de las siguientes actuaciones es una función de las Administraciones públicas en el ámbito de la política de salud:", "o": ["La promoción de programas de salud dirigidos exclusivamente a la mujer, con enfoque asistencial preferente.", "La adopción sistemática, dentro de las acciones de educación sanitaria, de iniciativas destinadas a favorecer la promoción específica de la salud de las mujeres, así como a prevenir su discriminación.", "El desarrollo de protocolos clínicos diferenciados para mujeres y hombres que atiendan a criterios de equidad biológica.", "La creación de unidades especializadas en violencia de género dentro del Sistema Nacional de Salud."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 27 · batería oficial, pregunta 161", "c": 1}, {"id": "gett05q27", "q": "Según el artículo 28 de la Ley Orgánica 3/2007, en relación con el desarrollo de la Sociedad de la Información:", "o": ["Los programas públicos estarán sujetos al cumplimiento obligatorio de cuotas de género en sus fases de ejecución.", "El lenguaje no sexista será recomendable en los contenidos creados por mujeres en el entorno digital.", "El Gobierno promoverá la plena incorporación de las mujeres en la Sociedad de la Información mediante el desarrollo de programas específicos, en especial, en materia de acceso y formación en tecnologías de la información y de las comunicaciones, contemplando las de colectivos de riesgo de exclusión y del ámbito rural.", "Las Administraciones públicas deberán garantizar que toda tecnología financiada públicamente reserve un porcentaje mínimo de acceso para mujeres."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 28 · batería oficial, pregunta 162", "c": 2}, {"id": "gett05q28", "q": "En relación con el artículo 29 de la Ley Orgánica 3/2007, ¿cuál de las siguientes afirmaciones refleja correctamente lo establecido en relación con el ámbito deportivo?", "o": ["El Gobierno garantizará la igualdad en la financiación de las federaciones deportivas femeninas y masculinas mediante una ley específica.", "Los programas deportivos dirigidos al público general deberán reservar un porcentaje de plazas a mujeres en todas las disciplinas.", "El Gobierno promoverá el deporte femenino y favorecerá la efectiva apertura de las disciplinas deportivas a las mujeres mediante el desarrollo de programas específicos en todas las etapas de la vida y en todos los niveles.", "Las federaciones deportivas deberán incluir obligatoriamente en sus estatutos un protocolo de igualdad en el acceso a cargos directivos y técnicos."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 29 · batería oficial, pregunta 163", "c": 2}, {"id": "gett05q29", "q": "Según el apartado 4 del artículo 30 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres: Las Administraciones públicas promoverán el desarrollo de una red de servicios sociales para atender a menores, mayores y dependientes como medida de __________ de la vida laboral, familiar y personal de hombres y mujeres en el mundo rural.", "o": ["Igualdad", "Conciliación", "Corresponsabilidad", "Protección"], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 30 · batería oficial, pregunta 164", "c": 1}, {"id": "gett05q30", "q": "En relación con el artículo 31 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres que dicta las políticas urbanas de ordenación del territorio y vivienda, las políticas urbanas y de ordenación del territorio tomarán en consideración:", "o": ["Las necesidades de distintos grupos sociales y de los diversos tipos de estructuras familiares.", "Dar prioridad a las zonas industriales.", "Favorecer el acceso a servicios solo para familias numerosas.", "Excluir la participación ciudadana en el planeamiento urbanístico."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 31 · batería oficial, pregunta 165", "c": 0}, {"id": "gett05q31", "q": "Según el artículo 32, apartado 1 de la Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, todas las políticas y planes de cooperación española para el desarrollo incluirán:", "o": ["Centrarse en el crecimiento económico como objetivo principal, considerando la igualdad de género solo como un aspecto secundario y no vinculante para la planificación estratégica.", "Incluir el principio de igualdad entre mujeres y hombres como un elemento sustancial en su agenda de prioridades.", "Priorizar aspectos territoriales y geográficos en la cooperación, sin incorporar sistemáticamente la perspectiva de género ni evaluar su impacto en los resultados.", "Omitir el establecimiento de mecanismos de seguimiento y evaluación específicos sobre igualdad de género, limitándose a informes generales de progreso."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 32 · batería oficial, pregunta 166", "c": 1}, {"id": "gett05q32", "q": "El artículo 33 de la Ley Orgánica 3/2007, indica que, las administraciones públicas, en el ámbito de sus respectivas competencias y, en relación con la ejecución de los contratos que celebren, podrán establecer ________ con el fin de promover la igualdad entre mujeres y hombres en el mercado de trabajo, de acuerdo con lo establecido en la legislación de contratos del sector público.", "o": ["Condiciones especiales", "Leyes.", "Obligaciones.", "Todas son correctas."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 33 · batería oficial, pregunta 167", "c": 0}, {"id": "gett05q33", "q": "Según el artículo 34 de la Ley Orgánica 3/2007, que redacta los contratos de la administración general del estado, el Consejo de Ministros determinará, ______ , a la vista de la evolución e impacto de las políticas de igualdad en el mercado laboral, los contratos de la Administración General del Estado y de sus organismos públicos que obligatoriamente deberán incluir entre sus condiciones de ejecución medidas tendentes a promover la igualdad efectiva entre mujeres y hombres en el mercado de trabajo, conforme a lo previsto en la legislación de contratos del sector público.", "o": ["Mensualmente.", "Trimestralmente.", "Anualmente.", "Semestralmente."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 34 · batería oficial, pregunta 168", "c": 2}, {"id": "gett05q34", "q": "Según el artículo 35 de la Ley Orgánica para la igualdad efectiva de mujeres y hombres, ¿qué aspectos podrán valorar las Administraciones públicas en las bases reguladoras de subvenciones para fomentar la igualdad?", "o": ["Únicamente la representación paritaria en los órganos de dirección de las entidades solicitantes.", "Solo las medidas que impliquen una reducción de jornada laboral para mujeres.", "Medidas de conciliación de la vida personal, laboral y familiar, responsabilidad social empresarial, o la obtención del distintivo empresarial en igualdad.", "El número de mujeres contratadas en los últimos cinco años, sin importar el tipo de contrato."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 35 · batería oficial, pregunta 169", "c": 2}, {"id": "gett05q35", "q": "Según lo dispuesto en el artículo 1 del Decreto Legislativo 1/2023, de 16 de marzo, ¿cuál de los siguientes enunciados recoge correctamente el objeto de la ley?", "o": ["Garantizar la igualdad salarial entre mujeres y hombres en el ámbito laboral exclusivamente.", "Regular únicamente las políticas públicas sobre violencia de género en el entorno familiar.", "Establecer los principios generales que han de presidir la actuación de los poderes públicos en materia de igualdad de mujeres y hombres, así como regular un conjunto de medidas dirigidas a promover y garantizar la igualdad de oportunidades y trato de mujeres y hombres en todos los ámbitos de la vida", "Crear un sistema judicial especializado para los delitos cometidos exclusivamente contra las mujeres en el entorno doméstico."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 1 · batería oficial, pregunta 170", "c": 2}, {"id": "gett05q36", "q": "Según el artículo 1 del Decreto Legislativo 1/2023, de 16 de marzo, ¿cuál de los siguientes aspectos forma parte del objeto de esta ley?", "o": ["Establecer medidas sancionadoras para casos de discriminación indirecta en la administración pública exclusivamente.", "Regular la representación femenina en el ámbito judicial y político de forma obligatoria.", "Eliminar la desigualdad estructural y todas las formas de discriminación por razón de sexo, incluida la violencia machista contra las mujeres.", "Crear un sistema de conciliación obligatorio para empresas privadas."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 1 · batería oficial, pregunta 171", "c": 2}, {"id": "gett05q37", "q": "Según el artículo 2.1 del Decreto Legislativo 1/2023, de 16 de marzo, la presente ley será de aplicación:", "o": ["Solo a la Administración de la Comunidad Autónoma del País Vasco.", "A todas las administraciones públicas vascas, sin excepción.", "A todas las administraciones públicas vascas, con las salvedades que a lo largo de ella se establezcan.", "Únicamente a los poderes públicos vascos que se recojan en el artículo 3."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 2.1 · batería oficial, pregunta 172", "c": 2}, {"id": "gett05q38", "q": "De acuerdo con el artículo 2.2 del Decreto Legislativo 1/2023, ¿cuál de los siguientes NO se incluye expresamente como Administración pública vasca?", "o": ["La Administración de la Comunidad Autónoma, sus organismos autónomos y entes públicos vinculados.", "La Administración foral, sus organismos autónomos y entes públicos dependientes.", "Las entidades privadas que colaboren con las administraciones públicas vascas.", "La Administración local, sus organismos autónomos y entes públicos vinculados."], "e": "Las demás opciones reproducen el texto del artículo.", "r": "DL 1/2023 art. 2.2 · batería oficial, pregunta 173", "c": 2}, {"id": "gett05q39", "q": "¿Cuál de los siguientes se considera poder público vasco según el artículo 2.3 del Decreto Legislativo 1/2023?", "o": ["Únicamente las administraciones públicas vascas y sus organismos autónomos.", "Solo las instituciones con capacidad legislativa y ejecutiva del País Vasco.", "Las administraciones públicas vascas, el Parlamento Vasco, las juntas generales, el Ararteko, el Tribunal Vasco de Cuentas Públicas y la Universidad del País Vasco.", "Únicamente el Gobierno Vasco y el Parlamento Vasco."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 2.3 · batería oficial, pregunta 174", "c": 2}, {"id": "gett05q40", "q": "Según el artículo 2.4 de la Ley 1/2023, ¿qué se exige a las entidades privadas que mantienen relación con los poderes públicos vascos mediante contratos, convenios o ayudas públicas?", "o": ["Únicamente la obligación de transparencia presupuestaria y rendición de cuentas.", "El cumplimiento, durante el tiempo y materia de su relación con el poder público, de los principios generales del artículo 3 y de los artículos 17 y 19.4.", "La participación activa en los planes de igualdad internos de los poderes públicos vascos.", "El compromiso de incorporar representación paritaria en sus órganos directivos."], "e": "La pregunta cita la «Ley 1/2023»; es el Decreto Legislativo 1/2023.", "r": "DL 1/2023 art. 2.4 · batería oficial, pregunta 175", "c": 1}, {"id": "gett05q41", "q": "¿Qué consecuencias puede tener el incumplimiento de las cláusulas para la igualdad incluidas en contratos, subvenciones o convenios con entidades privadas, según el artículo 2.5 del Real Decreto Legislativo 1/2023?", "o": ["El cierre inmediato de la entidad privada implicada.", "La imposición de penalidades, resolución de los correspondientes contratos o convenios o la minoración o devolución de las cantidades percibidas.", "La retirada temporal de la condición de entidad colaboradora del Gobierno Vasco.", "La publicación del incumplimiento en el Boletín Oficial del País Vasco."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 2.5 · batería oficial, pregunta 176", "c": 1}, {"id": "gett05q42", "q": "¿A qué otros ámbitos se aplica la presente ley, además de a los poderes públicos, según el artículo 2.6 del Real Decreto Legislativo 1/2023?", "o": ["Al sistema judicial y a las organizaciones sindicales.", "Al sistema educativo no universitario y a entidades religiosas.", "Al Sistema Universitario Vasco y al sector privado en los términos que a lo largo de ella se establecen.", "A las empresas públicas del Estado y al personal laboral interino."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 2.6 · batería oficial, pregunta 177", "c": 2}, {"id": "gett05q43", "q": "Según el artículo 3.1 del Decreto Legislativo 1/2023, ¿cuál de las siguientes situaciones constituye discriminación directa por razón de sexo?", "o": ["Cuando un acto jurídico neutro cause efectos negativos a más mujeres que hombres.", "Cuando se trate de forma menos favorable a una persona por razón de edad.", "Cuando una persona sea, haya sido o pudiera ser tratada de manera menos favorable que otra en situación análoga por razón de su sexo o de circunstancias directamente relacionadas con el sexo, como el embarazo o la maternidad.", "Cuando se establezca una política laboral con medidas de acción positiva."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 3.1 · batería oficial, pregunta 178", "c": 2}, {"id": "gett05q44", "q": "El artículo 3.2 del Real Decreto Legislativo 1/2023, de 16 de marzo, por el que se aprueba el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, indica que:", "o": ["Se adoptarán medidas para facilitar la participación de las personas con discapacidad en las políticas de igualdad.", "Se garantizará que los servicios públicos no impidan el acceso de las personas con necesidades especiales.", "Adoptaran las medidas oportunas para garantizar el ejercicio efectivo por parte de mujeres y hombres, en condiciones de igualdad, de los derechos políticos, civiles, económicos, laborales, sociales, culturales, medioambientales y del resto de derechos fundamentales que puedan ser reconocidos en las normas, incluido el control y acceso al poder y a los recursos y beneficios económicos y sociales.", "Velarán por que los derechos de las personas con discapacidad sean respetados en los procedimientos administrativos ordinarios."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 3.2 · batería oficial, pregunta 179", "c": 2}, {"id": "gett05q45", "q": "¿Qué se entiende por representación equilibrada en órganos de más de cuatro miembros, según el artículo 3.10?", "o": ["Que cada sexo esté representado en al menos un 30 % del órgano colegiado.", "Que haya al menos dos personas de cada sexo en los órganos plurales.", "Que en los órganos de más de cuatro miembros las personas de cada sexo están representadas al menos al 40 %.", "Que la representación de mujeres no sea inferior al 35 % para garantizar la equidad."], "e": "Es el texto literal del artículo.", "r": "LO 3/2007 art. 3.10 · batería oficial, pregunta 180", "c": 2}, {"id": "gett05q46", "q": "De acuerdo al artículo 3.12 del Real Decreto Legislativo 1/2023, de 16 de marzo, por el que se aprueba el texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres, el empoderamiento de la mujer es:", "o": ["Es el proceso mediante el cual las mujeres acceden a los mismos recursos y espacios que los hombres para alcanzar la igualdad de oportunidades.", "Es la toma de conciencia individual de su situación y su implicación en el cambio institucional.", "Es el proceso que estas llevan a cabo para la toma de conciencia individual y colectiva de la situación estructural de desigualdad y discriminación que sufren por el hecho de ser mujeres, y para la adquisición de la competencia, el poder y el control que les permitan tomar decisiones estratégicas sobre sus propias vidas y transformar las estructuras e instituciones que refuerzan y perpetúan la desigualdad y discriminación por razón de género en los distintos ámbitos de la vida.", "Es la facultad que adquieren las mujeres para decidir en todos los ámbitos políticos y económicos sin limitación alguna."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 3.12 · batería oficial, pregunta 181", "c": 2}, {"id": "gett05q47", "q": "El artículo 3.4 del Real Decreto Legislativo 1/2023, de 16 de marzo, redacta el respeto a la diversidad y a la diferencia. Y este indica que:", "o": ["Los poderes públicos adoptarán medidas que protejan la diversidad biológica, cultural y económica en la sociedad vasca.", "Los poderes públicos promoverán la igualdad sin atender a las diferencias internas entre mujeres y hombres.", "Los poderes públicos pondrán los medios necesarios para que el proceso hacia la igualdad de sexos se realice respetando tanto la diversidad y las diferencias existentes entre mujeres y hombres en cuanto a su biología, condiciones de vida, aspiraciones y necesidades, como la diversidad y diferencias existentes dentro de los propios grupos de mujeres y de hombres.", "Los poderes públicos garantizarán que la igualdad se aplique por igual, sin tener en cuenta diferencias individuales entre mujeres y hombres."], "e": "Es el texto literal del artículo.", "r": "DL 1/2023 art. 3.4 · batería oficial, pregunta 182", "c": 2}, {"id": "gett05q48", "q": "Según el artículo 3 del Decreto Legislativo 1/2023, de 16 de marzo, ¿cuál de los siguientes NO figura como uno de los principios generales que deben regir y orientar la actuación de los poderes públicos vascos en materia de igualdad de mujeres y hombres?", "o": ["Representación equilibrada.", "Empoderamiento de las mujeres.", "Conciliación de la vida laboral y familiar.", "Integración de la perspectiva interseccional."], "e": "El art. 3 recoge 16 principios; la conciliación no es uno de ellos.", "r": "DL 1/2023 art. 3 · batería oficial, pregunta 183", "c": 2}]}, {"id": "t06", "sig": "Tema 6", "titulo": "Tema 6. Ley 31/1995 de Prevención de Riesgos Laborales: Capítulo III", "sub": "Derechos y obligaciones. Batería oficial.", "preguntas": [{"id": "gett06q01", "q": "De conformidad con lo dispuesto en el artículo 14 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, los/as trabajadores/as tienen derecho a:", "o": ["Una protección eficaz en materia de seguridad y salud en el trabajo.", "Una prevención total en su trabajo y fuera de él.", "Una prevención laboral.", "Una información sobre su trabajo."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 14 · batería oficial, pregunta 184", "c": 0}, {"id": "gett06q02", "q": "Según el artículo 16 de la Ley 31/1995 de prevención de Riesgos Laborales, ¿cómo debe integrarse la prevención de riesgos laborales en una empresa?", "o": ["Debe ser una responsabilidad exclusiva de los/as trabajadores/as.", "Debe integrarse en el sistema general de gestión de la empresa, en todas sus actividades y niveles jerárquicos, mediante un plan de prevención.", "Debe integrarse únicamente en el nivel jerárquico más alto de la empresa.", "Debe ser gestionada solo por el departamento de recursos humanos."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 16 · batería oficial, pregunta 185", "c": 1}, {"id": "gett06q03", "q": "El empresario aplicará las medidas que integran el deber general de prevención previsto en el artículo 14 de la Ley 31/1995 de Prevención de Riesgos Laborales, con arreglo a los principios generales del artículo 15.1. Señale cuál de los siguientes principios NO se recogen en este artículo 15.1:", "o": ["Evitar los riesgos.", "Sustituir lo peligroso por lo que entrañe poco o ningún peligro.", "Adoptar medidas que antepongan la protección individual a la colectiva.", "Dar las debidas instrucciones a los/as trabajadores/as."], "e": "Art. 15.1.h: anteponer la protección colectiva a la individual.", "r": "Ley 31/1995 art. 14 · batería oficial, pregunta 186", "c": 2}, {"id": "gett06q04", "q": "De acuerdo con el artículo 22 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, el/la empresario/a garantizará a los/as trabajadores/as a su servicio la vigilancia periódica de su estado de salud en función de los riesgos inherentes al trabajo. Esta vigilancia sólo podrá llevarse a cabo:", "o": ["Cuando así lo decida unilateralmente el empresario.", "Cuando el/la trabajador/a no preste su consentimiento.", "Una vez cada dos años.", "Cuando el/la trabajador/a preste su consentimiento."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 22 · batería oficial, pregunta 187", "c": 3}, {"id": "gett06q05", "q": "Conforme al artículo 23 de la Ley 31/1995, de 8 de noviembre, de prevención de Riesgos Laborales, cuál de las siguientes NO deberá el empresario elaborar y conservar a disposición de la autoridad laboral:", "o": ["Planificación de la actividad preventiva, incluidas las medidas de protección y de prevención a adoptar y, en su caso, material de protección que deba utilizarse.", "Plan de prevención de riesgos laborales.", "Práctica de los controles del estado de salud de los/as trabajadores/as.", "Ficha de horario de entrada y salida de los/as trabajadores/as."], "e": "Las demás opciones reproducen el texto del artículo.", "r": "Ley 31/1995 art. 23 · batería oficial, pregunta 188", "c": 3}, {"id": "gett06q06", "q": "Siguiendo lo dispuesto en el artículo 27 de la Ley 31/1995, de 8 de noviembre, de prevención de Riesgos Laborales, el Gobierno establecerá las limitaciones a la contratación de:", "o": ["Jóvenes menores de dieciocho años en trabajos que no presenten riesgos específicos.", "Jóvenes menores de dieciocho años en trabajos que presenten riesgos específicos.", "Jóvenes menores de veinticinco años en trabajos que no presenten riesgos específicos.", "Jóvenes menores de veinticinco años en trabajos que presenten riesgos específicos."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 27 · batería oficial, pregunta 189", "c": 1}, {"id": "gett06q07", "q": "Los/as trabajadores/as con relaciones de trabajo temporales o de duración determinada, así como los/as contratados/as por empresas de trabajo temporal (artículo 28 de la Ley 31/1995, de 8 de noviembre, de prevención de Riesgos Laborales):", "o": ["Deberán disfrutar del mismo nivel de protección en materia de seguridad y salud que los restantes trabajadores de la empresa en la que prestan sus servicios.", "Deberán disfrutar de un mayor nivel de protección en materia de seguridad y salud que los restantes trabajadores de la empresa en la que prestan sus servicios.", "Deberán disfrutar de un menor nivel de protección en materia de seguridad y salud que los restantes trabajadores de la empresa en la que prestan sus servicios.", "No deberán disfrutar ningún tipo de protección en materia de seguridad y salud."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 28 · batería oficial, pregunta 190", "c": 0}, {"id": "gett06q08", "q": "Señale la respuesta INCORRECTA respecto a los equipos de trabajo y medios de protección (artículo 17 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales):", "o": ["El empresario adoptará las medidas necesarias con el fin de que los equipos de trabajo sean adecuados para el trabajo que deba realizarse y convenientemente adaptados a tal efecto, de forma que garanticen la seguridad y la salud de los/as trabajadores/as al utilizarlos.", "Cuando la utilización de un equipo de trabajo pueda presentar un riesgo específico para la seguridad y la salud de los trabajadores, el empresario adoptará las medidas necesarias con el fin de que los trabajos de reparación, transformación, mantenimiento o conservación sean realizados por trabajadores/as de la empresa subcontratista.", "El empresario deberá proporcionar a sus trabajadores equipos de protección individual adecuados para el desempeño de sus funciones y velar por el uso efectivo de los mismos cuando, por la naturaleza de los trabajos realizados, sean necesarios.", "Los equipos de protección individual deberán utilizarse cuando los riesgos no se puedan evitar o no puedan limitarse suficientemente por medios técnicos de protección colectiva o mediante medidas, métodos o procedimientos de organización del trabajo."], "e": "Art. 17.1.b: esos trabajos los hacen los trabajadores específicamente capacitados para ello.", "r": "Ley 31/1995 art. 17 · batería oficial, pregunta 191", "c": 1}, {"id": "gett06q09", "q": "De acuerdo con lo dispuesto en el artículo 29 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, es obligación del/la trabajador/a:", "o": ["Utilizar correctamente los medios y equipos de protección que ha comprado para protegerse de los riesgos del trabajo.", "Cooperar con el empresario para la realización del trabajo con la máxima eficacia y rendimiento económico.", "Utilizar correctamente los medios y equipos de protección facilitados por el empresario, de acuerdo con las instrucciones recibidas de éste.", "El/la trabajador/a no tiene obligaciones, son del empresario."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 29 · batería oficial, pregunta 192", "c": 2}, {"id": "gett06q10", "q": "Cuando los/as trabajadores/as estén o puedan estar expuestos a un riesgo grave e inminente con ocasión de su trabajo, el empresario estará obligado a: (Artículo 21 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales)", "o": ["Informar lo antes posible a todos los/as trabajadores/as afectados acerca de la existencia de dicho riesgo y de las medidas adoptadas o que, en su caso, deban adoptarse en materia de protección.", "Adoptar las medidas y dar las instrucciones necesarias para que, en caso de peligro grave, inminente e inevitable, los/as trabajadores/as puedan interrumpir su actividad y, si fuera necesario, abandonar de inmediato el lugar de trabajo.", "Disponer lo necesario para que el/la trabajador/a que no pudiera ponerse en contacto con su superior jerárquico, ante una situación de peligro grave e inminente para su seguridad, la de otros/as trabajadores/as o la de terceros a la empresa, esté en condiciones, habida cuenta de sus conocimientos y de los medios técnicos puestos a su disposición, de adoptar las medidas necesarias para evitar las consecuencias de dicho peligro.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 21 · batería oficial, pregunta 193", "c": 3}, {"id": "gett06q11", "q": "Conforme al artículo 15 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, relativo a los principios de acción preventiva, señale la respuesta INCORRECTA:", "o": ["El empresario/a tomará en consideración las capacidades profesionales de los/as trabajadores/as en materia de seguridad y de salud en el momento de encomendarles las tareas.", "El empresario/a adoptará las medidas necesarias a fin de garantizar que sólo los/as trabajadores/as que hayan recibido información suficiente y adecuada puedan acceder a las zonas de riesgo grave y específico.", "La efectividad de las medidas preventivas no preverá las distracciones o imprudencias no temerarias que pudiera cometer el/la trabajador/a.", "El empresario aplicará las medidas que integran el deber general de prevención previsto en el artículo 14, con arreglo al principio de evaluar los riesgos que no se puedan evitar, entre otros principios."], "e": "Art. 15.4: la efectividad de las medidas preventivas deberá prever las distracciones o imprudencias no temerarias.", "r": "Ley 31/1995 art. 15 · batería oficial, pregunta 194", "c": 2}, {"id": "gett06q12", "q": "Según el artículo 18 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, el empresario/a deberá consultar a los/as trabajadores/as, y permitir su participación en el marco de todas las cuestiones que afecten a:", "o": ["La seguridad y a la salud en el trabajo, de conformidad con lo dispuesto en el capítulo V de la presente Ley.", "Aspectos medioambientales de la empresa, de conformidad con lo dispuesto en el capítulo IV de la presente Ley.", "La seguridad y a la salud en el trabajo, de conformidad con lo dispuesto en el capítulo IV de la presente Ley.", "Aspectos medioambientales de la empresa, de conformidad con lo dispuesto en el capítulo V de la presente Ley."], "e": "Art. 18.2: de conformidad con el capítulo V (consulta y participación de los trabajadores).", "r": "Ley 31/1995 art. 18 · batería oficial, pregunta 195", "c": 0}, {"id": "gett06q13", "q": "En relación a la protección de trabajadores/as especialmente sensibles a determinados riesgos a que se refiere el artículo 25 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales:", "o": ["El empresario garantizará de manera específica la protección de los/as trabajadores/as que, por sus propias características personales o estado biológico conocido, incluidos aquellos que tengan reconocida la situación de discapacidad física, psíquica o sensorial, sean especialmente sensibles a los riesgos derivados del trabajo.", "El empresario podrá garantizar de manera general la protección de los/as trabajadores/as que, por sus propias características personales o estado biológico conocido, incluidos aquellos que tengan reconocida la situación de discapacidad física, psíquica o sensorial, sean especialmente sensibles a los riesgos derivados del trabajo.", "A tal fin, podrá tener en cuenta dichos aspectos en las evaluaciones de los riesgos y, en función de éstas, podrá adoptar las medidas preventivas y de protección necesarias.", "A tal fin, no tendrá tener en cuenta dichos aspectos en las evaluaciones de los riesgos y, en función de éstas, no tendrá que adoptar las medidas preventivas y de protección necesarias."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 25 · batería oficial, pregunta 196", "c": 0}, {"id": "gett06q14", "q": "De conformidad con el artículo 26 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, las trabajadoras embarazadas tendrán derecho a ausentarse del trabajo, con derecho a remuneración, para:", "o": ["La realización de exámenes prenatales y técnicas de preparación al parto, sin previo aviso al empresario y sin obligación de justificar la necesidad de su realización dentro de la jornada de trabajo.", "La realización de exámenes prenatales y técnicas de preparación al parto, previo aviso al empresario y justificación de la necesidad de su realización dentro de la jornada de trabajo.", "La realización de exámenes prenatales y técnicas de preparación al parto, sin previo aviso al empresario, pero debiendo justificar la necesidad de su realización dentro de la jornada de trabajo.", "La realización de exámenes prenatales y técnicas de preparación al parto, previo aviso al empresario, pero sin obligación de justificar la necesidad de su realización dentro de la jornada de trabajo."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 26 · batería oficial, pregunta 197", "c": 1}, {"id": "gett06q15", "q": "Según el artículo 29 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, los/as trabajadores/as, con arreglo a su formación y siguiendo las instrucciones del empresario, deberán en particular:", "o": ["Utilizar correctamente los medios y equipos de protección facilitados por el empresario, de acuerdo con las instrucciones recibidas de éste.", "Contribuir al cumplimiento de las obligaciones establecidas por la autoridad competente con el fin de proteger la seguridad y la salud de los/as trabajadores/as en el trabajo.", "Cooperar con el empresario para que éste pueda garantizar unas condiciones de trabajo que sean seguras y no entrañen riesgos para la seguridad y la salud de los/as trabajadores/as.", "Todas las respuestas anteriores son correctas."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 29 · batería oficial, pregunta 198", "c": 3}, {"id": "gett06q16", "q": "De conformidad con el artículo 20 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales, el empresario, teniendo en cuenta el tamaño y la actividad de la empresa, así como la posible presencia de personas ajenas a la misma, deberá analizar las posibles situaciones de emergencia y adoptar las medidas necesarias en materia de:", "o": ["Primeros auxilios, lucha contra incendios y evacuación de los/as trabajadores/as.", "Primeros auxilios y lucha contra incendios, salvo en materia de evacuación de los/as trabajadores/as.", "Primeros auxilios y evacuación de los/as trabajadores, salvo en materia de lucha contra incendios.", "Primeros auxilios únicamente."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 20 · batería oficial, pregunta 199", "c": 0}, {"id": "gett06q17", "q": "Según el artículo 22.2 de la Ley de Prevención de Riesgos Laborales, ¿cómo deben llevarse a cabo las medidas de vigilancia y control de la salud de los trabajadores?", "o": ["Deben realizarse sin la obligación de respetar el derecho a la intimidad de el/la trabajador/a.", "Deben realizarse respetando el derecho a la intimidad, la dignidad del/la trabajador/a y la confidencialidad de la información relacionada con su salud.", "Deben realizarse sin informar al/la trabajador/a sobre su estado de salud.", "Deben realizarse solo con el consentimiento explícito del empleador."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 22.2 · batería oficial, pregunta 200", "c": 1}, {"id": "gett06q18", "q": "Los datos relativos a la vigilancia de la salud de los/as trabajadores/as de acuerdo a lo previsto en el artículo 22 de la Ley de Prevención de Riesgos laborales:", "o": ["No podrán ser usados con fines discriminatorios ni en perjuicio del/la trabajador/a.", "Podrán ser usados con fines discriminatorios o en perjuicio del/la trabajador/a en algunas ocasiones.", "Podrán ser usados con fines discriminatorios o en perjuicio del/la trabajador/a en cualquier caso.", "No podrán ser usados con fines discriminatorios, pero sí en perjuicio del/la trabajador/a en caso de incumplimiento de alguno de sus deberes legales."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 22 · batería oficial, pregunta 201", "c": 0}, {"id": "gett06q19", "q": "Cuando en un mismo centro de trabajo desarrollen actividades trabajadores/as de dos o más empresas (artículo 24 de la Ley de Prevención de Riesgos Laborales):", "o": ["Éstas no tendrán que cooperar en la aplicación de la normativa sobre prevención de riesgos laborales.", "Éstas podrán cooperar en la aplicación de la normativa sobre prevención de riesgos laborales.", "Éstas deberán cooperar en la aplicación de la normativa sobre prevención de riesgos laborales.", "Ninguna de las respuestas anteriores es correcta."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 24 · batería oficial, pregunta 202", "c": 2}, {"id": "gett06q20", "q": "En cumplimiento del artículo 14 de la Ley de Prevención de Riesgos Laborales el coste de las medidas relativas a la seguridad y la salud en el trabajo:", "o": ["Podrá recaer totalmente sobre los/as trabajadores/as.", "No deberá recaer en modo alguno sobre los/as trabajadores/as.", "Podrá recaer parcialmente sobre los/as trabajadores/as.", "Podrá recaer sobre los/as trabajadores/as que presten su consentimiento expreso y escrito."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 14 · batería oficial, pregunta 203", "c": 1}, {"id": "gett06q21", "q": "Según el artículo 17 de la Ley de Prevención de Riesgos Laborales, cuando la utilización de un equipo de trabajo pueda presentar un riesgo específico para la seguridad y salud de los/as trabajadores/as, el empresario deberá:", "o": ["Permitir que cualquier trabajador/a utilice el equipo siempre que lo necesite.", "Dejar la responsabilidad del uso seguro del equipo exclusivamente en manos del/la trabajador/a.", "Adoptar las medidas necesarias para que sólo los/as trabajadores/as específicamente capacitados para ello realicen tareas de reparación, mantenimiento o conservación del equipo, y reservar su utilización a los/as encargados/as designados/as.", "Externalizar todas las tareas relacionadas con el equipo para evitar responsabilidades."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 17 · batería oficial, pregunta 204", "c": 2}, {"id": "gett06q22", "q": "De conformidad con el artículo 16 de la Ley de Prevención de Riesgos Laborales, las empresas, en atención al número de trabajadores/as y a la naturaleza y peligrosidad de las actividades realizadas, podrán realizar el plan de prevención de riesgos laborales, la evaluación de riesgos y la planificación de la actividad preventiva:", "o": ["De forma simplificada, siempre que ello no suponga una reducción del nivel de protección de la seguridad y salud de los/as trabajadores/as y en los términos que reglamentariamente se determinen.", "De forma simplificada, aunque ello suponga una reducción del nivel de protección de la seguridad y salud de los/as trabajadores/as y en los términos que reglamentariamente se determinen.", "De forma general, aunque ello suponga una reducción del nivel de protección de la seguridad y salud de los/as trabajadores/as y en los términos que se determinen por ley.", "De forma general, siempre que ello no suponga una reducción del nivel de protección de la seguridad y salud de los/as trabajadores/as y en los términos que se determinen exclusivamente mediante ley orgánica."], "e": "Es el texto literal del artículo.", "r": "Ley 31/1995 art. 16 · batería oficial, pregunta 205", "c": 0}]}, {"id": "t07", "sig": "Tema 7", "titulo": "Tema 7. Ley 39/2015: interesados y actividad de las Administraciones (Títulos I y II)", "sub": "Segunda prueba.", "preguntas": [], "incluye": ["getxo-administrativo/t09", "biblioteca-dfb/t06"]}, {"id": "t08", "sig": "Tema 8", "titulo": "Tema 8. Ley 39/2015: los actos administrativos (Título III)", "sub": "Segunda prueba.", "preguntas": [], "incluye": ["getxo-administrativo/t12"]}, {"id": "t09", "sig": "Tema 9", "titulo": "Tema 9. Ley 40/2015: disposiciones generales, órganos y potestad sancionadora (Título Preliminar, Caps. I a III)", "sub": "Segunda prueba.", "preguntas": [], "incluye": ["getxo-administrativo/t17", "getxo-administrativo/t18:1-12"]}, {"id": "t10", "sig": "Tema 10", "titulo": "Tema 10. Ley 40/2015: responsabilidad patrimonial (Título Preliminar, Cap. IV)", "sub": "Segunda prueba.", "preguntas": [], "incluye": ["getxo-administrativo/t18:13-30"]}, {"id": "t11", "sig": "Tema 11", "titulo": "Tema 11. LO 3/2018 de protección de datos (Títulos I, II y III)", "sub": "Segunda prueba.", "preguntas": [], "incluye": ["getxo-administrativo/t07"]}, {"id": "t12", "sig": "Tema 12", "titulo": "Tema 12. Ley 19/2013 de transparencia (Título I)", "sub": "Segunda prueba.", "preguntas": [{"id": "gett12q01", "q": "¿Cuál es el objeto de la Ley 19/2013, de 9 de diciembre?", "o": ["Ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información y establecer las obligaciones de buen gobierno", "Regular el procedimiento administrativo común", "Proteger los datos personales", "Regular el régimen jurídico del sector público"], "e": "Se llama Ley de transparencia, acceso a la información pública y buen gobierno.", "r": "Ley 19/2013 art. 1"}, {"id": "gett12q02", "q": "¿A cuál de estas entidades NO se aplica el Título I de la Ley 19/2013 como sujeto del art. 2.1?", "o": ["Una empresa privada sin subvenciones públicas", "Las entidades que integran la Administración Local", "Los organismos autónomos", "Las sociedades mercantiles con participación pública mayoritaria"], "e": "Las privadas solo quedan obligadas a la publicidad activa si reciben ayudas o subvenciones en las cuantías del art. 3.", "r": "Ley 19/2013 art. 2"}, {"id": "gett12q03", "q": "Las entidades privadas deben cumplir la publicidad activa si en un año perciben ayudas o subvenciones públicas superiores a:", "o": ["100.000 euros, o cuando al menos el 40 % de sus ingresos anuales sean ayuda pública, siempre que alcancen como mínimo 5.000 euros", "50.000 euros en todo caso", "10.000 euros", "100.000 euros, sin otra alternativa"], "e": "También los partidos políticos, sindicatos y organizaciones empresariales.", "r": "Ley 19/2013 art. 3"}, {"id": "gett12q04", "q": "Las personas que presten servicios públicos o ejerzan potestades administrativas están obligadas a:", "o": ["Suministrar a la Administración a la que estén vinculadas, previo requerimiento, toda la información necesaria para que cumpla sus obligaciones", "Publicar toda su información en su web", "Crear su propio portal de transparencia", "Nada; la ley no les afecta"], "e": "Lo mismo los adjudicatarios de contratos del sector público.", "r": "Ley 19/2013 art. 4"}, {"id": "gett12q05", "q": "La información sujeta a publicidad activa se publicará:", "o": ["En las sedes electrónicas o páginas web, de forma clara, estructurada y entendible, preferiblemente en formatos reutilizables", "Solo en el boletín oficial", "En el tablón de anuncios físico", "Solo cuando la pida un ciudadano"], "e": "Art. 5.4.", "r": "Ley 19/2013 art. 5.4"}, {"id": "gett12q06", "q": "¿Qué límites se aplican a la publicidad activa?", "o": ["Los límites al derecho de acceso del art. 14 y la protección de datos del art. 15", "Ninguno", "Solo el secreto oficial", "Los que fije cada Administración libremente"], "e": "Si la información contiene datos especialmente protegidos, solo se publica previa disociación.", "r": "Ley 19/2013 art. 5.3"}, {"id": "gett12q07", "q": "La información institucional, organizativa y de planificación incluye:", "o": ["Las funciones, la normativa aplicable y la estructura organizativa, con un organigrama actualizado", "Los contratos y convenios", "Los presupuestos", "Las subvenciones concedidas"], "e": "Art. 6. Los contratos, convenios, subvenciones y presupuestos son información económica, presupuestaria y estadística (art. 8).", "r": "Ley 19/2013 art. 6"}, {"id": "gett12q08", "q": "¿Qué información de relevancia jurídica deben publicar las Administraciones según el art. 7?", "o": ["Las directrices, instrucciones y circulares que supongan una interpretación del Derecho, y los anteproyectos y proyectos normativos", "Las sentencias de todos los tribunales", "Los informes internos de cualquier tipo", "Los borradores no aprobados de cualquier documento"], "e": "También las memorias e informes de los expedientes normativos y los documentos sometidos a información pública.", "r": "Ley 19/2013 art. 7"}, {"id": "gett12q09", "q": "La información de los contratos menores puede publicarse:", "o": ["Al menos trimestralmente", "Cada año", "Cada mes", "No se publican"], "e": "Art. 8.1.a.", "r": "Ley 19/2013 art. 8.1.a"}, {"id": "gett12q10", "q": "¿Qué retribuciones deben publicarse según el art. 8?", "o": ["Las retribuciones anuales de los altos cargos y máximos responsables de las entidades", "Las de todos los empleados públicos con nombre y apellidos", "Solo las de los funcionarios de carrera", "Ninguna"], "e": "También las indemnizaciones por el abandono del cargo.", "r": "Ley 19/2013 art. 8.1.f"}, {"id": "gett12q11", "q": "El Portal de la Transparencia de la Administración General del Estado depende de:", "o": ["El Ministerio de la Presidencia", "El Consejo de Transparencia y Buen Gobierno", "El Ministerio de Hacienda", "Las Cortes Generales"], "e": "Art. 10.", "r": "Ley 19/2013 art. 10"}, {"id": "gett12q12", "q": "¿Qué se entiende por información pública según el art. 13?", "o": ["Los contenidos o documentos, cualquiera que sea su formato o soporte, que obren en poder de los sujetos del Título I y que hayan sido elaborados o adquiridos en el ejercicio de sus funciones", "Solo los documentos publicados en el BOE", "Solo la información de expedientes terminados", "Cualquier información de interés general, esté o no en poder de la Administración"], "e": "Es el objeto del derecho de acceso.", "r": "Ley 19/2013 art. 13"}, {"id": "gett12q13", "q": "¿Cuál de estos NO es un límite al derecho de acceso del art. 14?", "o": ["El interés del solicitante en publicar la información en prensa", "La seguridad nacional", "La protección del medio ambiente", "El secreto profesional y la propiedad intelectual e industrial"], "e": "Son doce límites; su aplicación debe ser justificada, proporcionada y atender al interés público o privado superior.", "r": "Ley 19/2013 art. 14"}, {"id": "gett12q14", "q": "Si la información solicitada contiene datos especialmente protegidos de ideología, afiliación sindical, religión o creencias, el acceso:", "o": ["Solo se autoriza con el consentimiento expreso y por escrito del afectado, salvo que este los hubiera hecho públicos", "Se concede siempre", "Nunca se concede", "Se concede si lo autoriza el Consejo de Transparencia"], "e": "Art. 15.1.", "r": "Ley 19/2013 art. 15.1"}, {"id": "gett12q15", "q": "Cuando la aplicación de un límite no afecta a toda la información, se concede:", "o": ["Acceso parcial, omitiendo la información afectada por el límite", "Acceso total", "La denegación completa", "Acceso solo presencial"], "e": "Salvo que de ello resulte una información distorsionada o que carezca de sentido.", "r": "Ley 19/2013 art. 16"}, {"id": "gett12q16", "q": "La solicitud de acceso a la información:", "o": ["No necesita motivación, aunque el solicitante puede exponer sus motivos", "Debe estar siempre motivada", "Requiere acreditar interés legítimo", "Solo puede presentarse en papel"], "e": "La ausencia de motivación no es por sí sola causa de rechazo.", "r": "Ley 19/2013 art. 17.3"}, {"id": "gett12q17", "q": "¿Cuál de estas es una causa de inadmisión de las solicitudes de acceso?", "o": ["Que sean manifiestamente repetitivas o tengan un carácter abusivo no justificado con la finalidad de transparencia", "Que el solicitante no sea español", "Que no se indique el motivo", "Que la información sea antigua"], "e": "También la información en curso de elaboración, la de carácter auxiliar o la que exija una acción previa de reelaboración.", "r": "Ley 19/2013 art. 18"}, {"id": "gett12q18", "q": "Si la información puede afectar a derechos o intereses de terceros identificados, se les concede un plazo para alegar de:", "o": ["Quince días", "Diez días", "Un mes", "Cinco días"], "e": "El plazo para resolver se suspende hasta recibir las alegaciones o vencer el plazo.", "r": "Ley 19/2013 art. 19.3"}, {"id": "gett12q19", "q": "¿En qué plazo debe resolverse y notificarse una solicitud de acceso a la información según la Ley 19/2013?", "o": ["Un mes, ampliable otro mes por el volumen o la complejidad de la información", "Quince días", "Tres meses", "Diez días"], "e": "Desde la recepción de la solicitud por el órgano competente.", "r": "Ley 19/2013 art. 20.1"}, {"id": "gett12q20", "q": "Si no se resuelve en plazo una solicitud de acceso, se entiende:", "o": ["Desestimada", "Estimada", "Caducada", "Remitida al Consejo de Transparencia"], "e": "Art. 20.4.", "r": "Ley 19/2013 art. 20.4"}, {"id": "gett12q21", "q": "El acceso a la información es, como regla general:", "o": ["Gratuito, aunque la expedición de copias o la transposición a otros formatos puede dar lugar a tasas o precios", "De pago en todo caso", "Gratuito solo para personas físicas", "Gratuito solo en papel"], "e": "Art. 22.4. Se realizará preferentemente por vía electrónica.", "r": "Ley 19/2013 art. 22"}, {"id": "gett12q22", "q": "Contra las resoluciones en materia de acceso, con carácter potestativo y previo al contencioso, cabe:", "o": ["Reclamación ante el Consejo de Transparencia y Buen Gobierno, en el plazo de un mes", "Recurso de alzada en tres meses", "Recurso extraordinario de revisión", "Reclamación económico-administrativa"], "e": "El Consejo debe resolver en tres meses; si no lo hace, la reclamación se entiende desestimada.", "r": "Ley 19/2013 art. 24"}]}, {"id": "t13", "sig": "Tema 13", "titulo": "Tema 13. La comunicación en la Administración. Lenguaje administrativo y no sexista", "sub": "Segunda prueba (temario IVAP).", "preguntas": [{"id": "gett13q01", "q": "En el proceso de comunicación, el conjunto de signos y reglas que comparten emisor y receptor se llama:", "o": ["Código", "Canal", "Contexto", "Mensaje"], "e": "Elementos: emisor, receptor, mensaje, código, canal, contexto y retroalimentación.", "r": "Elementos de la comunicación"}, {"id": "gett13q02", "q": "El medio físico por el que se transmite el mensaje (papel, teléfono, correo electrónico) es el:", "o": ["Canal", "Código", "Contexto", "Referente"], "e": "Los obstáculos que dificultan la comunicación se llaman ruido o barreras.", "r": "Elementos de la comunicación"}, {"id": "gett13q03", "q": "La respuesta del receptor que permite al emisor saber si el mensaje se ha entendido se llama:", "o": ["Retroalimentación (feedback)", "Ruido", "Codificación", "Canal"], "e": "Sin retroalimentación, la comunicación es unidireccional.", "r": "Elementos de la comunicación"}, {"id": "gett13q04", "q": "La comunicación que va de los órganos superiores a los inferiores de una organización (órdenes, instrucciones, circulares) es la comunicación:", "o": ["Descendente", "Ascendente", "Horizontal", "Externa"], "e": "La ascendente va de abajo arriba (informes, sugerencias); la horizontal, entre unidades del mismo nivel.", "r": "Comunicación en la organización"}, {"id": "gett13q05", "q": "Las instrucciones y órdenes de servicio con las que los órganos administrativos dirigen la actividad de sus órganos jerárquicamente dependientes están reguladas en:", "o": ["El art. 6 de la Ley 40/2015", "El art. 21 de la Ley 39/2015", "El art. 103 de la Constitución", "El art. 14 de la Ley 39/2015"], "e": "Cuando una disposición específica así lo establezca, se publican en el boletín oficial correspondiente.", "r": "Ley 40/2015 art. 6"}, {"id": "gett13q06", "q": "¿Cuál de estas es una característica deseable del lenguaje administrativo actual?", "o": ["Claridad y sencillez, para que la ciudadanía entienda el mensaje", "Uso abundante de arcaísmos y fórmulas fijas", "Frases muy largas y subordinadas", "Abuso de la voz pasiva y de los tecnicismos"], "e": "Es la idea del lenguaje claro: frases cortas, orden lógico, vocabulario común y voz activa.", "r": "Lenguaje administrativo"}, {"id": "gett13q07", "q": "¿Cuál de estos rasgos se considera un defecto tradicional del lenguaje administrativo?", "o": ["El uso excesivo de gerundios y de construcciones impersonales", "El orden lógico sujeto-verbo-complemento", "El uso de párrafos breves", "Dirigirse directamente al destinatario"], "e": "Otros defectos: perífrasis innecesarias, arcaísmos («otrosí», «a tenor de»), latinismos y abreviaturas no explicadas.", "r": "Lenguaje administrativo"}, {"id": "gett13q08", "q": "En un escrito administrativo, la forma de tratamiento recomendada hoy hacia la ciudadanía es:", "o": ["Un trato respetuoso y cercano, evitando fórmulas arcaicas", "«Ilustrísimo Señor» para cualquier persona", "El tuteo en todos los casos", "No dirigirse nunca al destinatario"], "e": "Los tratamientos protocolarios solo se usan cuando corresponde al cargo.", "r": "Lenguaje administrativo"}, {"id": "gett13q09", "q": "El documento por el que un órgano comunica una información a otro órgano de la misma Administración, de forma sencilla e interna, es:", "o": ["La nota interior", "El oficio", "La certificación", "La diligencia"], "e": "El oficio se usa para comunicaciones formales entre órganos de distintas Administraciones o con particulares.", "r": "Documentos administrativos"}, {"id": "gett13q10", "q": "El documento que deja constancia de lo tratado y acordado en una sesión de un órgano colegiado es:", "o": ["El acta", "La certificación", "El informe", "La diligencia"], "e": "La extiende el secretario del órgano (art. 18 Ley 40/2015).", "r": "Documentos administrativos"}, {"id": "gett13q11", "q": "El uso de un lenguaje no sexista en la Administración vasca es una obligación recogida en:", "o": ["El texto refundido de la Ley para la Igualdad de Mujeres y Hombres (Decreto Legislativo 1/2023)", "La Ley 39/2015", "El Estatuto de Autonomía", "La Ley 10/1982 del euskera"], "e": "Los poderes públicos deben hacer un uso no sexista de todo tipo de lenguaje en los documentos y soportes que produzcan.", "r": "DL 1/2023"}, {"id": "gett13q12", "q": "¿Cuál de estas expresiones es un ejemplo de lenguaje no sexista?", "o": ["«La ciudadanía» en lugar de «los ciudadanos»", "«Los funcionarios» para referirse a toda la plantilla", "«El hombre» para referirse a la humanidad", "«Señorita» para las mujeres solteras"], "e": "Se recomiendan los genéricos reales y colectivos: el personal, el alumnado, la ciudadanía, las personas usuarias.", "r": "Lenguaje no sexista"}, {"id": "gett13q13", "q": "En lenguaje no sexista, ¿qué alternativa se recomienda a «los interesados»?", "o": ["«Las personas interesadas»", "«Los/as interesados/as» en todo el texto", "«L@s interesad@s»", "«Los interesados» con una nota a pie de página"], "e": "Las barras y la arroba dificultan la lectura; se recomiendan sustantivos genéricos o la palabra «persona».", "r": "Lenguaje no sexista"}, {"id": "gett13q14", "q": "En un formulario administrativo, para evitar el masculino genérico, se recomienda:", "o": ["Usar fórmulas abiertas como «Nombre y apellidos» o «Firma de la persona solicitante»", "Escribir siempre «el solicitante»", "Usar la arroba", "Dejar el texto solo en masculino"], "e": "Es una de las pautas habituales de las guías de lenguaje no sexista.", "r": "Lenguaje no sexista"}, {"id": "gett13q15", "q": "En la comunicación escrita con la ciudadanía en Euskadi, las comunicaciones de las Administraciones deben:", "o": ["Respetar los derechos lingüísticos y poder hacerse en euskera o en castellano", "Hacerse solo en castellano", "Hacerse solo en euskera", "Hacerse en la lengua del funcionario"], "e": "La ciudadanía tiene derecho a relacionarse en la lengua oficial que elija (Ley 10/1982, art. 5).", "r": "Ley 10/1982 art. 5"}, {"id": "gett13q16", "q": "La comunicación externa de la Administración es la que se dirige a:", "o": ["La ciudadanía y a otras Administraciones u organizaciones", "Los órganos de la misma unidad", "Los superiores jerárquicos", "El personal de la propia Administración"], "e": "La interna se produce dentro de la organización (descendente, ascendente y horizontal).", "r": "Comunicación en la organización"}, {"id": "gett13q17", "q": "¿Cuál de estas es una barrera de la comunicación?", "o": ["Usar tecnicismos que el receptor no entiende", "Comprobar que el mensaje se ha entendido", "Adaptar el mensaje al receptor", "Escuchar activamente"], "e": "Otras barreras: ruido, prejuicios, falta de atención o un canal inadecuado.", "r": "Barreras de la comunicación"}]}, {"id": "t14", "sig": "Tema 14", "titulo": "Tema 14. Comunicación oral: atención presencial y telefónica. Comunicación no verbal", "sub": "Segunda prueba (temario IVAP).", "preguntas": [{"id": "gett14q01", "q": "La escucha activa consiste en:", "o": ["Prestar atención plena al interlocutor y demostrarle que se le comprende, con gestos, preguntas y resúmenes", "Esperar en silencio a que termine para responder", "Interrumpir para ahorrar tiempo", "Escuchar mientras se hacen otras tareas"], "e": "Incluye mirar a la persona, no interrumpir, parafrasear y hacer preguntas aclaratorias.", "r": "Comunicación oral"}, {"id": "gett14q02", "q": "Repetir con otras palabras lo que ha dicho la persona para comprobar que se ha entendido se llama:", "o": ["Parafrasear", "Empatizar", "Asertividad", "Feedback negativo"], "e": "Es una técnica de la escucha activa.", "r": "Comunicación oral"}, {"id": "gett14q03", "q": "La empatía en la atención al público es:", "o": ["La capacidad de ponerse en el lugar de la otra persona y comprender su situación", "La capacidad de imponer el propio criterio", "La simpatía personal hacia la persona usuaria", "Dar siempre la razón a la persona usuaria"], "e": "No significa estar de acuerdo, sino comprender.", "r": "Habilidades sociales"}, {"id": "gett14q04", "q": "La asertividad es la capacidad de:", "o": ["Expresar las propias opiniones y defender los propios derechos con respeto hacia los demás", "Ceder siempre ante las peticiones", "Imponer las propias ideas", "Evitar cualquier conflicto callando"], "e": "Está entre la conducta pasiva y la agresiva.", "r": "Habilidades sociales"}, {"id": "gett14q05", "q": "Al atender una llamada telefónica en un servicio público, lo correcto es:", "o": ["Saludar, identificar el servicio y, en su caso, el nombre de quien atiende, y ofrecer ayuda", "Contestar con un simple «¿sí?»", "Esperar a que la persona se identifique primero", "Pasar la llamada sin preguntar"], "e": "En Euskadi, el saludo suele hacerse en las dos lenguas oficiales.", "r": "Atención telefónica"}, {"id": "gett14q06", "q": "En la comunicación telefónica, al no existir comunicación visual, cobra especial importancia:", "o": ["El tono, el ritmo y la claridad de la voz", "La postura corporal", "El aspecto físico", "La distancia con el interlocutor"], "e": "La sonrisa también se percibe en la voz.", "r": "Atención telefónica"}, {"id": "gett14q07", "q": "Si hay que dejar a una persona en espera al teléfono, lo correcto es:", "o": ["Pedirle permiso, explicar el motivo y no dejarla esperando mucho tiempo sin volver a atenderla", "Dejar el teléfono sin avisar", "Colgar y llamarla más tarde sin decirle nada", "Mantenerla en espera el tiempo que haga falta"], "e": "Si la espera se alarga, se ofrece devolver la llamada.", "r": "Atención telefónica"}, {"id": "gett14q08", "q": "Al transferir una llamada a otro compañero, se debe:", "o": ["Informar a la persona de la transferencia y pasar al compañero los datos de la consulta para no repetirla", "Transferir sin avisar", "Pedir a la persona que llame a otro número", "Colgar si el compañero no contesta"], "e": "Así se evita que la persona tenga que explicar todo otra vez.", "r": "Atención telefónica"}, {"id": "gett14q09", "q": "Tomar un recado telefónico correctamente implica anotar:", "o": ["Quién llama, para quién es, fecha y hora, el motivo y cómo contactar con quien llama", "Solo el nombre de quien llama", "Solo el número de teléfono", "Lo que se recuerde después de colgar"], "e": "El recado debe ser claro y llegar cuanto antes a su destinatario.", "r": "Atención telefónica"}, {"id": "gett14q10", "q": "¿Qué parte de la comunicación transmite información mediante gestos, posturas y expresiones faciales?", "o": ["La comunicación no verbal (kinesia)", "La comunicación verbal escrita", "El paralenguaje", "La proxémica"], "e": "El paralenguaje son los aspectos de la voz (tono, volumen, ritmo); la proxémica, el uso del espacio y la distancia.", "r": "Comunicación no verbal"}, {"id": "gett14q11", "q": "El uso del espacio y la distancia entre las personas al comunicarse se llama:", "o": ["Proxémica", "Kinesia", "Paralenguaje", "Cronémica"], "e": "En la atención al público conviene respetar la distancia social.", "r": "Comunicación no verbal"}, {"id": "gett14q12", "q": "El volumen, el tono, la velocidad y las pausas de la voz forman parte de:", "o": ["El paralenguaje", "La kinesia", "La proxémica", "El código escrito"], "e": "Influyen en cómo se interpreta el mensaje.", "r": "Comunicación no verbal"}, {"id": "gett14q13", "q": "En la atención presencial, ¿cuál de estas actitudes transmite disponibilidad?", "o": ["Mirar a la persona, sonreír y tener una postura abierta", "Cruzar los brazos", "Seguir mirando la pantalla mientras habla", "Atender de espaldas"], "e": "La comunicación no verbal debe ser coherente con lo que se dice.", "r": "Atención presencial"}, {"id": "gett14q14", "q": "Ante una persona usuaria enfadada, lo más adecuado es:", "o": ["Mantener la calma, escucharla sin interrumpir, mostrar comprensión y buscar una solución", "Responder en el mismo tono", "Ignorarla hasta que se calme", "Darle la razón aunque no la tenga"], "e": "Hay que evitar tomarse la queja como algo personal.", "r": "Atención a personas usuarias difíciles"}, {"id": "gett14q15", "q": "Si una consulta no es competencia de quien atiende, lo correcto es:", "o": ["Orientar a la persona hacia el órgano o servicio competente", "Decirle que no se puede ayudar", "Inventar una respuesta", "Pedirle que vuelva otro día"], "e": "Es el derecho a ser orientado; la Ley 39/2015 prevé la asistencia a las personas interesadas.", "r": "Atención al público"}, {"id": "gett14q16", "q": "Las Administraciones deben atender a las personas con discapacidad garantizando:", "o": ["La accesibilidad de la información y de los servicios, con los ajustes necesarios", "Que acudan siempre acompañadas", "Que usen solo medios electrónicos", "Un horario especial obligatorio"], "e": "Por ejemplo, información en lectura fácil, intérprete de lengua de signos o accesibilidad física.", "r": "Atención al público"}, {"id": "gett14q17", "q": "En la atención presencial, la primera impresión depende sobre todo de:", "o": ["La acogida inicial: saludo, actitud y comunicación no verbal", "La rapidez con que termina la conversación", "El número de documentos que se entregan", "El mobiliario de la oficina"], "e": "Por eso se cuida el saludo y la disponibilidad desde el primer momento.", "r": "Atención presencial"}]}, {"id": "t15", "sig": "Tema 15", "titulo": "Tema 15. El expediente administrativo. Documentos, copias y certificaciones", "sub": "Segunda prueba (temario IVAP).", "preguntas": [{"id": "gett15q01", "q": "Según el art. 70 de la Ley 39/2015, el expediente administrativo es:", "o": ["El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, así como las diligencias encaminadas a ejecutarla", "El documento que contiene la resolución final", "El registro de entrada de una solicitud", "El conjunto de documentos que presenta el interesado"], "e": "Es la definición del art. 70.1.", "r": "Ley 39/2015 art. 70.1"}, {"id": "gett15q02", "q": "Los expedientes administrativos tendrán formato:", "o": ["Electrónico", "Papel, con copia electrónica opcional", "Mixto obligatoriamente", "El que elija el interesado"], "e": "Se forman agregando ordenadamente documentos, pruebas, dictámenes, informes, acuerdos, notificaciones y demás diligencias.", "r": "Ley 39/2015 art. 70.2"}, {"id": "gett15q03", "q": "¿Cuál de estos NO forma parte del expediente administrativo?", "o": ["Las notas, borradores y opiniones de carácter auxiliar o de apoyo", "Los informes preceptivos", "Las notificaciones", "Las pruebas practicadas"], "e": "Salvo que se trate de informes preceptivos o facultativos solicitados antes de la resolución.", "r": "Ley 39/2015 art. 70.4"}, {"id": "gett15q04", "q": "Cuando se remite un expediente electrónico, se hace de acuerdo con:", "o": ["El Esquema Nacional de Interoperabilidad y sus normas técnicas", "La Ley de Propiedad Intelectual", "El Reglamento de Correos", "Las instrucciones de cada funcionario"], "e": "Se envía completo, foliado, autentificado y con un índice numerado de todos sus documentos.", "r": "Ley 39/2015 art. 70.3"}, {"id": "gett15q05", "q": "Según el art. 26 de la Ley 39/2015, los documentos administrativos se emiten:", "o": ["Por escrito, a través de medios electrónicos, salvo que su naturaleza exija otra forma más adecuada", "En papel, salvo que el interesado pida otro formato", "Verbalmente, salvo que se pida por escrito", "En el formato que elija cada órgano"], "e": "Art. 26.1.", "r": "Ley 39/2015 art. 26.1"}, {"id": "gett15q06", "q": "¿Cuál de estos NO es un requisito de validez de los documentos administrativos electrónicos del art. 26.2?", "o": ["Llevar sello de Correos", "Contener información de cualquier naturaleza archivada en un soporte electrónico", "Disponer de los datos de identificación que permitan su individualización", "Incorporar las firmas electrónicas que correspondan"], "e": "También deben tener una referencia temporal y los metadatos mínimos exigidos.", "r": "Ley 39/2015 art. 26.2"}, {"id": "gett15q07", "q": "No requieren firma electrónica los documentos electrónicos:", "o": ["Emitidos por las Administraciones que se publiquen con carácter meramente informativo, y los que no formen parte de un expediente", "Que sean resoluciones", "Que sean notificaciones", "Que sean certificados"], "e": "Siempre debe quedar acreditado su origen.", "r": "Ley 39/2015 art. 26.3"}, {"id": "gett15q08", "q": "¿Quién puede expedir copias auténticas de documentos públicos administrativos o privados?", "o": ["Cada Administración, determinando los órganos que tienen atribuidas esas competencias", "Solo los notarios", "Cualquier empleado público", "Solo el Secretario del Ayuntamiento"], "e": "Las copias auténticas tienen la misma validez y eficacia que los originales.", "r": "Ley 39/2015 art. 27.1"}, {"id": "gett15q09", "q": "Las copias auténticas, según el art. 27 de la Ley 39/2015:", "o": ["Tienen la misma validez y eficacia que los documentos originales", "Tienen menos valor que el original", "Solo sirven dentro del mismo expediente", "Caducan a los seis meses"], "e": "Pueden expedirse a partir de originales o de otras copias auténticas.", "r": "Ley 39/2015 art. 27.2"}, {"id": "gett15q10", "q": "Una copia electrónica de un documento en papel, para ser auténtica, requiere:", "o": ["Una imagen electrónica del original, con la firma y los metadatos correspondientes", "Una fotocopia compulsada", "La firma manuscrita del interesado", "Una diligencia del notario"], "e": "Se considera digitalización el proceso tecnológico que convierte el papel en un fichero electrónico.", "r": "Ley 39/2015 art. 27.3"}, {"id": "gett15q11", "q": "¿En qué plazo deben expedirse las copias auténticas que pidan los interesados?", "o": ["En el plazo máximo de quince días desde la solicitud en el registro electrónico de la Administración competente", "En diez días", "En un mes", "En tres días"], "e": "Art. 27.4.", "r": "Ley 39/2015 art. 27.4"}, {"id": "gett15q12", "q": "Según el art. 28 de la Ley 39/2015, los interesados NO están obligados a aportar:", "o": ["Documentos originales, salvo que la normativa reguladora establezca lo contrario", "Ningún dato personal", "Ninguna solicitud por escrito", "Ningún documento firmado"], "e": "Tampoco documentos ya aportados a cualquier Administración ni los elaborados por cualquier Administración.", "r": "Ley 39/2015 art. 28.3"}, {"id": "gett15q13", "q": "Si la Administración necesita documentos elaborados por otras Administraciones, se presume que el interesado:", "o": ["Autoriza su consulta, salvo que conste su oposición expresa o la ley especial exija consentimiento expreso", "Debe aportarlos siempre", "Debe firmar una autorización en papel", "No puede oponerse"], "e": "Art. 28.2.", "r": "Ley 39/2015 art. 28.2"}, {"id": "gett15q14", "q": "Excepcionalmente, la Administración puede pedir al interesado el cotejo de una copia aportada:", "o": ["Cuando la relevancia del documento lo exija o existan dudas derivadas de la calidad de la copia", "En todo caso", "Nunca", "Solo en procedimientos sancionadores"], "e": "Puede solicitar de forma motivada la exhibición del documento original.", "r": "Ley 39/2015 art. 28.5"}, {"id": "gett15q15", "q": "El documento por el que el órgano competente da fe de un acto, hecho o dato que consta en un expediente o registro es:", "o": ["La certificación", "El informe", "La diligencia", "La notificación"], "e": "En las Entidades locales, la fe pública corresponde al Secretario.", "r": "Documentos administrativos"}, {"id": "gett15q16", "q": "El documento en el que se hace constar en el expediente un hecho, un trámite o un acuerdo (por ejemplo, la entrega de un documento) es:", "o": ["La diligencia", "El acta", "El oficio", "El informe"], "e": "Suele ser un texto breve, fechado y firmado por el funcionario que la extiende.", "r": "Documentos administrativos"}, {"id": "gett15q17", "q": "Las certificaciones de los acuerdos de los órganos colegiados las expide:", "o": ["El Secretario, con el visto bueno del Presidente", "El Presidente en solitario", "Cualquier miembro del órgano", "El interesado"], "e": "Pueden expedirse antes de aprobar el acta, haciendo constar esa circunstancia.", "r": "Ley 40/2015 arts. 16 y 19"}, {"id": "gett15q18", "q": "El documento en el que un órgano emite su opinión técnica o jurídica sobre un asunto, para que el órgano competente resuelva, es:", "o": ["El informe", "La resolución", "La certificación", "El oficio"], "e": "Salvo disposición en contrario, los informes son facultativos y no vinculantes.", "r": "Ley 39/2015 art. 80"}, {"id": "gett15q19", "q": "Cada Administración debe mantener un archivo electrónico único de los documentos de:", "o": ["Los procedimientos finalizados", "Todos los procedimientos en curso", "Solo los procedimientos sancionadores", "Solo los expedientes de personal"], "e": "Art. 17.1 de la Ley 39/2015.", "r": "Ley 39/2015 art. 17.1"}]}, {"id": "t16", "sig": "Tema 16", "titulo": "Tema 16. Archivos de oficina, documentación electrónica y archivo de la Administración vasca", "sub": "Segunda prueba (temario IVAP).", "preguntas": [{"id": "gett16q01", "q": "El archivo de oficina o de gestión es aquel que conserva:", "o": ["La documentación en tramitación o de consulta frecuente por la propia unidad", "La documentación con valor histórico permanente", "La documentación de todas las Administraciones", "Solo los documentos en papel"], "e": "Según el ciclo vital, los documentos pasan del archivo de oficina al central, al intermedio y al histórico.", "r": "Ciclo vital de los documentos"}, {"id": "gett16q02", "q": "¿Cuál es el orden habitual de los archivos según el ciclo vital de los documentos?", "o": ["Archivo de oficina, archivo central, archivo intermedio y archivo histórico", "Archivo histórico, central, intermedio y de oficina", "Archivo central, de oficina, histórico e intermedio", "Archivo intermedio, de oficina, central e histórico"], "e": "Cada fase corresponde a una edad del documento: activa, semiactiva e inactiva.", "r": "Ciclo vital de los documentos"}, {"id": "gett16q03", "q": "El envío organizado de documentación de un archivo a otro siguiendo el ciclo vital se llama:", "o": ["Transferencia", "Expurgo", "Préstamo", "Digitalización"], "e": "Se acompaña de una relación de entrega o relación de transferencia.", "r": "Gestión de archivos"}, {"id": "gett16q04", "q": "La operación de seleccionar y eliminar los documentos que no tienen valor para su conservación se llama:", "o": ["Expurgo (eliminación) tras la valoración documental", "Transferencia", "Clasificación", "Ordenación"], "e": "La eliminación de documentos públicos solo puede hacerse siguiendo el procedimiento y los calendarios aprobados.", "r": "Gestión de archivos"}, {"id": "gett16q05", "q": "Agrupar los documentos según las funciones y actividades de la organización, mediante un cuadro, se llama:", "o": ["Clasificación", "Ordenación", "Instalación", "Descripción"], "e": "La ordenación dispone los documentos dentro de cada serie (por fecha, alfabética, numérica).", "r": "Tratamiento archivístico"}, {"id": "gett16q06", "q": "¿Cuál de estos es un sistema de ordenación de documentos?", "o": ["Cronológico", "Por calendario de conservación", "Por transferencia", "Por valoración"], "e": "Otros: alfabético (onomástico, geográfico, por materias), numérico y alfanumérico.", "r": "Ordenación"}, {"id": "gett16q07", "q": "En la ordenación alfabética de apellidos, las partículas como «de», «del» o «la»:", "o": ["Normalmente no se tienen en cuenta y se colocan al final", "Se colocan siempre al principio", "Determinan el orden", "Se eliminan del nombre"], "e": "Por ejemplo, «Torre, Ana de la».", "r": "Ordenación alfabética"}, {"id": "gett16q08", "q": "El conjunto de documentos producidos por un mismo órgano en el desarrollo de una misma actividad o función se llama:", "o": ["Serie documental", "Fondo", "Sección", "Unidad documental simple"], "e": "El fondo es el conjunto de documentos de un mismo productor.", "r": "Conceptos archivísticos"}, {"id": "gett16q09", "q": "¿Qué norma establece que cada Administración mantendrá un archivo electrónico único de los procedimientos finalizados?", "o": ["La Ley 39/2015 (art. 17)", "La Ley 40/2015 (art. 3)", "La Ley 19/2013", "El Código Civil"], "e": "Los documentos deben conservarse en un formato que garantice su autenticidad, integridad y conservación.", "r": "Ley 39/2015 art. 17"}, {"id": "gett16q10", "q": "Según el art. 17.3 de la Ley 39/2015, los medios o soportes de los documentos electrónicos deben contar con medidas de seguridad conforme a:", "o": ["El Esquema Nacional de Seguridad", "El Esquema Nacional de Interoperabilidad únicamente", "La Ley de Propiedad Intelectual", "La normativa de Correos"], "e": "Deben garantizar la integridad, autenticidad, confidencialidad, calidad, protección y conservación, y el cumplimiento de la protección de datos.", "r": "Ley 39/2015 art. 17.3"}, {"id": "gett16q11", "q": "Los metadatos de un documento electrónico son:", "o": ["Datos asociados al documento que describen su contexto, contenido y estructura", "El contenido del documento", "La firma del documento", "Copias de seguridad"], "e": "Por ejemplo: órgano, fecha de captura, origen, estado de elaboración y tipo documental.", "r": "Documento electrónico"}, {"id": "gett16q12", "q": "El formato de archivo recomendado para conservar documentos electrónicos a largo plazo es:", "o": ["PDF/A", "DOCX", "JPG con compresión", "TXT sin metadatos"], "e": "Es una norma ISO pensada para la conservación a largo plazo.", "r": "Documento electrónico"}, {"id": "gett16q13", "q": "El documento que enumera las series documentales y fija sus plazos de conservación, transferencia o eliminación se llama:", "o": ["Calendario de conservación", "Cuadro de clasificación", "Registro de entrada", "Inventario de bienes"], "e": "Lo aprueba el órgano competente en materia de valoración documental.", "r": "Gestión de archivos"}, {"id": "gett16q14", "q": "El acceso de la ciudadanía a los archivos y registros administrativos está reconocido en:", "o": ["El art. 105.b de la Constitución", "El art. 103 de la Constitución", "El art. 149 de la Constitución", "El art. 9.3 de la Constitución"], "e": "Salvo en lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas.", "r": "CE art. 105.b"}, {"id": "gett16q15", "q": "En la Administración vasca, el sistema que organiza la gestión de los documentos y archivos de la Administración General de la Comunidad Autónoma se denomina:", "o": ["Sistema de Archivo de la Administración Pública de la Comunidad Autónoma de Euskadi", "Archivo Histórico Nacional", "Registro Electrónico General", "Euskadi.eus"], "e": "Es el sistema citado en el temario del IVAP para este tema.", "r": "Archivo de la Administración vasca"}, {"id": "gett16q16", "q": "La unidad documental compuesta, formada por varios documentos relacionados con un mismo asunto, es:", "o": ["El expediente", "El documento simple", "La serie", "El fondo"], "e": "El documento simple es una unidad documental aislada.", "r": "Conceptos archivísticos"}, {"id": "gett16q17", "q": "Prestar un documento de archivo a una unidad administrativa exige normalmente:", "o": ["Registrar el préstamo y controlar su devolución", "Entregarlo sin control", "Hacer siempre una copia auténtica", "La autorización del Pleno"], "e": "Así se garantiza que el documento vuelve a su sitio.", "r": "Gestión de archivos"}]}, {"id": "t17", "sig": "Tema 17", "titulo": "Tema 17. Correspondencia y paquetería", "sub": "Segunda prueba (temario IVAP).", "preguntas": [{"id": "gett17q01", "q": "¿Qué entidad presta en España el servicio postal universal?", "o": ["La Sociedad Estatal Correos y Telégrafos", "Cualquier empresa de mensajería", "El Ministerio de Transportes directamente", "Las Diputaciones Forales"], "e": "Lo establece la Ley 43/2010, del servicio postal universal.", "r": "Ley 43/2010"}, {"id": "gett17q02", "q": "Un envío certificado se caracteriza por:", "o": ["Dejar constancia de su admisión y de su entrega, con un número de seguimiento, y garantía frente a pérdida o deterioro", "No dejar ningún registro", "Entregarse siempre en mano al día siguiente", "Ser gratuito para las Administraciones"], "e": "Se entrega con firma del destinatario o de quien lo recoja.", "r": "Correspondencia"}, {"id": "gett17q03", "q": "El aviso o acuse de recibo es:", "o": ["El documento que firma el destinatario al recibir el envío y que se devuelve al remitente como prueba de la entrega", "El resguardo que se da al remitente al admitir el envío", "La etiqueta con el código de seguimiento", "La factura del envío"], "e": "Es un servicio adicional del certificado, muy usado en las notificaciones administrativas en papel.", "r": "Correspondencia"}, {"id": "gett17q04", "q": "El reembolso, en los servicios postales, consiste en:", "o": ["Que el destinatario pague una cantidad al recibir el envío, que se entrega después al remitente", "Que el remitente recupere el dinero si el envío se pierde", "Que el envío se devuelva al remitente sin abrir", "Una tarifa reducida para Administraciones"], "e": "Es habitual en ventas a distancia.", "r": "Paquetería"}, {"id": "gett17q05", "q": "El giro postal sirve para:", "o": ["Enviar dinero a través de Correos", "Enviar paquetes urgentes", "Certificar el contenido de un escrito", "Devolver un envío al remitente"], "e": "Puede ser nacional o internacional.", "r": "Servicios postales"}, {"id": "gett17q06", "q": "El telegrama es un servicio de:", "o": ["Transmisión rápida de un texto, que puede hacerse con acuse de recibo y certificación de contenido", "Envío de paquetes", "Envío de dinero", "Mensajería instantánea por internet"], "e": "Hoy se usa poco, salvo para comunicaciones con valor de prueba.", "r": "Servicios postales"}, {"id": "gett17q07", "q": "El burofax con certificación de contenido y acuse de recibo es útil porque:", "o": ["Acredita el contenido de lo enviado, la fecha y la entrega", "Es el envío más barato", "No necesita firma del destinatario", "Se entrega siempre en el mismo día"], "e": "Por eso se usa para comunicaciones con valor probatorio.", "r": "Servicios postales"}, {"id": "gett17q08", "q": "Según la Ley 39/2015, ¿en qué oficinas pueden presentarse documentos dirigidos a una Administración, además del registro electrónico?", "o": ["En las oficinas de Correos, en la forma que se establezca reglamentariamente", "En cualquier comercio autorizado", "En las oficinas bancarias", "Solo en el ayuntamiento del domicilio"], "e": "También en representaciones diplomáticas y oficinas consulares de España en el extranjero y en las oficinas de asistencia en materia de registros.", "r": "Ley 39/2015 art. 16.4"}, {"id": "gett17q09", "q": "La presentación de un escrito en Correos mediante el «correo administrativo» exige:", "o": ["Presentarlo en sobre abierto para que se feche y selle la primera hoja antes de certificarlo", "Presentarlo en sobre cerrado", "Enviarlo por correo ordinario", "Presentarlo solo en días hábiles por la tarde"], "e": "Así consta la fecha de presentación a efectos del plazo.", "r": "Correo administrativo"}, {"id": "gett17q10", "q": "En la gestión de la correspondencia de entrada de una oficina, el primer paso es:", "o": ["Recibir, comprobar y registrar los documentos", "Archivar directamente los documentos", "Responder a todos los escritos", "Destruir los sobres sin mirar el remite"], "e": "Después se distribuyen a la unidad competente.", "r": "Correspondencia de entrada"}, {"id": "gett17q11", "q": "En la correspondencia de salida, antes del envío hay que:", "o": ["Registrar la salida, comprobar la dirección y los anexos y elegir la modalidad de envío adecuada", "Enviar sin registrar", "Usar siempre envío ordinario", "Esperar a acumular varios envíos durante un mes"], "e": "Si el envío debe acreditar la entrega, se usa certificado con acuse de recibo.", "r": "Correspondencia de salida"}, {"id": "gett17q12", "q": "Las notificaciones administrativas en papel se practican por:", "o": ["Cualquier medio que permita dejar constancia de su recepción, la fecha, la identidad y el contenido", "Correo ordinario sin acuse de recibo", "Llamada telefónica", "Publicación en redes sociales"], "e": "Art. 41.1 de la Ley 39/2015. Por eso se usa el certificado con acuse de recibo.", "r": "Ley 39/2015 art. 41.1"}, {"id": "gett17q13", "q": "Si al intentar una notificación en papel en el domicilio no hay nadie, según el art. 42.2 de la Ley 39/2015:", "o": ["Se hace constar en el expediente y se repite una sola vez en hora distinta dentro de los tres días siguientes", "Se da por notificada", "Se publica directamente en el BOE", "Se archiva el expediente"], "e": "Si en la primera hora fue antes de las 15:00, el segundo intento será después de las 15:00, y viceversa, con al menos tres horas de diferencia.", "r": "Ley 39/2015 art. 42.2"}, {"id": "gett17q14", "q": "El servicio de paquetería que garantiza la entrega en un plazo muy corto, normalmente al día siguiente, se llama:", "o": ["Servicio urgente o exprés", "Servicio ordinario", "Correo administrativo", "Apartado postal"], "e": "Las empresas de mensajería ofrecen servicios similares.", "r": "Paquetería"}, {"id": "gett17q15", "q": "El apartado de correos es:", "o": ["Un casillero en una oficina de Correos donde se recibe la correspondencia", "Un tipo de envío urgente", "El registro de envíos de una oficina", "Un servicio de envío de dinero"], "e": "Es útil cuando no se quiere recibir la correspondencia en el domicilio.", "r": "Servicios postales"}, {"id": "gett17q16", "q": "Para clasificar la correspondencia por destino, en España se usa:", "o": ["El código postal, de cinco cifras", "El NIF del destinatario", "El número de teléfono", "El código de la provincia de dos letras"], "e": "Las dos primeras cifras indican la provincia (48 corresponde a Bizkaia).", "r": "Correspondencia"}]}, {"id": "t18", "sig": "Tema 18", "titulo": "Tema 18. Competencia digital 1.1: navegar, buscar y filtrar información", "sub": "Segunda prueba (temario IVAP).", "preguntas": [{"id": "gett18q01", "q": "La competencia digital 1.1 del marco europeo DigComp se refiere a:", "o": ["Navegar, buscar y filtrar datos, información y contenidos digitales", "Evaluar datos, información y contenidos digitales", "Gestionar datos e información", "Comunicarse mediante tecnologías digitales"], "e": "Pertenece al área 1, alfabetización en información y datos. La 1.2 es evaluar y la 1.3, gestionar.", "r": "DigComp 1.1"}, {"id": "gett18q02", "q": "¿Cuántas áreas de competencia tiene el marco DigComp?", "o": ["Cinco", "Tres", "Siete", "Diez"], "e": "Información y datos; comunicación y colaboración; creación de contenidos; seguridad; y resolución de problemas.", "r": "DigComp"}, {"id": "gett18q03", "q": "Un navegador web es:", "o": ["Un programa que permite acceder y visualizar páginas web", "Un motor de búsqueda", "Un proveedor de acceso a internet", "Un antivirus"], "e": "Ejemplos: Chrome, Firefox, Edge o Safari. Google o Bing son motores de búsqueda.", "r": "Navegación"}, {"id": "gett18q04", "q": "La dirección única de una página web que se escribe en la barra de direcciones se llama:", "o": ["URL", "IP", "DNS", "HTML"], "e": "Por ejemplo, https://www.getxo.eus.", "r": "Navegación"}, {"id": "gett18q05", "q": "Que una dirección web empiece por «https» indica que:", "o": ["La comunicación entre el navegador y el sitio está cifrada", "La página es oficial de una Administración", "La página no tiene publicidad", "La página está libre de virus"], "e": "El candado de la barra de direcciones indica la conexión segura, pero no garantiza que el sitio sea fiable.", "r": "Navegación segura"}, {"id": "gett18q06", "q": "Guardar una página web para volver a ella fácilmente se hace con:", "o": ["Los marcadores o favoritos", "El historial", "Las cookies", "La caché"], "e": "El historial registra automáticamente las páginas visitadas.", "r": "Navegación"}, {"id": "gett18q07", "q": "La navegación privada o de incógnito:", "o": ["No guarda el historial, las cookies ni los datos de formularios en el equipo al cerrar la ventana", "Hace que nadie pueda saber qué páginas se visitan", "Oculta la dirección IP a todos los sitios", "Protege frente a cualquier virus"], "e": "La empresa, el proveedor de internet o los sitios visitados pueden seguir viendo la actividad.", "r": "Navegación privada"}, {"id": "gett18q08", "q": "Las cookies son:", "o": ["Pequeños archivos que los sitios web guardan en el navegador para recordar información del usuario", "Virus que se instalan al navegar", "Copias de seguridad de las páginas", "Programas para bloquear anuncios"], "e": "Los sitios deben pedir consentimiento para las cookies no necesarias.", "r": "Navegación"}, {"id": "gett18q09", "q": "Para buscar una frase exacta en la mayoría de buscadores se usan:", "o": ["Las comillas", "Los paréntesis", "El signo de interrogación", "Los corchetes"], "e": "Por ejemplo, \"Reglamento de uso de instalaciones\".", "r": "Búsqueda"}, {"id": "gett18q10", "q": "En un buscador, el signo menos (-) delante de una palabra sirve para:", "o": ["Excluir los resultados que contienen esa palabra", "Buscar solo esa palabra", "Buscar sinónimos", "Ordenar por fecha"], "e": "Por ejemplo: piscina -Bilbao.", "r": "Búsqueda"}, {"id": "gett18q11", "q": "El operador «site:» en un buscador permite:", "o": ["Limitar la búsqueda a un sitio web o dominio concreto", "Buscar solo imágenes", "Buscar documentos PDF", "Traducir la página"], "e": "Por ejemplo: igualdad site:euskadi.eus.", "r": "Búsqueda"}, {"id": "gett18q12", "q": "Para buscar solo documentos de un tipo concreto, como PDF, se usa el operador:", "o": ["filetype:", "site:", "intitle:", "related:"], "e": "Por ejemplo: presupuestos filetype:pdf.", "r": "Búsqueda"}, {"id": "gett18q13", "q": "Filtrar la información en un buscador consiste en:", "o": ["Usar opciones como fecha, idioma, tipo de resultado o región para acotar los resultados", "Borrar el historial", "Instalar un antivirus", "Descargar todos los resultados"], "e": "Las herramientas de búsqueda avanzada permiten aplicar varios filtros a la vez.", "r": "Filtrado"}, {"id": "gett18q14", "q": "Un criterio para valorar la fiabilidad de una página web es:", "o": ["Comprobar quién es el autor o la entidad responsable y la fecha de actualización", "Que tenga muchas imágenes", "Que aparezca la primera en el buscador", "Que tenga muchos anuncios"], "e": "También contrastar la información con otras fuentes y comprobar si cita sus fuentes.", "r": "Evaluación de la información"}, {"id": "gett18q15", "q": "Un enlace que al pulsarlo lleva a otra página o documento se llama:", "o": ["Hipervínculo", "Marcador", "Cookie", "Pestaña"], "e": "Las pestañas permiten tener varias páginas abiertas en la misma ventana del navegador.", "r": "Navegación"}, {"id": "gett18q16", "q": "Las alertas o suscripciones a fuentes de noticias (por ejemplo, RSS) sirven para:", "o": ["Recibir automáticamente las novedades de las fuentes que interesan", "Bloquear la publicidad", "Navegar sin conexión", "Borrar las cookies"], "e": "Es una forma de mantenerse informado sin buscar cada vez.", "r": "Gestión de búsquedas"}, {"id": "gett18q17", "q": "El atajo de teclado habitual para buscar una palabra dentro de una página web es:", "o": ["Ctrl + F", "Ctrl + P", "Ctrl + S", "Ctrl + Z"], "e": "Ctrl + P imprime; Ctrl + S guarda; Ctrl + Z deshace.", "r": "Navegación"}, {"id": "gett18q18", "q": "La caché del navegador sirve para:", "o": ["Guardar temporalmente partes de las páginas visitadas para cargarlas más rápido", "Guardar las contraseñas", "Bloquear las ventanas emergentes", "Registrar las descargas"], "e": "Borrar la caché puede ayudar cuando una página no se muestra actualizada.", "r": "Navegación"}]}, {"id": "t19", "sig": "Tema 19", "titulo": "Tema 19. Derechos de la ciudadanía y acceso a archivos y registros", "sub": "Segunda prueba.", "preguntas": [{"id": "gett19q01", "q": "¿Qué artículo de la Ley 39/2015 recoge los derechos de las personas en sus relaciones con las Administraciones Públicas?", "o": ["El art. 13", "El art. 53", "El art. 21", "El art. 3"], "e": "El art. 53 recoge los derechos del interesado en el procedimiento administrativo.", "r": "Ley 39/2015 art. 13"}, {"id": "gett19q02", "q": "Según el art. 13, quienes tienen capacidad de obrar ante las Administraciones tienen derecho a comunicarse con ellas a través de:", "o": ["Un Punto de Acceso General electrónico de la Administración", "Solo el registro presencial", "Las redes sociales del organismo", "El teléfono exclusivamente"], "e": "Es el primer derecho del art. 13.", "r": "Ley 39/2015 art. 13.a"}, {"id": "gett19q03", "q": "¿Cuál de estos NO es un derecho del art. 13 de la Ley 39/2015?", "o": ["A que la Administración resuelva siempre a su favor", "A ser asistidas en el uso de medios electrónicos", "A utilizar las lenguas oficiales en el territorio de su Comunidad Autónoma", "A ser tratadas con respeto y deferencia por las autoridades y empleados públicos"], "e": "También: acceso a la información pública, archivos y registros; exigir responsabilidades; obtener y usar medios de identificación y firma electrónica; y protección de datos.", "r": "Ley 39/2015 art. 13"}, {"id": "gett19q04", "q": "El derecho de acceso a la información pública, archivos y registros se ejerce, según el art. 13.d de la Ley 39/2015, de acuerdo con:", "o": ["La Ley 19/2013, de transparencia, acceso a la información pública y buen gobierno, y el resto del ordenamiento", "Solo la Ley 39/2015", "El Código Civil", "La Ley de Propiedad Intelectual"], "e": "El art. 105.b de la Constitución remite a la ley la regulación del acceso a los archivos y registros administrativos.", "r": "Ley 39/2015 art. 13.d"}, {"id": "gett19q05", "q": "¿Cuál de estos derechos es del interesado en un procedimiento (art. 53) y no del art. 13?", "o": ["Conocer en cualquier momento el estado de la tramitación de los procedimientos en que sea interesado", "Ser tratado con respeto y deferencia", "Utilizar las lenguas oficiales", "Ser asistido en el uso de medios electrónicos"], "e": "También: identificar a las autoridades y al personal responsable, no presentar documentos ya aportados, formular alegaciones y obtener información y orientación.", "r": "Ley 39/2015 art. 53"}, {"id": "gett19q06", "q": "El interesado tiene derecho a identificar:", "o": ["A las autoridades y al personal al servicio de las Administraciones bajo cuya responsabilidad se tramiten los procedimientos", "A todos los demás interesados en el procedimiento", "Al autor de una denuncia anónima", "A los miembros del tribunal de oposiciones antes de su nombramiento"], "e": "Art. 53.1.b.", "r": "Ley 39/2015 art. 53.1.b"}, {"id": "gett19q07", "q": "Quienes se relacionan con la Administración por medios electrónicos tienen derecho a consultar la información del estado de tramitación en:", "o": ["El Punto de Acceso General electrónico de la Administración, que funciona como portal de acceso", "Solo en la oficina presencial", "En el BOE", "En el boletín provincial"], "e": "Art. 53.1.a.", "r": "Ley 39/2015 art. 53.1.a"}, {"id": "gett19q08", "q": "Según la Constitución, el acceso de los ciudadanos a los archivos y registros administrativos tiene como límites:", "o": ["La seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas", "La voluntad del funcionario que custodia el archivo", "El interés económico de la Administración", "La antigüedad de los documentos"], "e": "Art. 105.b de la Constitución.", "r": "CE art. 105.b"}, {"id": "gett19q09", "q": "Para ejercer el derecho de acceso a la información pública de la Ley 19/2013:", "o": ["No es necesario motivar la solicitud", "Hay que acreditar ser interesado en el procedimiento", "Hay que pagar una tasa siempre", "Hay que ser mayor de edad y vecino del municipio"], "e": "El solicitante puede exponer sus motivos, pero la falta de motivación no es causa de rechazo.", "r": "Ley 19/2013 art. 17.3"}, {"id": "gett19q10", "q": "Las personas físicas que no estén obligadas a relacionarse electrónicamente con la Administración:", "o": ["Pueden elegir en todo momento si se comunican por medios electrónicos o no", "Deben hacerlo siempre en papel", "Deben hacerlo siempre electrónicamente", "Solo pueden cambiar de medio una vez"], "e": "Art. 14.1 de la Ley 39/2015.", "r": "Ley 39/2015 art. 14.1"}, {"id": "gett19q11", "q": "¿Qué derecho reconoce el art. 12 de la Ley 39/2015 a los interesados?", "o": ["A ser asistidos en el uso de medios electrónicos, especialmente en la identificación y firma electrónica y en la presentación de solicitudes", "A no relacionarse nunca electrónicamente", "A elegir el funcionario que les atiende", "A obtener gratis cualquier copia"], "e": "Si no disponen de medios, un funcionario habilitado puede identificarles y firmar por ellos, con su consentimiento expreso.", "r": "Ley 39/2015 art. 12"}, {"id": "gett19q12", "q": "Según el art. 28 de la Ley 39/2015, los interesados tienen derecho a no aportar documentos:", "o": ["Que ya se encuentren en poder de la Administración actuante o hayan sido elaborados por cualquier otra Administración", "De ningún tipo", "Si son personas jurídicas", "Si el procedimiento es de oficio"], "e": "La Administración debe consultarlos u obtenerlos por sus redes corporativas, salvo oposición del interesado.", "r": "Ley 39/2015 art. 28.2"}, {"id": "gett19q13", "q": "Las quejas sobre el funcionamiento de los servicios públicos en Euskadi pueden presentarse ante:", "o": ["El Ararteko, además de ante la propia Administración", "El Tribunal Constitucional", "El Consejo de Estado", "La Junta Electoral"], "e": "El Ararteko es la institución vasca equivalente al Defensor del Pueblo (art. 15 del Estatuto).", "r": "EAPV art. 15"}, {"id": "gett19q14", "q": "Según el art. 13.e de la Ley 39/2015, las personas tienen derecho a:", "o": ["Exigir las responsabilidades de las Administraciones Públicas y autoridades, cuando así corresponda legalmente", "Sancionar al personal que les atiende", "Elegir el procedimiento aplicable", "Fijar el plazo para resolver"], "e": "La responsabilidad patrimonial de las Administraciones se regula en la Ley 40/2015.", "r": "Ley 39/2015 art. 13.e"}, {"id": "gett19q15", "q": "¿Qué derecho tienen las personas respecto a sus datos personales según el art. 13.h de la Ley 39/2015?", "o": ["A la protección de sus datos personales y, en particular, a su seguridad y confidencialidad en ficheros, sistemas y aplicaciones de las Administraciones", "A que la Administración no trate ningún dato suyo", "A cobrar por el uso de sus datos", "A que sus datos se publiquen"], "e": "Se aplica la normativa de protección de datos (RGPD y LO 3/2018).", "r": "Ley 39/2015 art. 13.h"}, {"id": "gett19q16", "q": "El derecho a obtener una copia sellada de los documentos que se presenten se recoge, para el interesado, en:", "o": ["El art. 53.1.a de la Ley 39/2015", "El art. 14 de la Ley 40/2015", "El art. 105 de la Constitución", "El art. 3 de la Ley 19/2013"], "e": "Junto con el derecho a obtener copia de los documentos del procedimiento.", "r": "Ley 39/2015 art. 53.1.a"}]}, {"id": "t20", "sig": "Tema 20", "titulo": "Tema 20. Reglamento de uso de las instalaciones de Getxo Kirolak", "sub": "Segunda prueba.", "preguntas": [{"id": "gett20q01", "q": "¿Qué órgano aprobó definitivamente el Reglamento de uso de las instalaciones de Getxo Kirolak y cuándo?", "o": ["El Consejo Rector de Getxo Kirolak, en sesión del 19 de mayo de 2010", "El Pleno del Ayuntamiento de Getxo, el 31 de mayo de 2010", "La Presidencia de Getxo Kirolak, el 17 de febrero de 2010", "La Junta de Gobierno Local, el 9 de abril de 2010"], "e": "La aprobación inicial fue el 17 de febrero de 2010 y el anuncio de información pública se publicó en el BOB el 9 de abril de 2010.", "r": "Reglamento GK, preámbulo"}, {"id": "gett20q02", "q": "¿Durante cuánto tiempo se sometió el reglamento a información pública y audiencia de los interesados?", "o": ["30 días hábiles, conforme al art. 49 de la Ley 7/1985", "20 días naturales", "15 días hábiles", "Dos meses"], "e": "Es el plazo mínimo de la LBRL para las ordenanzas y reglamentos locales.", "r": "Reglamento GK, preámbulo"}, {"id": "gett20q03", "q": "Según el art. 3, Getxo Kirolak se estructura como:", "o": ["Organismo Autónomo Local de carácter administrativo, con personalidad jurídica pública", "Sociedad mercantil municipal", "Servicio municipal sin personalidad jurídica", "Fundación pública"], "e": "Tiene plena capacidad para administrar, adquirir derechos, contratar y asumir obligaciones.", "r": "Reglamento GK art. 3"}, {"id": "gett20q04", "q": "¿De quién son titulares las instalaciones deportivas que regula el reglamento?", "o": ["Del Ayuntamiento de Getxo", "De Getxo Kirolak", "De la Diputación Foral de Bizkaia", "Del Gobierno Vasco"], "e": "El Ayuntamiento encomienda su gestión y administración a Getxo Kirolak (arts. 1 y 2).", "r": "Reglamento GK arts. 1 y 2"}, {"id": "gett20q05", "q": "Según el art. 5.2, el uso de las instalaciones queda supeditado a que la persona que lo demande:", "o": ["Esté al corriente del pago de las tasas y no esté sancionada por la mala utilización de los espacios", "Esté empadronada en Getxo", "Sea mayor de edad", "Pertenezca a un club deportivo"], "e": "Son de acceso libre para todas las personas, con las limitaciones de la ley y del reglamento (art. 6.2).", "r": "Reglamento GK art. 5.2"}, {"id": "gett20q06", "q": "¿Quién aprueba los programas de actividades para la distribución temporal de las instalaciones?", "o": ["La presidencia de Getxo Kirolak, que da cuenta al Consejo Rector", "El Consejo Rector", "El Pleno municipal", "La dirección deportiva"], "e": "Se busca un equilibrio entre las personas y colectivos que lo demanden.", "r": "Reglamento GK art. 5.3"}, {"id": "gett20q07", "q": "¿Hasta qué edad deben estar los niños y niñas acompañados en todo momento por una persona adulta dentro de las instalaciones?", "o": ["Hasta 10 años", "Hasta 8 años", "Hasta 12 años", "Hasta 14 años"], "e": "Art. 6.4.", "r": "Reglamento GK art. 6.4"}, {"id": "gett20q08", "q": "Una persona abonada con una sanción pendiente:", "o": ["No puede acceder a las instalaciones hasta que la abone", "Puede acceder pero no reservar", "Puede acceder sin limitaciones", "Pierde para siempre la condición de abonada"], "e": "Y quien tenga una cuota de curso pendiente no puede inscribirse en otra actividad hasta pagarla (art. 6.2).", "r": "Reglamento GK art. 6.3"}, {"id": "gett20q09", "q": "¿Cuándo se paga el precio público o la tasa por el uso de las instalaciones?", "o": ["Siempre con carácter previo a la utilización", "Al terminar el uso", "A final de mes", "Al final del año natural"], "e": "Art. 7.1.", "r": "Reglamento GK art. 7.1"}, {"id": "gett20q10", "q": "La tasa de cuota de abonado se factura:", "o": ["Con periodicidad anual, por año natural, y puede domiciliarse en el primer cuatrimestre", "Mensualmente", "Trimestralmente", "Por temporada deportiva de septiembre a junio"], "e": "Art. 7.2.", "r": "Reglamento GK art. 7.2"}, {"id": "gett20q11", "q": "Si una persona se da de alta como abonada durante el segundo cuatrimestre del año:", "o": ["Se le aplica un descuento del 20 % sobre la cuota anual", "Paga la cuota anual completa", "Se le descuenta el 60 %", "Se le descuenta el 50 %"], "e": "Primer cuatrimestre: cuota completa; segundo: 20 % de descuento; tercero: 60 % de descuento.", "r": "Reglamento GK art. 7.3"}, {"id": "gett20q12", "q": "El impago de una cuota:", "o": ["Suspende la condición de persona abonada", "Supone una sanción grave", "No tiene consecuencias", "Supone la baja definitiva sin posibilidad de volver"], "e": "Art. 7.4.", "r": "Reglamento GK art. 7.4"}, {"id": "gett20q13", "q": "¿Cómo considera el reglamento a las personas acompañantes y espectadoras?", "o": ["Personas usuarias pasivas", "Personas usuarias ocasionales", "Personas abonadas", "No son personas usuarias"], "e": "Se les aplican las normas hasta donde alcance su responsabilidad durante su permanencia.", "r": "Reglamento GK art. 8.2"}, {"id": "gett20q14", "q": "¿Puede ser abonada de Getxo Kirolak una persona que no reside en Getxo?", "o": ["Sí, toda persona, residente o no en Getxo, que formalice su inscripción y sea admitida", "No, solo las empadronadas en Getxo", "Solo si trabaja en Getxo", "Solo con abono familiar"], "e": "Debe tener el carné de abono y estar al corriente de pago (art. 9.1).", "r": "Reglamento GK art. 9.1"}, {"id": "gett20q15", "q": "El carné de abono es:", "o": ["Personal e intransferible", "Transferible a familiares", "Transferible con autorización", "Válido para cualquier miembro del club"], "e": "Ceder el carné a otra persona es una infracción grave (art. 27.2.4).", "r": "Reglamento GK arts. 9.5 y 27.2.4"}, {"id": "gett20q16", "q": "La persona usuaria ocasional, para acceder, debe adquirir:", "o": ["Una entrada de día, que permite el acceso a las instalaciones de uso libre y la reserva de instalaciones", "El carné de deportista", "El abono familiar", "Un bono mensual"], "e": "Art. 10.1.", "r": "Reglamento GK art. 10.1"}, {"id": "gett20q17", "q": "Si un colectivo autorizado causa desperfectos en una instalación, la responsabilidad es de:", "o": ["La entidad a la que se concedió el uso, sin perjuicio de la responsabilidad individual", "Getxo Kirolak", "El Ayuntamiento", "Solo la persona que causó el daño"], "e": "Debe notificarlo por escrito, cuanto antes, en la recepción (art. 11.4).", "r": "Reglamento GK art. 11.4"}, {"id": "gett20q18", "q": "¿En qué meses el alumnado de los centros escolares de Getxo utiliza gratuitamente las instalaciones deportivas municipales?", "o": ["De octubre a junio", "De septiembre a junio", "Todo el año", "De enero a diciembre"], "e": "Con un calendario de actividades escolares acordado con los centros antes del curso (art. 11.A.2).", "r": "Reglamento GK art. 11.A.2"}, {"id": "gett20q19", "q": "El periodo general de entrenamientos de las entidades deportivas va:", "o": ["Del 1 de septiembre al 1 de junio", "Del 1 de octubre al 30 de junio", "Del 15 de septiembre al 15 de junio", "Todo el año"], "e": "La asociación que necesite otro periodo puede solicitarlo (art. 11.B.5).", "r": "Reglamento GK art. 11.B.5"}, {"id": "gett20q20", "q": "En partidos de competición oficial, ¿a cuántos deportistas del equipo visitante autoriza Getxo Kirolak el acceso gratuito en modalidades de pabellón?", "o": ["16, y 30 en campos exteriores (incluido el personal técnico y directivo)", "12 en pabellón y 22 en campos exteriores", "20 en pabellón y 25 en campos exteriores", "16 en cualquier modalidad"], "e": "Art. 11.B.9.", "r": "Reglamento GK art. 11.B.9"}, {"id": "gett20q21", "q": "Los clubes que quieran cobrar entrada para presenciar sus partidos necesitan:", "o": ["Autorización por escrito de la presidencia de Getxo Kirolak", "Comunicarlo a la recepción", "Autorización del Pleno municipal", "Nada, es libre"], "e": "Art. 11.B.10.", "r": "Reglamento GK art. 11.B.10"}, {"id": "gett20q22", "q": "Si se extravía el carné de abono, hay que comunicarlo en las oficinas de atención al público en el plazo de:", "o": ["Tres días", "Diez días", "Un mes", "24 horas"], "e": "Si no se comunica y otra persona lo usa, se puede sancionar a la titular salvo que acredite el hurto o robo con la denuncia.", "r": "Reglamento GK art. 13.1.d"}, {"id": "gett20q23", "q": "¿Cuál de estos servicios es gratuito para las personas usuarias según el art. 14?", "o": ["Las salas de estudio, los vestuarios y la pista de atletismo", "El gimnasio de fitness", "Las pistas de pádel", "El servicio de salud"], "e": "También las salas polivalentes de frontones, la zona de juegos exteriores, el circuito de cross y el velódromo. El resto se paga según la ordenanza fiscal.", "r": "Reglamento GK art. 14.1.a"}, {"id": "gett20q24", "q": "¿Cuánto tiempo al día se puede reservar como máximo una instalación destinada a una misma modalidad deportiva?", "o": ["2 horas, salvo actividades programadas por Getxo Kirolak", "1 hora", "3 horas", "No hay límite"], "e": "Superar ese periodo máximo es una infracción grave (art. 27.2.5).", "r": "Reglamento GK art. 15.2"}, {"id": "gett20q25", "q": "Si una instalación está en mal estado o el tiempo impide la práctica deportiva, la devolución o el cambio de la reserva se pide:", "o": ["En los dos días hábiles posteriores a la fecha prevista de uso", "En los diez días siguientes", "El mismo día", "En el plazo de un mes"], "e": "La reserva sellada para canjear tiene validez durante los 6 meses siguientes a su emisión.", "r": "Reglamento GK art. 15.6"}, {"id": "gett20q26", "q": "¿Con cuánta antelación máxima puede anularse la reserva de una instalación?", "o": ["Con un máximo de 2 días de antelación", "Con 24 horas de antelación", "Con una semana", "No se puede anular"], "e": "Art. 15.7.", "r": "Reglamento GK art. 15.7"}, {"id": "gett20q27", "q": "En el sistema de reservas por quincenas, ¿cuántas reservas puede hacer cada carné de abono en la quincena en curso?", "o": ["Dos", "Una", "Tres", "Cuatro"], "e": "También dos para la quincena siguiente.", "r": "Reglamento GK art. 17.1"}, {"id": "gett20q28", "q": "Los menores de 16 años pueden usar las pistas sin reserva previa cuando:", "o": ["Han pasado 15 minutos desde la hora de inicio sin que la instalación haya sido reservada", "Van acompañados de una persona adulta", "Es fin de semana", "Lo autoriza la recepción"], "e": "Art. 17.1.4.", "r": "Reglamento GK art. 17.1.4"}, {"id": "gett20q29", "q": "Para inscribirse en un curso deportivo de Getxo Kirolak es necesario:", "o": ["Ser persona abonada", "Estar empadronado en Getxo", "Ser mayor de 16 años", "Pertenecer a un club"], "e": "Se llama cursillista a quien se inscribe en un curso (art. 18.1).", "r": "Reglamento GK art. 18.1"}, {"id": "gett20q30", "q": "¿Qué dos programas de cursos ofrece Getxo Kirolak cada año?", "o": ["Uno de temporada (octubre a junio) y otro de verano (julio y agosto)", "Uno de invierno y otro de primavera", "Uno trimestral y otro anual", "Uno escolar y otro de adultos"], "e": "Para las nuevas inscripciones se celebra un sorteo (art. 19.2).", "r": "Reglamento GK art. 19.1"}, {"id": "gett20q31", "q": "La baja voluntaria de un curso, para que no se cobre el siguiente periodo, debe notificarse:", "o": ["Por escrito, con una antelación mínima de 7 días antes del inicio del servicio", "Por teléfono el mismo día", "Con un mes de antelación", "No hace falta, la baja es automática"], "e": "Quien no pague la tasa 7 días antes del siguiente mes puede perder la plaza.", "r": "Reglamento GK art. 19.4 a 19.6"}, {"id": "gett20q32", "q": "Cuando hay una plaza libre en un curso, Getxo Kirolak avisa a la persona de la lista de espera con tres intentos en tres horas, y la persona tiene para aceptar o renunciar:", "o": ["Una hora como máximo", "24 horas", "Tres días", "Diez minutos"], "e": "Si renuncia, pasa al último lugar de la lista de espera.", "r": "Reglamento GK art. 20.4 y 20.5"}, {"id": "gett20q33", "q": "¿Qué animales pueden entrar en las instalaciones?", "o": ["Solo los perros lazarillos debidamente identificados", "Cualquier perro con correa", "Ninguno, sin excepción", "Los animales de compañía pequeños"], "e": "Art. 22.5.", "r": "Reglamento GK art. 22.5"}, {"id": "gett20q34", "q": "¿Hasta qué edad pueden los niños y niñas acceder al vestuario del sexo opuesto acompañados por una persona mayor de edad?", "o": ["Menores de siete años", "Menores de diez años", "Menores de cinco años", "Menores de doce años"], "e": "Salvo que existan vestuarios destinados a ese fin.", "r": "Reglamento GK art. 23.2"}, {"id": "gett20q35", "q": "Los objetos que quedan en las taquillas y no se recogen se guardan en depósito durante:", "o": ["Un mes, y después se entregan a la Policía Municipal de Getxo", "Una semana", "Tres meses", "Un año"], "e": "Getxo Kirolak no responde de los objetos depositados en las taquillas.", "r": "Reglamento GK art. 24.6"}, {"id": "gett20q36", "q": "¿Hasta qué edad pueden usar el parque infantil cubierto de Fadura y cuál es su capacidad máxima?", "o": ["Hasta 8 años, con una capacidad máxima de 25 menores", "Hasta 10 años, con 30 menores", "Hasta 6 años, con 20 menores", "Hasta 12 años, con 25 menores"], "e": "En el módulo central no pueden medir más de 1,30 metros.", "r": "Reglamento GK art. 26.3"}, {"id": "gett20q37", "q": "En las piscinas de Getxo Kirolak, ¿cuál de estas normas es obligatoria?", "o": ["Ducharse antes de acceder a la piscina", "Usar gorro de baño", "Usar chancletas", "Usar gafas de natación"], "e": "El gorro y las chancletas son recomendables, no obligatorios.", "r": "Reglamento GK art. 26.4"}, {"id": "gett20q38", "q": "¿Cuál es el horario de verano de las piscinas exteriores?", "o": ["Del 15 de junio al 15 de septiembre", "Del 1 de junio al 31 de agosto", "Del 1 de julio al 31 de agosto", "Del 24 de junio al 15 de septiembre"], "e": "Salvo que Getxo Kirolak decida modificar el periodo. Las condiciones climatológicas adversas no dan derecho a devolución.", "r": "Reglamento GK art. 26.5"}, {"id": "gett20q39", "q": "Para inscribirse en el gimnasio de fitness-musculación, la edad mínima general es de:", "o": ["Más de 16 años", "Más de 14 años", "Más de 18 años", "Más de 12 años"], "e": "En casos excepcionales, el personal técnico puede aceptar a menores de esa edad.", "r": "Reglamento GK art. 26.8"}, {"id": "gett20q40", "q": "En horas de máxima afluencia, el uso de las máquinas cardiovasculares del gimnasio se limita a:", "o": ["20 minutos por persona como máximo", "30 minutos", "15 minutos", "45 minutos"], "e": "Art. 26.8.f.", "r": "Reglamento GK art. 26.8.f"}, {"id": "gett20q41", "q": "¿Cómo se clasifican las infracciones del reglamento?", "o": ["Leves, graves y muy graves", "Leves y graves", "Administrativas y penales", "Simples y cualificadas"], "e": "Art. 27.", "r": "Reglamento GK art. 27"}, {"id": "gett20q42", "q": "Causar daños voluntariamente o por negligencia en las instalaciones por valor de entre 200 y 600 euros es una infracción:", "o": ["Grave", "Leve", "Muy grave", "No es infracción, solo hay que pagar el daño"], "e": "Los daños de 600 euros o más son infracción muy grave.", "r": "Reglamento GK art. 27.2.1"}, {"id": "gett20q43", "q": "Utilizar una instalación deportiva municipal para impartir clases con finalidad de beneficio particular es una infracción:", "o": ["Muy grave", "Grave", "Leve", "No está prohibido"], "e": "También es muy grave el tráfico de drogas o el incumplimiento de los convenios firmados con Getxo Kirolak.", "r": "Reglamento GK art. 27.3.3"}, {"id": "gett20q44", "q": "¿Qué multa corresponde a una infracción grave?", "o": ["De 751 a 1.500 euros", "De 1 a 750 euros", "De 1.501 a 3.000 euros", "Hasta 3.000 euros"], "e": "Leves: de 1 a 750 euros; muy graves: de 1.501 a 3.000 euros.", "r": "Reglamento GK art. 28"}, {"id": "gett20q45", "q": "¿En qué plazo prescriben las infracciones graves del reglamento?", "o": ["Dos años", "Seis meses", "Tres años", "Un año"], "e": "Las leves prescriben a los seis meses y las muy graves a los tres años.", "r": "Reglamento GK art. 30"}, {"id": "gett20q46", "q": "¿Quién dicta la resolución en el procedimiento sancionador por infracciones graves o muy graves y qué recurso cabe?", "o": ["La Presidencia, en diez días desde la propuesta, y cabe recurso de alzada ante el Consejo Rector", "El Consejo Rector, y cabe recurso de reposición", "El Alcalde, y cabe recurso contencioso", "La dirección, y cabe recurso de alzada ante el Pleno"], "e": "Si no hay resolución en seis meses desde la iniciación, el procedimiento caduca.", "r": "Reglamento GK art. 31.8"}, {"id": "gett20q47", "q": "En el procedimiento sancionador por infracciones graves o muy graves, ¿de qué plazo disponen las personas interesadas para alegar tras la iniciación?", "o": ["Quince días", "Diez días", "Cinco días", "Un mes"], "e": "En el procedimiento para infracciones leves el plazo es de 10 días.", "r": "Reglamento GK arts. 31.4 y 32.2"}]}]});
